window.PAPERS_DATA = {
    "darkir": "\n<article class=\"paper-article\">\n    <div class=\"paper-reader-toolbar\">\n        <div class=\"paper-toolbar-group\">\n            <span style=\"font-weight: 700; color: #38BDF8; font-size: 0.85rem;\">CVPR 2025 Paper Reader (Full Translation)</span>\n            <button class=\"paper-tool-btn btn-col-toggle\" onclick=\"togglePaperColumns('darkir')\">\ud83d\udcc4 Ch\u1ebf \u0110\u1ed9 1 C\u1ed9t (D\u1ecdc)</button>\n        </div>\n        <div class=\"paper-toolbar-group\">\n            <a href=\"papers/darkir.html\" target=\"_blank\" class=\"paper-tool-btn\">\u2197\ufe0f M\u1edf Trang \u0110\u1ed9c L\u1eadp To\u00e0n M\u00e0n H\u00ecnh</a>\n            <button class=\"paper-tool-btn\" onclick=\"closePaperReader('darkir')\">\u2715 \u0110\u00f3ng B\u00e0i B\u00e1o</button>\n        </div>\n    </div>\n\n    <header class=\"paper-header\">\n        <span class=\"paper-venue-badge\">IEEE / CVF CVPR 2025 \u2022 ORAL PRESENTATION \u2022 MAIN REFERENCE</span>\n        <h1 class=\"paper-title\">DarkIR: Ph\u1ee5c H\u1ed3i \u1ea2nh Thi\u1ebfu S\u00e1ng \u0110a Nhi\u1ec7m B\u1ec1n V\u1eefng</h1>\n        <h2 class=\"paper-title-en\">DarkIR: Robust Low-Light Image Restoration</h2>\n        <div class=\"paper-authors\">\n            <strong>Daniel Feijoo</strong><sup>1\u2020</sup>, <strong>Juan C. Benito</strong><sup>1</sup>, <strong>Alvaro Garcia</strong><sup>1</sup>, <strong>Marcos V. Conde</strong><sup>1,2\u2020</sup>\n        </div>\n        <div class=\"paper-affiliations\">\n            <sup>1</sup> Cidaut AI, Valladolid, T\u00e2y Ban Nha<br>\n            <sup>2</sup> Computer Vision Lab, \u0110\u1ea1i h\u1ecdc W\u00fcrzburg, CHLB \u0110\u1ee9c<br>\n            <sup>\u2020</sup> T\u00e1c gi\u1ea3 li\u00ean h\u1ec7: {danfei, marcos.conde}@cidaut.es\n        </div>\n        <div class=\"paper-links-row\">\n            <a href=\"https://github.com/cidautai/DarkIR\" target=\"_blank\" class=\"paper-ext-link\">\ud83d\udcbb M\u00e3 Ngu\u1ed3n Ch\u00ednh Th\u1ee9c: github.com/cidautai/DarkIR</a>\n            <a href=\"../papers/Feijoo_DarkIR_Robust_Low-Light_Image_Restoration_CVPR_2025_paper.pdf\" target=\"_blank\" class=\"paper-ext-link\">\ud83d\udcd1 T\u1ea3i File PDF K\u1ef7 Y\u1ebfu CVPR (9.2 MB)</a>\n        </div>\n    </header>\n\n    <div class=\"paper-abstract-box\">\n        <div class=\"paper-abstract-title\">T\u00f3m T\u1eaft B\u00e0i B\u00e1o (Abstract)</div>\n        <p class=\"paper-abstract-text\">\n            Ch\u1ee5p \u1ea3nh trong b\u00f3ng \u0111\u00eam ho\u1eb7c trong \u0111i\u1ec1u ki\u1ec7n \u00e1nh s\u00e1ng c\u1ef1c y\u1ebfu th\u01b0\u1eddng xuy\u00ean ph\u1ea3i ch\u1ecbu \u0111\u1ef1ng \u0111\u1ed3ng th\u1eddi ba d\u1ea1ng suy tho\u00e1i nghi\u00eam tr\u1ecdng: <strong>nhi\u1ec5u c\u1ea3m bi\u1ebfn (noise)</strong>, <strong>thi\u1ebfu s\u00e1ng (low-light)</strong> v\u00e0 <strong>m\u1edd nh\u00f2e (blurring)</strong> do m\u00f4i tr\u01b0\u1eddng thi\u1ebfu quang t\u1eed v\u00e0 vi\u1ec7c bu\u1ed9c ph\u1ea3i m\u1edf m\u00e0n tr\u1eadp ph\u01a1i s\u00e1ng l\u00e2u (long exposure). M\u1eb7c d\u00f9 hai b\u00e0i to\u00e1n Kh\u1eed m\u1edd (Deblurring) v\u00e0 T\u0103ng c\u01b0\u1eddng \u1ea3nh thi\u1ebfu s\u00e1ng (Low-Light Image Enhancement - LLIE) c\u00f3 m\u1ed1i quan h\u1ec7 ph\u1ee5 thu\u1ed9c h\u1eefu c\u01a1 ch\u1eb7t ch\u1ebd trong c\u00e1c \u0111i\u1ec1u ki\u1ec7n n\u00e0y, h\u1ea7u h\u1ebft c\u00e1c c\u00f4ng tr\u00ecnh nghi\u00ean c\u1ee9u ph\u1ee5c h\u1ed3i \u1ea3nh hi\u1ec7n nay l\u1ea1i ti\u1ebfp c\u1eadn v\u00e0 gi\u1ea3i quy\u1ebft ch\u00fang m\u1ed9t c\u00e1ch ri\u00eang r\u1ebd, r\u1eddi r\u1ea1c. Trong b\u00e0i b\u00e1o n\u00e0y, ch\u00fang t\u00f4i \u0111\u1ec1 xu\u1ea5t m\u1ed9t ki\u1ebfn tr\u00fac m\u1ea1ng n\u01a1-ron s\u00e2u hi\u1ec7u qu\u1ea3 v\u00e0 b\u1ec1n v\u1eefng ph\u1ee5c v\u1ee5 b\u00e0i to\u00e1n <em>ph\u1ee5c h\u1ed3i \u1ea3nh thi\u1ebfu s\u00e1ng \u0111a nhi\u1ec7m th\u1ed1ng nh\u1ea5t (multi-task low-light image restoration)</em>. Thay v\u00ec ch\u1ea1y theo xu h\u01b0\u1edbng s\u1eed d\u1ee5ng c\u00e1c m\u00f4 h\u00ecnh d\u1ef1a tr\u00ean Transformer c\u1ed3ng k\u1ec1nh, ch\u00fang t\u00f4i \u0111\u1ec1 xu\u1ea5t c\u00e1c c\u01a1 ch\u1ebf ch\u00fa \u00fd m\u1edbi nh\u1eb1m m\u1edf r\u1ed9ng tr\u01b0\u1eddng ti\u1ebfp nh\u1eadn (receptive field) c\u1ee7a c\u00e1c m\u1ea1ng CNN hi\u1ec7u n\u0103ng cao. Ph\u01b0\u01a1ng ph\u00e1p c\u1ee7a ch\u00fang t\u00f4i c\u1eaft gi\u1ea3m tri\u1ec7t \u0111\u1ec3 chi ph\u00ed t\u00ednh to\u00e1n c\u1ea3 v\u1ec1 s\u1ed1 l\u01b0\u1ee3ng tham s\u1ed1 (Parameters) l\u1eabn s\u1ed1 ph\u00e9p t\u00ednh t\u00edch l\u0169y nh\u00e2n (MAC operations) so v\u1edbi c\u00e1c gi\u1ea3i thu\u1eadt ti\u1ec1n nhi\u1ec7m. M\u00f4 h\u00ecnh c\u1ee7a ch\u00fang t\u00f4i, mang t\u00ean <strong>DarkIR</strong>, thi\u1ebft l\u1eadp k\u1ef7 l\u1ee5c State-of-the-Art (SOTA) m\u1edbi tr\u00ean c\u00e1c b\u1ed9 d\u1eef li\u1ec7u chu\u1ea9n danh ti\u1ebfng g\u1ed3m LOLBlur, LOLv2 v\u00e0 Real-LOLBlur, \u0111\u1ed3ng th\u1eddi ch\u1ee9ng minh kh\u1ea3 n\u0103ng t\u1ed5ng qu\u00e1t h\u00f3a v\u01b0\u1ee3t tr\u1ed9i tr\u00ean c\u00e1c b\u1ee9c \u1ea3nh ch\u1ee5p \u0111\u00eam th\u1ef1c t\u1ebf ngo\u00e0i \u0111\u1eddi s\u1ed1ng.\n        </p>\n    </div>\n\n    <!-- Figure 1 -->\n    <figure class=\"paper-figure full-width\">\n        <img src=\"assets/images/papers/darkir/fig_1_p1.png\" alt=\"DarkIR Figure 1 Teaser\">\n        <figcaption class=\"paper-figcaption\">\n            <strong>H\u00ecnh 1: \u0110\u1ed9ng l\u1ef1c nghi\u00ean c\u1ee9u c\u1ee7a DarkIR.</strong> C\u00e1c ph\u01b0\u01a1ng ph\u00e1p t\u0103ng c\u01b0\u1eddng \u1ea3nh thi\u1ebfu s\u00e1ng (LLIE) v\u00e0 ph\u1ee5c h\u1ed3i \u1ea3nh tr\u01b0\u1edbc \u0111\u00e2y ho\u00e0n to\u00e0n kh\u00f4ng b\u1ec1n v\u1eefng tr\u01b0\u1edbc s\u1ef1 thay \u0111\u1ed5i \u0111\u1ed3ng th\u1eddi c\u1ee7a \u0111\u1ed9 m\u1edd nh\u00f2e v\u00e0 m\u1ee9c \u0111\u1ed9 chi\u1ebfu s\u00e1ng. H\u00e0ng tr\u00ean: <em>RetinexFormer [3]</em> th\u1ea5t b\u1ea1i n\u1eb7ng n\u1ec1 khi xu\u1ea5t hi\u1ec7n v\u1ec7t m\u1edd nh\u00f2e chuy\u1ec3n \u0111\u1ed9ng. H\u00e0ng d\u01b0\u1edbi: <em>LEDNet [65]</em> th\u1ea5t b\u1ea1i khi g\u1eb7p nhi\u1ec5u h\u1ea1t c\u1ea3m bi\u1ebfn d\u00e0y \u0111\u1eb7c. M\u00f4 h\u00ecnh \u0111a nhi\u1ec7m <strong>DarkIR (\u0110\u1ec1 xu\u1ea5t)</strong> c\u1ee7a ch\u00fang t\u00f4i c\u00f3 kh\u1ea3 n\u0103ng ph\u1ee5c h\u1ed3i ho\u00e0n h\u1ea3o c\u00e1c b\u1ee9c \u1ea3nh ch\u1ee5p \u0111\u00eam th\u1ef1c t\u1ebf d\u01b0\u1edbi nhi\u1ec1u \u0111i\u1ec1u ki\u1ec7n chi\u1ebfu s\u00e1ng, nhi\u1ec5u h\u1ea1t v\u00e0 m\u1edd nh\u00f2e bi\u1ebfn thi\u00ean ph\u1ee9c t\u1ea1p. (Nh\u1ea5p chu\u1ed9t v\u00e0o \u1ea3nh \u0111\u1ec3 ph\u00f3ng to chi ti\u1ebft).\n        </figcaption>\n    </figure>\n\n    <div class=\"paper-content-columns\">\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">1.</span> Gi\u1edbi Thi\u1ec7u (Introduction)</h3>\n        <p>\n            Trong \u0111i\u1ec1u ki\u1ec7n ch\u1ee5p \u1ea3nh ban \u0111\u00eam ho\u1eb7c thi\u1ebfu s\u00e1ng, ch\u00fang ta c\u00f3 th\u1ec3 m\u00f4 h\u00ecnh h\u00f3a qu\u00e1 tr\u00ecnh h\u00ecnh th\u00e0nh \u1ea3nh quan s\u00e1t b\u1ecb suy tho\u00e1i theo ph\u01b0\u01a1ng tr\u00ecnh v\u1eadt l\u00fd quang h\u1ecdc sau:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$\\mathbf{y} = \\gamma(\\mathbf{x} \\otimes \\mathbf{k}) + \\mathbf{n}$$</div>\n            <span class=\"paper-equation-num\">(1)</span>\n        </div>\n        <p>\n            Trong \u0111\u00f3: $\\mathbf{y}$ l\u00e0 b\u1ee9c \u1ea3nh t\u1ed1i m\u1edd quan s\u00e1t \u0111\u01b0\u1ee3c thu t\u1eeb thi\u1ebft b\u1ecb; $\\mathbf{x}$ \u0111\u1ea1i di\u1ec7n cho khung c\u1ea3nh th\u1ef1c t\u1ebf l\u00fd t\u01b0\u1edfng kh\u00f4ng b\u1ecb nhi\u1ec5u \u0111\u1ed9ng; $\\mathbf{k}$ \u0111\u1ea1i di\u1ec7n cho h\u00e0m t\u00e1n x\u1ea1 \u0111i\u1ec3m (Point-Spread Function - PSF) g\u00e2y m\u1edd nh\u00f2e \u1ed1ng k\u00ednh do chuy\u1ec3n \u0111\u1ed9ng rung l\u1eafc; $\\mathbf{n}$ l\u00e0 th\u00e0nh ph\u1ea7n nhi\u1ec5u c\u1ea3m bi\u1ebfn c\u1ed9ng g\u1ed9p; v\u00e0 $\\gamma(\\cdot)$ l\u00e0 h\u00e0m phi tuy\u1ebfn th\u1ec3 hi\u1ec7n s\u1ef1 ki\u1ec3m so\u00e1t d\u1ea3i \u0111\u1ed9ng v\u00e0 \u0111\u1ed9 b\u00e3o h\u00f2a \u0111i\u1ec3m \u1ea3nh (dynamic range & pixel saturation clipping). K\u00fd hi\u1ec7u $\\otimes$ bi\u1ec3u di\u1ec5n to\u00e1n t\u1eed t\u00edch ch\u1eadp kh\u00f4ng gian hai chi\u1ec1u.\n        </p>\n        <p>\n            So v\u1edbi \u0111i\u1ec1u ki\u1ec7n ban ng\u00e0y \u0111\u1ea7y \u0111\u1ee7 \u00e1nh s\u00e1ng, khi ch\u1ee5p thi\u1ebfu s\u00e1ng, nhi\u1ec5u c\u1ea3m bi\u1ebfn (bao g\u1ed3m nhi\u1ec5u h\u1ea1t photon shot noise tu\u00e2n theo ph\u00e2n ph\u1ed1i Poisson v\u00e0 nhi\u1ec5u \u0111\u1ecdc \u0111i\u1ec7n t\u1eed read noise tu\u00e2n theo ph\u00e2n ph\u1ed1i Gaussian) t\u0103ng v\u1ecdt l\u00ean m\u1ed9t c\u00e1ch \u0111\u00e1ng k\u1ec3. Trong nhi\u1ebfp \u1ea3nh ban \u0111\u00eam, m\u00e1y \u1ea3nh th\u01b0\u1eddng s\u1eed d\u1ee5ng th\u1eddi gian ph\u01a1i s\u00e1ng d\u00e0i (t\u1ed1c \u0111\u1ed9 m\u00e0n tr\u1eadp ch\u1eadm) nh\u1eb1m cho ph\u00e9p c\u1ea3m bi\u1ebfn thu nh\u1eadn \u0111\u01b0\u1ee3c nhi\u1ec1u quang t\u1eed \u00e1nh s\u00e1ng kh\u1ea3 d\u1ee5ng h\u01a1n. Tuy nhi\u00ean, vi\u1ec7c ph\u01a1i s\u00e1ng k\u00e9o d\u00e0i t\u1ea5t y\u1ebfu d\u1eabn \u0111\u1ebfn c\u00e1c v\u1ec7t b\u00f3ng ma (ghosting) v\u00e0 hi\u1ec7n t\u01b0\u1ee3ng m\u1edd nh\u00f2e chuy\u1ec3n \u0111\u1ed9ng (motion blur artifacts) do chuy\u1ec3n \u0111\u1ed9ng c\u1ee7a camera v\u00e0 v\u1eadt th\u1ec3.\n        </p>\n        <p>\n            Nh\u1eefng d\u1ea1ng suy tho\u00e1i h\u00ecnh \u1ea3nh n\u00e0y \u0111\u1eb7c bi\u1ec7t tr\u1ea7m tr\u1ecdng tr\u00ean \u0111i\u1ec7n tho\u1ea1i th\u00f4ng minh (smartphones), b\u1edfi v\u00ec thi\u1ebft b\u1ecb di \u0111\u1ed9ng c\u00f3 kh\u1ea9u \u0111\u1ed9 \u1ed1ng k\u00ednh c\u1ed1 \u0111\u1ecbnh v\u00e0 h\u1ec7 th\u1ed1ng quang h\u1ecdc r\u1ea5t h\u1ea1n ch\u1ebf v\u1ec1 m\u1eb7t k\u00edch th\u01b0\u1edbc v\u1eadt l\u00fd. V\u00ec nh\u1eefng l\u00fd do n\u00e0y, b\u00e0i to\u00e1n \u0111\u1ed3ng th\u1eddi n\u00e2ng cao \u0111\u1ed9 s\u00e1ng v\u00e0 kh\u1eed m\u1edd (joint low-light enhancement and deblurring) \u0111\u00f3ng vai tr\u00f2 s\u1ed1ng c\u00f2n trong l\u0129nh v\u1ef1c nhi\u1ebfp \u1ea3nh t\u00ednh to\u00e1n di \u0111\u1ed9ng (mobile computational photography) [12, 65] \u2014 xem c\u00e1c m\u1eabu minh h\u1ecda t\u1ea1i <strong>H\u00ecnh 1</strong>.\n        </p>\n        <p>\n            Trong b\u1ea5t k\u1ef3 ho\u00e0n c\u1ea3nh ch\u1ee5p th\u1ef1c t\u1ebf n\u00e0o, b\u1ee9c \u1ea3nh thu nh\u1eadn lu\u00f4n lu\u00f4n mang m\u1ed9t m\u1ee9c \u0111\u1ed9 nhi\u1ec5u v\u00e0 m\u1edd nh\u1ea5t \u0111\u1ecbnh [13]. N\u1ebfu d\u00f9ng ch\u00e2n m\u00e1y \u1ea3nh c\u1ed1 \u0111\u1ecbnh (tripod) \u0111\u1ec3 ch\u1ee5p \u1ea3nh t\u0129nh, ch\u00fang ta c\u00f3 th\u1ec3 gi\u1ea3m \u0111\u00e1ng k\u1ec3 \u0111\u1ed9 m\u1edd. H\u01a1n n\u1eefa, n\u1ebfu c\u00f3 h\u1ec7 th\u1ed1ng chi\u1ebfu s\u00e1ng nh\u00e2n t\u1ea1o ph\u00f9 h\u1ee3p, nhi\u1ec5u h\u1ea1t c\u0169ng c\u00f3 th\u1ec3 \u0111\u01b0\u1ee3c ki\u1ec1m ch\u1ebf [1, 20]. Tuy nhi\u00ean, ng\u00e0y nay ph\u1ea7n l\u1edbn c\u00e1c b\u1ee9c \u1ea3nh \u0111\u1ec1u \u0111\u01b0\u1ee3c ch\u1ee5p b\u1eb1ng tay c\u1ea7m \u0111i\u1ec7n tho\u1ea1i di \u0111\u1ed9ng (handheld smartphones). Do k\u00edch th\u01b0\u1edbc c\u1ea3m bi\u1ebfn v\u00e0 quang h\u1ecdc si\u00eau nh\u1ecf, c\u00e1c nh\u00e0 s\u1ea3n xu\u1ea5t bu\u1ed9c ph\u1ea3i \u00e1p d\u1ee5ng c\u00e1c b\u1ed9 x\u1eed l\u00fd t\u00edn hi\u1ec7u h\u00ecnh \u1ea3nh (ISPs) v\u00f4 c\u00f9ng ph\u1ee9c t\u1ea1p [10, 12] so v\u1edbi c\u00e1c d\u00f2ng m\u00e1y \u1ea3nh chuy\u00ean nghi\u1ec7p kh\u00f4ng g\u01b0\u01a1ng l\u1eadt (DSLM).\n        </p>\n        <p>\n            Ch\u1ea5t l\u01b0\u1ee3ng \u1ea3nh \u0111i\u1ec7n tho\u1ea1i hi\u1ec7n nay v\u1eabn c\u00f2n kho\u1ea3ng c\u00e1ch xa so v\u1edbi ti\u00eau chu\u1ea9n m\u00e1y \u1ea3nh DSLM. R\u1ea5t may m\u1eafn, c\u00e1c nghi\u00ean c\u1ee9u g\u1ea7n \u0111\u00e2y trong th\u1ecb gi\u00e1c m\u00e1y t\u00ednh c\u1ea5p th\u1ea5p (low-level vision) v\u00e0 nhi\u1ebfp \u1ea3nh t\u00ednh to\u00e1n \u0111ang t\u1eebng b\u01b0\u1edbc thu h\u1eb9p kho\u1ea3ng c\u00e1ch n\u00e0y. T\u0103ng c\u01b0\u1eddng \u1ea3nh thi\u1ebfu s\u00e1ng (LLIE) [3, 14, 30, 31, 45, 64], kh\u1eed m\u1edd \u1ea3nh [21, 25, 38, 40] v\u00e0 n\u00e2ng c\u1ea5p \u1ea3nh ch\u1ee5p \u0111\u00eam [42, 65] l\u00e0 nh\u1eefng ch\u1ee7 \u0111\u1ec1 thu h\u00fat s\u1ef1 quan t\u00e2m l\u1edbn.\n        </p>\n        <p>\n            V\u00ed d\u1ee5, vi\u1ec7c tri\u1ec7t ti\u00eau hi\u1ec7n t\u01b0\u1ee3ng m\u1edd nh\u00f2e do run tay (hand tremor) \u0111\u00e3 \u0111\u01b0\u1ee3c nghi\u00ean c\u1ee9u k\u1ef9 l\u01b0\u1ee1ng, ngay c\u1ea3 trong k\u1ecbch b\u1ea3n \u00e1nh s\u00e1ng y\u1ebfu [29, 62]. D\u1eabu v\u1eady, trong \u0111a s\u1ed1 tr\u01b0\u1eddng h\u1ee3p, c\u00e1c t\u00e1c v\u1ee5 n\u00e0y \u0111\u1ec1u \u0111\u01b0\u1ee3c gi\u1ea3i quy\u1ebft m\u1ed9t c\u00e1ch ri\u00eang r\u1ebd. H\u1ec7 qu\u1ea3 l\u00e0: c\u00e1c ph\u01b0\u01a1ng ph\u00e1p kh\u1eed m\u1edd SOTA hi\u1ec7n nay kh\u00f4ng th\u1ec3 t\u1ed5ng qu\u00e1t h\u00f3a sang \u1ea3nh ch\u1ee5p \u0111\u00eam, v\u00e0 ng\u01b0\u1ee3c l\u1ea1i, c\u00e1c ph\u01b0\u01a1ng ph\u00e1p t\u0103ng s\u00e1ng t\u1ed1t nh\u1ea5t c\u0169ng kh\u00f4ng th\u1ec3 l\u00e0m gi\u1ea3m \u0111\u01b0\u1ee3c c\u00e1c v\u1ec7t m\u1edd nh\u00f2e nghi\u00eam tr\u1ecdng. \u0110\u00e2y l\u00e0 m\u1ed9t h\u1ea1n ch\u1ebf mang t\u00ednh h\u1ec7 th\u1ed1ng, b\u1edfi v\u00ec ng\u01b0\u1eddi d\u00f9ng s\u1ebd ph\u1ea3i tinh ch\u1ec9nh, l\u01b0u tr\u1eef v\u00e0 th\u1ef1c thi n\u1ed1i ti\u1ebfp nhi\u1ec1u m\u00f4 h\u00ecnh chuy\u00ean bi\u1ec7t cho t\u1eebng t\u00e1c v\u1ee5 (sequential cascading), g\u00e2y c\u1ea3n tr\u1edf l\u1edbn khi tri\u1ec3n khai v\u00e0o c\u00e1c \u1ee9ng d\u1ee5ng th\u1ef1c t\u1ebf th\u1ebf gi\u1edbi th\u1ef1c.\n        </p>\n        <p>\n            Theo hi\u1ec3u bi\u1ebft t\u1ed1t nh\u1ea5t c\u1ee7a ch\u00fang t\u00f4i, c\u00f3 r\u1ea5t \u00edt c\u00f4ng tr\u00ecnh nghi\u00ean c\u1ee9u h\u01b0\u1edbng t\u1edbi vi\u1ec7c gi\u1ea3i quy\u1ebft \u0111\u1ed3ng th\u1eddi c\u1ea3 ba b\u00e0i to\u00e1n (kh\u1eed nhi\u1ec5u, kh\u1eed m\u1edd v\u00e0 t\u0103ng s\u00e1ng thi\u1ebfu s\u00e1ng) theo ph\u01b0\u01a1ng ph\u00e1p \u0111\u1ea7u-cu\u1ed1i t\u00edch h\u1ee3p (joint end-to-end manner) [6, 33, 63, 65], trong \u0111\u00f3 n\u1ed5i b\u1eadt nh\u1ea5t l\u00e0 c\u00f4ng tr\u00ecnh LEDNet [65]. Ch\u00fang t\u00f4i t\u1eadp trung v\u00e0o h\u01b0\u1edbng nghi\u00ean c\u1ee9u n\u00e0y, b\u1edfi v\u00ec vi\u1ec7c khai th\u00e1c m\u1ed1i t\u01b0\u01a1ng quan b\u1ea3n ch\u1ea5t gi\u1eefa c\u00e1c d\u1ea1ng suy tho\u00e1i cho ph\u00e9p ch\u00fang t\u00f4i \u0111\u1ea1t \u0111\u01b0\u1ee3c hi\u1ec7u n\u0103ng cao nh\u1ea5t v\u1ec1 \u0111\u1ed9 trung th\u1ef1c t\u00e1i t\u1ea1o \u1ea3nh, t\u00ednh kh\u1ea3 d\u1ee5ng v\u00e0 hi\u1ec7u qu\u1ea3 t\u00ednh to\u00e1n.\n        </p>\n\n        <h4 class=\"paper-sub-heading\">\u0110\u00f3ng G\u00f3p Khoa H\u1ecdc C\u1ee7a B\u00e0i B\u00e1o (Contributions)</h4>\n        <p>\n            Ch\u00fang t\u00f4i \u0111\u1ec1 xu\u1ea5t m\u1ed9t m\u1ea1ng n\u01a1-ron t\u00edch ch\u1eadp (CNN) ho\u1ea1t \u0111\u1ed9ng \u0111\u1ed3ng th\u1eddi tr\u00ean c\u1ea3 hai mi\u1ec1n: <strong>mi\u1ec1n kh\u00f4ng gian (spatial domain)</strong> v\u00e0 <strong>mi\u1ec1n t\u1ea7n s\u1ed1 (frequency domain)</strong>:\n        </p>\n        <ul>\n            <li>Trong mi\u1ec1n kh\u00f4ng gian, ch\u00fang t\u00f4i t\u1eadp trung x\u1eed l\u00fd nhi\u1ec5u c\u1ea3m bi\u1ebfn $\\mathbf{n}$ v\u00e0 \u0111\u1ed9 m\u1edd kh\u00f4ng \u0111\u1ed3ng nh\u1ea5t $\\mathbf{k}$ b\u1eb1ng c\u01a1 ch\u1ebf ch\u00fa \u00fd kh\u00f4ng gian tr\u01b0\u1eddng ti\u1ebfp nh\u1eadn c\u1ef1c l\u1edbn (large receptive field spatial attention).</li>\n            <li>Trong mi\u1ec1n t\u1ea7n s\u1ed1 Fourier, ch\u00fang t\u00f4i gi\u1ea3i quy\u1ebft b\u00e0i to\u00e1n thi\u1ebfu s\u00e1ng m\u1ed9t c\u00e1ch d\u1ec5 d\u00e0ng v\u00e0 t\u1ef1 nhi\u00ean [28, 44] nh\u1edd v\u00e0o b\u1ea3n ch\u1ea5t to\u00e0n c\u1ee5c (global nature) c\u1ee7a s\u1ef1 ph\u00e2n b\u1ed1 n\u0103ng l\u01b0\u1ee3ng chi\u1ebfu s\u00e1ng.</li>\n        </ul>\n        <p>\n            Ch\u00fang t\u00f4i t\u00f3m t\u1eaft 3 \u0111\u00f3ng g\u00f3p khoa h\u1ecdc ch\u00ednh nh\u01b0 sau:\n        </p>\n        <ol>\n            <li>Thi\u1ebft k\u1ebf m\u1ed9t m\u1ea1ng n\u01a1-ron g\u1ecdn nh\u1eb9 k\u1ebft h\u1ee3p h\u00e0i h\u00f2a c\u01a1 ch\u1ebf ch\u00fa \u00fd mi\u1ec1n t\u1ea7n s\u1ed1 (frequency attention) v\u00e0 c\u01a1 ch\u1ebf ch\u00fa \u00fd tr\u01b0\u1eddng nh\u00ecn r\u1ed9ng (large receptive field attention), t\u1eadn d\u1ee5ng t\u1ed1i \u0111a th\u00f4ng tin t\u01b0\u01a1ng h\u1ed7 gi\u1eefa hai mi\u1ec1n.</li>\n            <li>M\u00f4 h\u00ecnh DarkIR thi\u1ebft l\u1eadp k\u1ef7 l\u1ee5c SOTA m\u1edbi tr\u00ean c\u00e1c b\u1ed9 d\u1eef li\u1ec7u danh ti\u1ebfng LOLBlur v\u00e0 Real-LOLBlur [65], c\u1ea3i thi\u1ec7n h\u01a1n <strong>+1.0 dB PSNR</strong> so v\u1edbi m\u00f4 h\u00ecnh ti\u1ec1n nhi\u1ec7m t\u1ed1t nh\u1ea5t LEDNet [65], trong khi c\u1eaft gi\u1ea3m \u0111\u00e1ng k\u1ec3 chi ph\u00ed t\u00ednh to\u00e1n ph\u1ea7n c\u1ee9ng (\u00edt h\u01a1n 55% tham s\u1ed1 v\u00e0 4x \u00edt h\u01a1n GMACs).</li>\n            <li>DarkIR \u0111\u1ea1i di\u1ec7n cho m\u1ed9t m\u00f4 h\u00ecnh \u0111\u1ed1i chu\u1ea9n (baseline) m\u1edbi \u0111\u1ea7y m\u1ea1nh m\u1ebd cho b\u00e0i to\u00e1n ph\u1ee5c h\u1ed3i \u1ea3nh ch\u1ee5p \u0111\u00eam \u0111a nhi\u1ec7m.</li>\n        </ol>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">2.</span> C\u00e1c C\u00f4ng Tr\u00ecnh Li\u00ean Quan (Related Work)</h3>\n        \n        <h4 class=\"paper-sub-heading\">2.1 Kh\u1eed M\u1edd \u1ea2nh (Image Deblurring)</h4>\n        <p>\n            C\u1ed9ng \u0111\u1ed3ng khoa h\u1ecdc \u0111\u00e3 tr\u1ea3i qua h\u00e0ng th\u1eadp k\u1ef7 nghi\u00ean c\u1ee9u v\u1ec1 vi\u1ec7c t\u00e1i t\u1ea1o c\u00e1c khung c\u1ea3nh s\u1eafc n\u00e9t. C\u00e1c gi\u1ea3i thu\u1eadt kh\u1eed m\u1edd \u0111\u01b0\u1ee3c chia th\u00e0nh hai nh\u00e1nh ch\u00ednh: <strong>ph\u01b0\u01a1ng ph\u00e1p kh\u00f4ng m\u00f9 (non-blind)</strong> v\u00e0 <strong>ph\u01b0\u01a1ng ph\u00e1p m\u00f9 (blind)</strong>. Trong khi ph\u01b0\u01a1ng ph\u00e1p kh\u00f4ng m\u00f9 \u0111\u00f2i h\u1ecfi ph\u1ea3i bi\u1ebft tr\u01b0\u1edbc kernel m\u1edd $\\mathbf{k}$ (ho\u1eb7c PSF) \u0111\u1ec3 ti\u1ebfn h\u00e0nh gi\u1ea3i t\u00edch ch\u1eadp (deconvolution), c\u00e1c ph\u01b0\u01a1ng ph\u00e1p m\u00f9 kh\u00f4ng c\u00f3 b\u1ea5t k\u1ef3 th\u00f4ng tin ti\u00ean nghi\u1ec7m n\u00e0o v\u1ec1 qu\u00e1 tr\u00ecnh g\u00e2y m\u1edd.\n        </p>\n        <p>\n            Nh\u1eefng n\u0103m g\u1ea7n \u0111\u00e2y, nhi\u1ec1u ki\u1ebfn tr\u00fac h\u1ecdc s\u00e2u \u0111\u00e3 \u0111\u01b0\u1ee3c \u0111\u1ec1 xu\u1ea5t cho c\u1ea3 hai b\u00e0i to\u00e1n [25, 38], v\u01b0\u1ee3t qua ho\u00e0n to\u00e0n c\u00e1c thu\u1eadt to\u00e1n c\u1ed5 \u0111i\u1ec3n. C\u00e1c m\u00f4 h\u00ecnh h\u1ecdc s\u00e2u kh\u00f4ng c\u1ea7n \u01b0\u1edbc l\u01b0\u1ee3ng PSF ph\u1ee9c t\u1ea1p v\u00e0 c\u00f3 t\u00ednh ch\u1ea5t b\u1ea5t kh\u1ea3 tri thi\u1ebft b\u1ecb (sensor-agnostic), ngh\u0129a l\u00e0 c\u00f3 th\u1ec3 t\u0103ng c\u01b0\u1eddng tr\u1ef1c ti\u1ebfp \u1ea3nh sRGB ch\u1ee5p t\u1eeb nhi\u1ec1u c\u1ea3m bi\u1ebfn m\u00e1y \u1ea3nh kh\u00e1c nhau. \u0110a ph\u1ea7n c\u00e1c ph\u01b0\u01a1ng ph\u00e1p hi\u1ec7n \u0111\u1ea1i d\u1ef1a tr\u00ean CNN [4, 25, 37, 57], GANs (DeblurGAN [25]), Transformer mi\u1ec1n t\u1ea7n s\u1ed1 [24], hay m\u00f4 h\u00ecnh Diffusion [33, 49].\n        </p>\n\n        <h4 class=\"paper-sub-heading\">2.2 T\u0103ng C\u01b0\u1eddng \u1ea2nh Thi\u1ebfu S\u00e1ng (LLIE)</h4>\n        <p>\n            C\u00e1c ph\u01b0\u01a1ng ph\u00e1p ban \u0111\u1ea7u d\u1ef1a tr\u00ean th\u1ed1ng k\u00ea \u1ea3nh ho\u1eb7c th\u00f4ng tin ti\u00ean nghi\u1ec7m [2, 18], h\u1ea7u h\u1ebft d\u1ef1a tr\u00ean <strong>L\u00fd thuy\u1ebft Retinex (Retinex Theory)</strong> [26] ph\u00e2n r\u00e3 \u1ea3nh th\u00e0nh th\u00e0nh ph\u1ea7n ph\u1ea3n x\u1ea1 (reflectance) v\u00e0 th\u00e0nh ph\u1ea7n chi\u1ebfu s\u00e1ng (illumination). B\u01b0\u1edbc sang k\u1ef7 nguy\u00ean h\u1ecdc s\u00e2u, c\u00e1c m\u00f4 h\u00ecnh CNN nh\u01b0 RetinexNet [48], Zero-DCE [16] v\u00e0 SCI [35] chi\u1ebfm \u01b0u th\u1ebf. G\u1ea7n \u0111\u00e2y, c\u00e1c m\u00f4 h\u00ecnh Vision Transformer nh\u01b0 RetinexFormer [3] ho\u1eb7c c\u00e1c m\u1ea1ng khai th\u00e1c th\u00f4ng tin bi\u00ean \u0111\u1ed9 Fourier nh\u01b0 FourLLIE [44] ti\u1ebfp t\u1ee5c \u0111\u1ea9y cao gi\u1edbi h\u1ea1n ch\u1ea5t l\u01b0\u1ee3ng.\n        </p>\n\n        <h4 class=\"paper-sub-heading\">2.3 Kh\u1eed M\u1edd Trong \u0110i\u1ec1u Ki\u1ec7n Thi\u1ebfu S\u00e1ng (Low-Light Blur Enhancement)</h4>\n        <p>\n            M\u1eb7c d\u00f9 hai b\u00e0i to\u00e1n tr\u00ean thu h\u00fat s\u1ef1 ch\u00fa \u00fd \u0111\u1ed9c l\u1eadp r\u1ea5t l\u1edbn, vi\u1ec7c gi\u1ea3i quy\u1ebft \u0111\u1ed3ng th\u1eddi c\u1ea3 hai b\u00e0i to\u00e1n c\u00f9ng m\u1ed9t l\u00fac l\u00e0 m\u1ed9t th\u00e1ch th\u1ee9c k\u1ef9 thu\u1eadt c\u1ef1c kh\u00f3, v\u00e0 ch\u1ec9 c\u00f3 s\u1ed1 \u00edt c\u00f4ng tr\u00ecnh ti\u1ebfp c\u1eadn [6, 33, 63, 65]. NBDN [6] \u0111\u1ec1 xu\u1ea5t m\u1ea1ng kh\u00f4ng m\u00f9 \u0111\u1ec3 x\u1eed l\u00fd \u1ea3nh \u0111\u00eam b\u00e3o h\u00f2a. V\u1edbi LEDNet [65], nh\u00f3m t\u00e1c gi\u1ea3 \u0111\u00e3 x\u00e2y d\u1ef1ng m\u1ea1ng Encoder-Decoder v\u00e0 gi\u1edbi thi\u1ec7u hai b\u1ed9 d\u1eef li\u1ec7u chu\u1ea9n quy m\u00f4 l\u1edbn l\u00e0 LOLBlur v\u00e0 Real-LOLBlur. DarkIR k\u1ebf th\u1eeba v\u00e0 kh\u1eafc ph\u1ee5c to\u00e0n di\u1ec7n c\u00e1c \u0111i\u1ec3m ngh\u1ebdn c\u1ee7a LEDNet.\n        </p>\n\n        <!-- Figure 2 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/darkir/fig_2_p3.png\" alt=\"DarkIR Architecture Diagram\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 2: S\u01a1 \u0111\u1ed3 ki\u1ebfn tr\u00fac t\u1ed5ng th\u1ec3 c\u1ee7a DarkIR.</strong> M\u1ea1ng n\u01a1-ron tu\u00e2n theo ki\u1ebfn tr\u00fac Encoder-Decoder. Ch\u00fang t\u00f4i s\u1eed d\u1ee5ng c\u00e1c kh\u1ed1i ch\u1ee9c n\u0103ng b\u1ea5t \u0111\u1ed1i x\u1ee9ng d\u1ef1a tr\u00ean c\u1ea5u tr\u00fac MetaFormer [56]. B\u1ed9 m\u00e3 h\u00f3a (Encoder) t\u1eadp trung gi\u1ea3i quy\u1ebft b\u00e0i to\u00e1n chi\u1ebfu s\u00e1ng thi\u1ebfu s\u00e1ng b\u1eb1ng th\u00f4ng tin mi\u1ec1n t\u1ea7n s\u1ed1 Fourier, t\u1ea1o ra \u1ea3nh t\u00e1i t\u1ea1o trung gian thu nh\u1ecf $\\hat{x}_{\\downarrow 8}$ \u0111\u00e3 \u0111\u01b0\u1ee3c c\u00e2n b\u1eb1ng m\u1ee9c s\u00e1ng ho\u00e0n h\u1ea3o. B\u1ed9 gi\u1ea3i m\u00e3 (Decoder) nh\u1eadn c\u00e1c \u0111\u1eb7c tr\u01b0ng s\u00e1ng \u0111\u00e3 \u0111\u01b0\u1ee3c m\u00e3 h\u00f3a, t\u1eadp trung n\u00e2ng t\u1ef7 l\u1ec7 (upscaling) v\u00e0 kh\u1eed s\u1ea1ch m\u1edd nh\u00f2e b\u1eb1ng c\u01a1 ch\u1ebf ch\u00fa \u00fd kh\u00f4ng gian tr\u01b0\u1eddng ti\u1ebfp nh\u1eadn c\u1ef1c l\u1edbn (Di-SpAM). Thi\u1ebft k\u1ebf n\u00e0y gi\u00fap m\u00f4 h\u00ecnh g\u1ecdn nh\u1eb9, s\u1edf h\u1eefu \u00edt tham s\u1ed1 v\u00e0 FLOPs h\u01a1n h\u1eb3n c\u00e1c ph\u01b0\u01a1ng ph\u00e1p tr\u01b0\u1edbc.\n            </figcaption>\n        </figure>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">3.</span> Ph\u01b0\u01a1ng Ph\u00e1p \u0110\u1ec1 Xu\u1ea5t (Method)</h3>\n        <p>\n            Ch\u00fang t\u00f4i d\u1ef1a tr\u00ean tri\u1ebft l\u00fd thi\u1ebft k\u1ebf <strong>MetaFormer</strong> [56] \u0111\u1ec3 x\u00e2y d\u1ef1ng m\u1ea1ng n\u01a1-ron c\u1ee7a m\u00ecnh. Thi\u1ebft k\u1ebf n\u00e0y tr\u1eebu t\u01b0\u1ee3ng h\u00f3a c\u00e1c ki\u1ebfn tr\u00fac d\u1ef1a tr\u00ean Transformer th\u00e0nh c\u00e1c kh\u1ed1i \u0111\u01a1n gi\u1ea3n g\u1ed3m hai th\u00e0nh ph\u1ea7n c\u1ed1t l\u00f5i: module ch\u00fa \u00fd to\u00e0n c\u1ee5c (global attention / token mixer) v\u00e0 m\u1ea1ng truy\u1ec1n th\u1eb3ng (Feed-Forward Network - FFN / MLP). C\u00f4ng th\u1ee9c \u0111i\u1ec3n h\u00ecnh c\u1ee7a MetaFormer l\u00e0:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$z_1 = \\text{Attention}(\\text{LayerNorm}(z)) + z$$</div>\n            <span class=\"paper-equation-num\">(2)</span>\n        </div>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$z_2 = \\text{FFN}(\\text{LayerNorm}(z_1)) + z_1$$</div>\n            <span class=\"paper-equation-num\">(3)</span>\n        </div>\n        <p>\n            Trong \u0111\u00f3 $z$ l\u00e0 \u0111\u1eb7c tr\u01b0ng \u0111\u1ea7u v\u00e0o v\u00e0 $z_2$ l\u00e0 \u0111\u1eb7c tr\u01b0ng \u0111\u1ea7u ra c\u1ee7a kh\u1ed1i. H\u1ea7u h\u1ebft c\u00e1c m\u00f4 h\u00ecnh ph\u1ee5c h\u1ed3i \u1ea3nh h\u00e0ng \u0111\u1ea7u nh\u01b0 NAFNet [7] \u0111\u1ec1u \u00e1p d\u1ee5ng c\u1ea5u tr\u00fac n\u00e0y. Ch\u00fang t\u00f4i n\u00e2ng c\u1ea5p MetaFormer b\u1eb1ng c\u00e1ch ph\u00e1t tri\u1ec3n c\u00e1c kh\u1ed1i chuy\u00ean bi\u1ec7t cho t\u1eebng t\u00e1c v\u1ee5: <strong>EBlock</strong> chuy\u00ean x\u1eed l\u00fd thi\u1ebfu s\u00e1ng \u1edf Encoder, v\u00e0 <strong>DBlock</strong> chuy\u00ean x\u1eed l\u00fd kh\u1eed m\u1edd \u1edf Decoder. H\u01a1n n\u1eefa, ch\u00fang t\u00f4i s\u1eed d\u1ee5ng c\u01a1 ch\u1ebf c\u1ed5ng \u0111\u01a1n gi\u1ea3n (Simple Gates - SG) v\u00e0 c\u01a1 ch\u1ebf ch\u00fa \u00fd k\u00eanh gi\u1ea3n l\u01b0\u1ee3c (Simplified Channel Attention - SCA) thay th\u1ebf cho c\u00e1c h\u00e0m k\u00edch ho\u1ea1t phi tuy\u1ebfn t\u00ednh \u0111\u1eaft \u0111\u1ecf [7].\n        </p>\n\n        <h4 class=\"paper-sub-heading\">3.1 B\u1ed9 M\u00e3 H\u00f3a T\u0103ng C\u01b0\u1eddng \u00c1nh S\u00e1ng (Low-Light Enhancement Encoder)</h4>\n        <p>\n            Nhi\u1ec1u nghi\u00ean c\u1ee9u quang h\u1ecdc [28, 44] \u0111\u00e3 ch\u1ee9ng minh r\u1eb1ng: <strong>\u0111i\u1ec1u ki\u1ec7n chi\u1ebfu s\u00e1ng c\u1ee7a b\u1ee9c \u1ea3nh t\u01b0\u01a1ng quan r\u1ea5t cao v\u1edbi ph\u1ed5 bi\u00ean \u0111\u1ed9 (amplitude) trong mi\u1ec1n Fourier</strong>. Do \u0111\u00f3, b\u1eb1ng c\u00e1ch ch\u1ec9 k\u00edch s\u00e1ng ph\u1ed5 bi\u00ean \u0111\u1ed9 c\u1ee7a \u1ea3nh m\u00e0 gi\u1eef nguy\u00ean ph\u1ed5 pha (phase), ch\u00fang ta c\u00f3 th\u1ec3 \u0111i\u1ec1u ch\u1ec9nh m\u1ee9c s\u00e1ng c\u1ee7a to\u00e0n b\u1ed9 b\u1ee9c \u1ea3nh m\u1ed9t c\u00e1ch t\u1ef1 nhi\u00ean m\u00e0 kh\u00f4ng l\u00e0m bi\u1ebfn d\u1ea1ng \u0111\u01b0\u1eddng n\u00e9t h\u00ecnh h\u1ecdc. \u0110\u1eb7c t\u00ednh n\u00e0y b\u1ea3o to\u00e0n qua nhi\u1ec1u thang \u0111\u1ed9 ph\u00e2n gi\u1ea3i kh\u00e1c nhau [28].\n        </p>\n        <p>\n            V\u00ec v\u1eady, kh\u1ed1i <strong>EBlock</strong> bao g\u1ed3m hai th\u00e0nh ph\u1ea7n: Module ch\u00fa \u00fd kh\u00f4ng gian (Spatial Attention Module - SpAM) v\u00e0 M\u1ea1ng n\u01a1-ron mi\u1ec1n t\u1ea7n s\u1ed1 (Frequency MLP - Fre-MLP). SpAM s\u1eed d\u1ee5ng kh\u1ed1i inverted residual k\u1ebft h\u1ee3p SCA v\u00e0 Simple Gate.\n        </p>\n        <p>\n            Ti\u1ebfp theo, ph\u00e9p bi\u1ebfn \u0111\u1ed5i Fourier nhanh 2D (2D-FFT) chuy\u1ec3n \u0111\u1eb7c tr\u01b0ng sang mi\u1ec1n ph\u1ee9c:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$\\mathcal{F}(X) = X_R + i X_I \\in \\mathbb{C}^{C \\times H \\times W}$$</div>\n            <span class=\"paper-equation-num\">(4)</span>\n        </div>\n        <p>\n            Ch\u00fang t\u00f4i t\u00e1ch ri\u00eang ph\u1ed5 bi\u00ean \u0111\u1ed9 $|X| = \\sqrt{X_R^2 + X_I^2}$ v\u00e0 \u0111\u01b0a qua Fre-MLP g\u1ed3m hai l\u1edbp t\u00edch ch\u1eadp $1 \\times 1$ k\u1ebft h\u1ee3p h\u00e0m k\u00edch ho\u1ea1t LReLU. Ph\u00e9p bi\u1ebfn \u0111\u1ed5i Fourier ng\u01b0\u1ee3c (IFFT) sau \u0111\u00f3 \u0111\u01b0a \u0111\u1eb7c tr\u01b0ng tr\u1edf l\u1ea1i mi\u1ec1n kh\u00f4ng gian. Nh\u1edd vi\u1ec7c gi\u1ea3m t\u1ef7 l\u1ec7 kh\u00f4ng gian qua t\u00edch ch\u1eadp c\u00f3 b\u01b0\u1edbc nh\u1ea3y (strided convolution), ch\u00fang t\u00f4i c\u00f3 th\u1ec3 x\u1ebfp ch\u1ed3ng nhi\u1ec1u kh\u1ed1i EBlock \u1edf c\u00e1c t\u1ea7ng s\u00e2u m\u00e0 kh\u00f4ng l\u00e0m b\u00f9ng n\u1ed5 s\u1ed1 ph\u00e9p to\u00e1n. T\u1ea1i \u0111\u00e1y b\u1ed9 m\u00e3 h\u00f3a, m\u1ed9t l\u1edbp t\u00edch ch\u1eadp t\u1ea1o ra \u1ea3nh t\u00e1i t\u1ea1o thu nh\u1ecf $\\hat{x}_{\\downarrow 8}$ c\u00f3 k\u00edch th\u01b0\u1edbc b\u1eb1ng $1/8$ \u1ea3nh g\u1ed1c nh\u01b0ng \u0111\u00e3 \u0111\u01b0\u1ee3c c\u00e2n b\u1eb1ng m\u1ee9c s\u00e1ng ho\u00e0n h\u1ea3o.\n        </p>\n\n        <h4 class=\"paper-sub-heading\">3.2 B\u1ed9 Gi\u1ea3i M\u00e3 Kh\u1eed M\u1edd (Deblurring Decoder)</h4>\n        <p>\n            Kh\u1ed1i gi\u1ea3i m\u00e3 <strong>DBlock</strong> t\u1eadp trung v\u00e0o c\u00e1c ph\u00e9p bi\u1ebfn \u0111\u1ed5i h\u00ecnh h\u1ecdc trong mi\u1ec1n kh\u00f4ng gian. \u0110\u1ea7u v\u00e0o c\u1ee7a Decoder l\u00e0 bi\u1ec3u di\u1ec5n s\u00e2u c\u1ee7a $\\hat{x}_{\\downarrow 8}$, do \u0111\u00f3 Decoder c\u00f3 th\u1ec3 t\u1eadp trung ho\u00e0n to\u00e0n v\u00e0o vi\u1ec7c: (1) n\u00e2ng \u0111\u1ed9 ph\u00e2n gi\u1ea3i (upsampling) v\u00e0 (2) tri\u1ec7t ti\u00eau c\u00e1c v\u1ec7t m\u1edd nh\u00f2e, kh\u00f4i ph\u1ee5c \u0111\u1ed9 s\u1eafc n\u00e9t g\u1edd c\u1ea1nh. C\u1ea5u tr\u00fac DBlock tu\u00e2n theo:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$z_1 = \\text{Di-SpAM}(\\text{LayerNorm}(z)) + z$$</div>\n            <span class=\"paper-equation-num\">(5)</span>\n        </div>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$z_2 = \\text{GatedFFN}(\\text{LayerNorm}(z_1)) + z_1$$</div>\n            <span class=\"paper-equation-num\">(6)</span>\n        </div>\n        <p>\n            L\u1ea5y c\u1ea3m h\u1ee9ng t\u1eeb Large Kernel Attention (LKA) [17], ch\u00fang t\u00f4i s\u00e1ng t\u1ea1o ra module <strong>Di-SpAM (Dilated-Spatial Attention Module)</strong>. Kh\u00e1c v\u1edbi LKA, Di-SpAM tr\u00edch xu\u1ea5t \u0111\u1eb7c tr\u01b0ng \u1edf ba c\u1ea5p \u0111\u1ed9 song song b\u1eb1ng ba nh\u00e1nh t\u00edch ch\u1eadp s\u00e2u (Depth-wise Convolutions) v\u1edbi h\u1ec7 s\u1ed1 gi\u00e3n n\u1edf l\u1ea7n l\u01b0\u1ee3t l\u00e0 $d = 1, 4, 9$. C\u00e1c thu\u1ed9c t\u00ednh t\u1eeb 3 nh\u00e1nh \u0111\u01b0\u1ee3c c\u1ed9ng g\u1ed9p, \u0111i qua l\u1edbp ch\u00fa \u00fd k\u00eanh SCA v\u00e0 cu\u1ed1i c\u00f9ng k\u1ebft h\u1ee3p v\u1edbi m\u1ea1ng Gated-FFN.\n        </p>\n\n        <h4 class=\"paper-sub-heading\">3.3 H\u00e0m M\u1ea5t M\u00e1t T\u1ed1i \u01afu H\u00f3a (Loss Function)</h4>\n        <p>\n            Ch\u00fang t\u00f4i k\u1ebft h\u1ee3p h\u00e0i h\u00f2a gi\u1eefa h\u00e0m m\u1ea5t m\u00e1t \u0111\u1ed9 trung th\u1ef1c (distortion loss) v\u00e0 h\u00e0m m\u1ea5t m\u00e1t c\u1ea3m nh\u1eadn tri gi\u00e1c (perceptual loss) \u0111\u1ec3 t\u1ed1i \u01b0u h\u00f3a m\u00f4 h\u00ecnh $f$:\n        </p>\n        <ul>\n            <li>H\u00e0m m\u1ea5t m\u00e1t \u0111i\u1ec3m \u1ea3nh $L_{l1} = \\|x - \\hat{x}\\|_1$ \u0111\u1ea3m b\u1ea3o \u0111\u1ed9 ch\u00ednh x\u00e1c m\u1ee9c x\u00e1m cao nh\u1ea5t.</li>\n            <li>H\u00e0m m\u1ea5t m\u00e1t c\u1ea3m nh\u1eadn $L_{percep} = \\text{LPIPS}(x, \\hat{x})$ t\u00ednh kho\u1ea3ng c\u00e1ch \u0111\u1eb7c tr\u01b0ng VGG19 [43] gi\u1eefa \u1ea3nh sinh ra v\u00e0 \u1ea3nh tham chi\u1ebfu:\n                <div class=\"paper-equation\">\n                    <div class=\"paper-equation-math\">$$L_{percep} = \\text{LPIPS}(x, \\hat{x})$$</div>\n                    <span class=\"paper-equation-num\">(7)</span>\n                </div>\n            </li>\n            <li>H\u00e0m m\u1ea5t m\u00e1t Gradient bi\u00ean c\u1ea1nh $L_{edge}$ ph\u1ea1t n\u1eb7ng sai s\u1ed1 t\u1ea1i c\u00e1c \u0111\u01b0\u1eddng n\u00e9t t\u1ea7n s\u1ed1 cao:\n                <div class=\"paper-equation\">\n                    <div class=\"paper-equation-math\">$$L_{edge} = \\|\\nabla x - \\nabla \\hat{x}\\|_2^2$$</div>\n                    <span class=\"paper-equation-num\">(8)</span>\n                </div>\n            </li>\n            <li>H\u00e0m m\u1ea5t m\u00e1t \u0111\u1ecbnh h\u01b0\u1edbng ki\u1ebfn tr\u00fac t\u1ea7ng \u0111\u00e1y $L_{lol}$ \u00e9p Encoder ph\u1ea3i th\u1ef1c hi\u1ec7n \u0111\u00fang ch\u1ee9c n\u0103ng t\u0103ng s\u00e1ng \u1edf m\u1ee9c \u0111\u1ed9 ph\u00e2n gi\u1ea3i thu nh\u1ecf:\n                <div class=\"paper-equation\">\n                    <div class=\"paper-equation-math\">$$L_{lol} = \\|x - \\hat{x}_{\\uparrow 8}\\|_1 + \\text{LPIPS}(x, \\hat{x}_{\\uparrow 8})$$</div>\n                    <span class=\"paper-equation-num\">(9)</span>\n                </div>\n                v\u1edbi $\\hat{x}_{\\uparrow 8}$ l\u00e0 \u1ea3nh n\u1ed9i suy song tuy\u1ebfn t\u00ednh ph\u00f3ng to 8 l\u1ea7n t\u1eeb \u0111\u1ea7u ra t\u1ea7ng \u0111\u00e1y Encoder.\n            </li>\n        </ul>\n        <p>\n            H\u00e0m m\u1ea5t m\u00e1t t\u1ed5ng h\u1ee3p to\u00e0n di\u1ec7n l\u00e0:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$\\mathcal{L} = \\lambda_p \\cdot L_{l1} + \\lambda_{pe} \\cdot L_{percep} + \\lambda_{ed} \\cdot L_{edge} + L_{lol}$$</div>\n            <span class=\"paper-equation-num\">(10)</span>\n        </div>\n        <p>\n            C\u00e1c h\u1ec7 s\u1ed1 tr\u1ecdng s\u1ed1 th\u1ef1c nghi\u1ec7m \u0111\u01b0\u1ee3c thi\u1ebft l\u1eadp l\u1ea7n l\u01b0\u1ee3t l\u00e0 $\\lambda_p = 1$, $\\lambda_{pe} = 10^{-2}$ v\u00e0 $\\lambda_{ed} = 50$.\n        </p>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">4.</span> K\u1ebft Qu\u1ea3 Th\u1ef1c Nghi\u1ec7m & \u0110\u1ed1i Chu\u1ea9n (Experimental Results)</h3>\n        \n        <h4 class=\"paper-sub-heading\">4.1 C\u00e1c B\u1ed9 D\u1eef Li\u1ec7u Th\u1ef1c Nghi\u1ec7m (Datasets)</h4>\n        <ul>\n            <li><strong>LOLBlur [65]:</strong> G\u1ed3m 10,200 c\u1eb7p \u1ea3nh hu\u1ea5n luy\u1ec7n v\u00e0 1,800 c\u1eb7p \u1ea3nh ki\u1ec3m th\u1eed t\u1ed5ng h\u1ee3p m\u00f4 ph\u1ecfng ch\u00ednh x\u00e1c m\u1edd nh\u00f2e chuy\u1ec3n \u0111\u1ed9ng v\u00e0 nhi\u1ec5u c\u1ea3m bi\u1ebfn th\u1ef1c t\u1ebf.</li>\n            <li><strong>Real-LOLBlur [65]:</strong> T\u1eadp ki\u1ec3m th\u1eed g\u1ed3m 482 \u1ea3nh ch\u1ee5p \u0111\u00eam th\u1ef1c t\u1ebf t\u1eeb RealBlur [40], ch\u1ee5p b\u1eb1ng tay, kh\u00f4ng c\u00f3 Ground Truth, d\u00f9ng \u0111\u1ec3 \u0111o l\u01b0\u1eddng kh\u1ea3 n\u0103ng t\u1ed5ng qu\u00e1t h\u00f3a th\u1ef1c t\u1ebf.</li>\n            <li><strong>LOLv2 (Real & Synthetic) [55]:</strong> B\u1ea3n m\u1edf r\u1ed9ng c\u1ee7a t\u1eadp LOL n\u1ed5i ti\u1ebfng, g\u1ed3m 689 c\u1eb7p train / 100 test (Real) v\u00e0 900 train / 100 val (Synthetic).</li>\n            <li><strong>LSRW [19]:</strong> G\u1ed3m \u1ea3nh t\u1eeb m\u00e1y \u1ea3nh chuy\u00ean nghi\u1ec7p Nikon (3,150 train, 20 test) v\u00e0 \u0111i\u1ec7n tho\u1ea1i th\u00f4ng minh Huawei (2,450 train, 30 val).</li>\n        </ul>\n\n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 1: \u0110\u00e1nh gi\u00e1 \u0111\u1ecbnh l\u01b0\u1ee3ng tr\u00ean t\u1eadp d\u1eef li\u1ec7u chu\u1ea9n LOLBlur. DarkIR thi\u1ebft l\u1eadp k\u1ef7 l\u1ee5c SOTA m\u1edbi tr\u00ean c\u1ea3 ch\u1ec9 s\u1ed1 m\u00e9o d\u1ea1ng v\u00e0 c\u1ea3m nh\u1eadn, s\u1edf h\u1eefu \u00edt h\u01a1n 55% tham s\u1ed1 so v\u1edbi LEDNet [65] v\u00e0 \u00edt h\u01a1n 88% so v\u1edbi Restormer [57].</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>Ph\u01b0\u01a1ng Ph\u00e1p</th>\n                        <th>PSNR (dB) \u2191</th>\n                        <th>SSIM \u2191</th>\n                        <th>LPIPS \u2193</th>\n                        <th>Params (M) \u2193</th>\n                        <th>MACs (G) \u2193</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>KinD++ [61]</td><td>21.26</td><td>0.753</td><td>0.359</td><td>1.20M</td><td>34.99G</td></tr>\n                    <tr><td>DRBN [54]</td><td>21.78</td><td>0.768</td><td>0.325</td><td>0.60M</td><td>48.61G</td></tr>\n                    <tr><td>DeblurGAN-v2 [25]</td><td>22.30</td><td>0.745</td><td>0.356</td><td>60.90M</td><td>-</td></tr>\n                    <tr><td>MIMO-UNet [8]</td><td>22.41</td><td>0.835</td><td>0.262</td><td>6.80M</td><td>67.25G</td></tr>\n                    <tr><td>NAFNet [9]</td><td>25.36</td><td>0.882</td><td>0.158</td><td>12.05M</td><td>12.30G</td></tr>\n                    <tr><td>LEDNet [65] (SOTA C\u0169)</td><td>25.74</td><td>0.850</td><td>0.224</td><td>7.40M</td><td>38.65G</td></tr>\n                    <tr><td>RetinexFormer [3]</td><td>26.02</td><td>0.887</td><td>0.181</td><td>1.61M</td><td>15.57G</td></tr>\n                    <tr><td>Restormer [57]</td><td>26.72</td><td>0.902</td><td>0.133</td><td>26.13M</td><td>144.25G</td></tr>\n                    <tr style=\"background: rgba(56, 189, 248, 0.12); font-weight: bold;\">\n                        <td style=\"color: #38BDF8;\">DarkIR-m (Ours)</td>\n                        <td class=\"best\">27.00</td>\n                        <td>0.883</td>\n                        <td>0.162</td>\n                        <td style=\"color: #38BDF8;\">3.31M</td>\n                        <td style=\"color: #38BDF8;\">7.25G</td>\n                    </tr>\n                    <tr style=\"background: rgba(167, 139, 250, 0.12); font-weight: bold;\">\n                        <td style=\"color: #A78BFA;\">DarkIR-l (Ours)</td>\n                        <td class=\"best\">27.30</td>\n                        <td class=\"best\">0.898</td>\n                        <td class=\"best\">0.137</td>\n                        <td>12.96M</td>\n                        <td>27.19G</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 3 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/darkir/fig_3_p5.png\" alt=\"DarkIR Figure 3 Visual Comparison\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 3: So s\u00e1nh ch\u1ea5t l\u01b0\u1ee3ng tr\u1ef1c quan tr\u00ean t\u1eadp d\u1eef li\u1ec7u LOLBlur (c\u00e1c m\u1eabu t\u1ed5ng h\u1ee3p trong t\u1eadp test).</strong> T\u1eeb tr\u00e1i sang ph\u1ea3i: \u1ea2nh \u0111\u1ea7u v\u00e0o m\u1edd nh\u00f2e thi\u1ebfu s\u00e1ng (Input), LEDNet, RetinexFormer, NAFNet, Restormer, DarkIR-m (Ours), DarkIR-l (Ours), v\u00e0 \u1ea3nh chu\u1ea9n Ground Truth (GT). DarkIR kh\u00f4i ph\u1ee5c r\u00f5 n\u00e9t t\u1eebng k\u00fd t\u1ef1 ch\u1eef \"excited\" tr\u00ean poster v\u00e0 chai n\u01b0\u1edbc trong ph\u00f2ng t\u1ed1i m\u00e0 kh\u00f4ng h\u1ec1 b\u1ecb nh\u00f2e b\u1ebft hay qu\u1ea7ng s\u00e1ng gi\u1ea3.\n            </figcaption>\n        </figure>\n\n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 2: So s\u00e1nh \u0111\u1ecbnh l\u01b0\u1ee3ng v\u1edbi c\u00e1c chu\u1ed7i x\u1eed l\u00fd 2 b\u01b0\u1edbc (2-step pipelines) tr\u00ean LOLBlur. DarkIR v\u01b0\u1ee3t tr\u1ed9i ho\u00e0n to\u00e0n.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>C\u1ea5u H\u00ecnh Pipeline Gh\u00e9p N\u1ed1i</th>\n                        <th>Lo\u1ea1i Quy Tr\u00ecnh</th>\n                        <th>PSNR (dB) \u2191</th>\n                        <th>SSIM \u2191</th>\n                        <th>LPIPS \u2193</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>Zero-DCE [16] \u2192 MIMO [8]</td><td>1. LLIE \u2192 Deblurring</td><td>17.68</td><td>0.542</td><td>0.510</td></tr>\n                    <tr><td>RUAS [30] \u2192 MIMO [8]</td><td>1. LLIE \u2192 Deblurring</td><td>17.81</td><td>0.569</td><td>0.523</td></tr>\n                    <tr><td>RetinexFormer [3] \u2192 NAFNet [7]</td><td>1. LLIE \u2192 Deblurring</td><td>17.16</td><td>0.673</td><td>0.392</td></tr>\n                    <tr><td>Chen [5] \u2192 Zero-DCE [16]</td><td>2. Deblurring \u2192 LLIE</td><td>17.02</td><td>0.502</td><td>0.516</td></tr>\n                    <tr><td>DeblurGAN-v2 [25] \u2192 Zero-DCE [16]</td><td>2. Deblurring \u2192 LLIE</td><td>18.33</td><td>0.589</td><td>0.476</td></tr>\n                    <tr><td>MIMO [8] \u2192 Zero-DCE [16]</td><td>2. Deblurring \u2192 LLIE</td><td>17.52</td><td>0.570</td><td>0.498</td></tr>\n                    <tr><td>NAFNet [7] \u2192 RetinexFormer [3]</td><td>2. Deblurring \u2192 LLIE</td><td>14.66</td><td>0.500</td><td>0.465</td></tr>\n                    <tr style=\"background: rgba(56, 189, 248, 0.15); font-weight: bold;\">\n                        <td style=\"color: #38BDF8;\">DarkIR-m (Ours)</td>\n                        <td>T\u00edch H\u1ee3p \u0110\u1ea7u-Cu\u1ed1i (End-to-End)</td>\n                        <td class=\"best\">27.00</td>\n                        <td class=\"best\">0.883</td>\n                        <td class=\"best\">0.162</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 4 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/darkir/fig_4_p6.png\" alt=\"DarkIR Figure 4 Comparisons with Pipelines\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 4: So s\u00e1nh tr\u1ef1c quan tr\u00ean LOLBlur gi\u1eefa DarkIR v\u00e0 c\u00e1c quy tr\u00ecnh 2 b\u01b0\u1edbc.</strong> C\u00e1c gi\u1ea3i ph\u00e1p 2 b\u01b0\u1edbc \u0111\u1ec1u sinh ra qu\u1ea7ng s\u00e1ng ch\u00f3i l\u1ecdi ho\u1eb7c nhi\u1ec5u m\u00e0u loang l\u1ed5, trong khi DarkIR t\u00e1i t\u1ea1o c\u00e1c c\u1ea5u tr\u00fac h\u00ecnh h\u1ecdc s\u1eafc n\u00e9t v\u00e0 t\u1ef1 nhi\u00ean.\n            </figcaption>\n        </figure>\n\n        <div class=\"paper-table-wrapper\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 3: K\u1ebft qu\u1ea3 tr\u00ean t\u1eadp d\u1eef li\u1ec7u LSRW (50 \u1ea3nh ki\u1ec3m th\u1eed t\u1eeb Huawei v\u00e0 Nikon).</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr><th>Ph\u01b0\u01a1ng Ph\u00e1p</th><th>PSNR (dB) \u2191</th><th>SSIM \u2191</th></tr>\n                </thead>\n                <tbody>\n                    <tr><td>RetinexNet [47]</td><td>15.906</td><td>0.3725</td></tr>\n                    <tr><td>FIDE [51]</td><td>17.669</td><td>0.5485</td></tr>\n                    <tr><td>DRBN [54]</td><td>16.149</td><td>0.5422</td></tr>\n                    <tr><td>KinD [61]</td><td>16.472</td><td>0.4929</td></tr>\n                    <tr><td>EnGAN [22]</td><td>16.311</td><td>0.4697</td></tr>\n                    <tr><td>Zero-DCE [16]</td><td>15.834</td><td>0.4664</td></tr>\n                    <tr><td>RUAS [30]</td><td>14.437</td><td>0.4276</td></tr>\n                    <tr><td>SCI [35]</td><td>15.017</td><td>0.4846</td></tr>\n                    <tr style=\"font-weight: bold; color: #38BDF8;\"><td>DarkIR-mt (Ours Multi-Task)</td><td class=\"best\">18.930</td><td class=\"best\">0.5830</td></tr>\n                </tbody>\n            </table>\n        </div>\n\n        <div class=\"paper-table-wrapper\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 4: K\u1ebft qu\u1ea3 tr\u00ean t\u1eadp d\u1eef li\u1ec7u LOLv2-Real v\u00e0 LOLv2-Synthetic.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>Ph\u01b0\u01a1ng Ph\u00e1p</th>\n                        <th>MACs (G) \u2193</th>\n                        <th>Params (M) \u2193</th>\n                        <th>LOLv2-Real PSNR \u2191</th>\n                        <th>LOLv2-Real SSIM \u2191</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>UFormer [46]</td><td>12.00G</td><td>5.29M</td><td>18.82</td><td>0.771</td></tr>\n                    <tr><td>RetinexNet [47]</td><td>587.47G</td><td>0.84M</td><td>15.47</td><td>0.567</td></tr>\n                    <tr><td>EnGAN [22]</td><td>61.01G</td><td>114.35M</td><td>18.23</td><td>0.617</td></tr>\n                    <tr><td>DRBN [54]</td><td>48.61G</td><td>5.27M</td><td>20.29</td><td>0.831</td></tr>\n                    <tr><td>Restormer [57]</td><td>144.25G</td><td>26.13M</td><td>19.94</td><td>0.827</td></tr>\n                    <tr><td>FourLLIE [44]</td><td>5.80G</td><td>0.12M</td><td>21.60</td><td>0.847</td></tr>\n                    <tr><td>RetinexFormer [3]</td><td>15.57G</td><td>1.61M</td><td>22.80</td><td>0.840</td></tr>\n                    <tr style=\"font-weight: bold; color: #38BDF8;\">\n                        <td>DarkIR-mt (Ours)</td>\n                        <td>7.25G</td>\n                        <td>3.31M</td>\n                        <td class=\"best\">23.87</td>\n                        <td class=\"best\">0.880</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 5 & 6 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/darkir/fig_5_p7.png\" alt=\"DarkIR Figure 5 LSRW Qualitative\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 5: K\u1ebft qu\u1ea3 tr\u1ef1c quan tr\u00ean t\u1eadp d\u1eef li\u1ec7u th\u1ef1c t\u1ebf LSRW-Huawei.</strong> DarkIR ph\u1ee5c h\u1ed3i d\u1ea3i m\u00e0u chu\u1ea9n x\u00e1c v\u00e0 kh\u1eed s\u1ea1ch nhi\u1ec5u h\u1ea1t so v\u1edbi KinD, DRBN v\u00e0 EnGAN.\n            </figcaption>\n        </figure>\n\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/darkir/fig_6_p7.png\" alt=\"DarkIR Figure 6 LOLv2-Real vs RetinexFormer\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 6: So s\u00e1nh tr\u1ef1c quan tr\u00ean LOLv2-Real v\u1edbi RetinexFormer [3].</strong> DarkIR gi\u1eef \u0111\u01b0\u1ee3c \u0111\u1ed9 s\u00e1ng \u0111\u1ed3ng \u0111\u1ec1u v\u00e0 c\u00e1c g\u1edd bi\u00ean n\u1ed9i th\u1ea5t s\u1eafc n\u00e9t h\u01a1n h\u1eb3n.\n            </figcaption>\n        </figure>\n\n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 5: \u0110\u00e1nh gi\u00e1 ch\u1ea5t l\u01b0\u1ee3ng c\u1ea3m nh\u1eadn kh\u00f4ng c\u1ea7n \u1ea3nh m\u1eabu (Blind IQA) tr\u00ean t\u1eadp \u1ea3nh ch\u1ee5p \u0111\u00eam th\u1ef1c t\u1ebf Real-LOLBlur.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>Ph\u01b0\u01a1ng Ph\u00e1p</th>\n                        <th>MUSIQ \u2191 (C\u00e0ng cao c\u00e0ng t\u1ed1t)</th>\n                        <th>NRQM \u2191 (C\u00e0ng cao c\u00e0ng t\u1ed1t)</th>\n                        <th>NIQE \u2193 (C\u00e0ng th\u1ea5p c\u00e0ng t\u1ed1t)</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>RUAS \u2192 MIMO</td><td>34.39</td><td>3.322</td><td>6.812</td></tr>\n                    <tr><td>MIMO \u2192 Zero-DCE</td><td>28.36</td><td>3.697</td><td>6.892</td></tr>\n                    <tr><td>RetinexFormer [3]</td><td>45.30</td><td>5.281</td><td>4.576</td></tr>\n                    <tr><td>NAFNet [9]</td><td>50.22</td><td>4.940</td><td>5.123</td></tr>\n                    <tr><td>LEDNet [65]</td><td>39.11</td><td>5.643</td><td>4.764</td></tr>\n                    <tr><td>Restormer [57]</td><td>46.60</td><td>4.627</td><td>5.268</td></tr>\n                    <tr style=\"font-weight: bold; color: #38BDF8;\">\n                        <td>DarkIR-m (Ours)</td>\n                        <td>48.36</td>\n                        <td>4.983</td>\n                        <td>4.998</td>\n                    </tr>\n                    <tr style=\"font-weight: bold; color: #A78BFA;\">\n                        <td>DarkIR-l (Ours)</td>\n                        <td>48.79</td>\n                        <td>4.917</td>\n                        <td>5.051</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 7 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/darkir/fig_7_p8.png\" alt=\"DarkIR Figure 7 Real Night Scenes\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 7: So s\u00e1nh ch\u1ea5t l\u01b0\u1ee3ng tr\u1ef1c quan tr\u00ean c\u00e1c c\u1ea3nh \u0111\u00eam th\u1ef1c t\u1ebf t\u1eeb b\u1ed9 d\u1eef li\u1ec7u RealBlurLOL.</strong> C\u00e1c ph\u01b0\u01a1ng ph\u00e1p kh\u00e1c \u0111\u1ec1u b\u1ecb nh\u00f2e v\u1ec7t \u0111\u00e8n xe ho\u1eb7c l\u00e0m v\u1ee1 c\u1ea5u tr\u00fac t\u00f2a nh\u00e0, trong khi DarkIR kh\u00f4i ph\u1ee5c c\u00e1c chi ti\u1ebft ki\u1ebfn tr\u00fac \u0111\u00eam v\u00f4 c\u00f9ng \u1ea5n t\u01b0\u1ee3ng.\n            </figcaption>\n        </figure>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">5.</span> Ph\u00e2n T\u00edch \u0110\u1ed9 L\u1ec7ch Chuy\u00ean S\u00e2u (Ablation Studies)</h3>\n        \n        <div class=\"paper-table-wrapper\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 6: Nghi\u00ean c\u1ee9u \u0111\u1ed9 l\u1ec7ch ki\u1ebfn tr\u00fac c\u00e1c kh\u1ed1i m\u1ea1ng (Network Blocks Ablation).</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr><th>C\u1ea5u H\u00ecnh Th\u1eed Nghi\u1ec7m</th><th>Params (M) \u2193</th><th>MACs (G) \u2193</th><th>PSNR (dB) \u2191</th><th>SSIM \u2191</th></tr>\n                </thead>\n                <tbody>\n                    <tr><td>EBlock thay b\u1eb1ng NAFBlock</td><td>3.12M</td><td>7.69G</td><td>26.51</td><td>0.876</td></tr>\n                    <tr><td>EBlock th\u00eam bi\u1ebfn \u0111\u1ed5i Pha</td><td>4.08M</td><td>8.38G</td><td>26.30</td><td>0.871</td></tr>\n                    <tr><td>To\u00e0n b\u1ed9 m\u1ea1ng l\u00e0 DBlock</td><td>3.20M</td><td>8.19G</td><td>26.68</td><td>0.876</td></tr>\n                    <tr><td>To\u00e0n b\u1ed9 m\u1ea1ng l\u00e0 EBlock</td><td>3.44M</td><td>6.46G</td><td>26.17</td><td>0.863</td></tr>\n                    <tr><td>To\u00e0n b\u1ed9 m\u1ea1ng l\u00e0 NAFBlock [7]</td><td>3.04M</td><td>7.29G</td><td>26.24</td><td>0.868</td></tr>\n                    <tr><td>DBlock thay b\u1eb1ng NAFBlock</td><td>3.24M</td><td>6.84G</td><td>26.23</td><td>0.864</td></tr>\n                    <tr><td>DBlock b\u1ecf Depthwise m\u1edf r\u1ed9ng</td><td>3.27M</td><td>6.99G</td><td>26.63</td><td>0.875</td></tr>\n                    <tr style=\"font-weight: bold; color: #38BDF8;\"><td>DarkIR-m (\u0110\u1ea7y \u0111\u1ee7 c\u1ea5u h\u00ecnh)</td><td>3.31M</td><td>7.25G</td><td class=\"best\">26.90</td><td class=\"best\">0.874</td></tr>\n                </tbody>\n            </table>\n        </div>\n\n        <div class=\"paper-table-wrapper\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 7: Nghi\u00ean c\u1ee9u c\u01a1 ch\u1ebf ch\u00fa \u00fd kh\u00f4ng gian: Large Kernel Attention (LKA) so v\u1edbi Di-SpAM \u0111\u1ec1 xu\u1ea5t.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr><th>C\u01a1 Ch\u1ebf Ch\u00fa \u00dd Kh\u00f4ng Gian</th><th>Params (M) \u2193</th><th>MACs (G) \u2193</th><th>PSNR (dB) \u2191</th><th>SSIM \u2191</th></tr>\n                </thead>\n                <tbody>\n                    <tr><td>Large Kernel Attention (LKA) [17]</td><td>4.06M</td><td>9.14G</td><td>26.45</td><td>0.876</td></tr>\n                    <tr style=\"font-weight: bold; color: #38BDF8;\"><td>Di-SpAM (DarkIR-m \u0110\u1ec1 xu\u1ea5t)</td><td>3.31M</td><td>7.25G</td><td class=\"best\">27.00</td><td class=\"best\">0.883</td></tr>\n                </tbody>\n            </table>\n        </div>\n\n        <div class=\"paper-table-wrapper\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 8: Kh\u1ea3 n\u0103ng m\u1edf r\u1ed9ng quy m\u00f4 m\u1ea1ng theo s\u1ed1 k\u00eanh embedding.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr><th>Phi\u00ean B\u1ea3n DarkIR</th><th>S\u1ed1 K\u00eanh</th><th>Params (M) \u2193</th><th>MACs (G) \u2193</th><th>PSNR (dB) \u2191</th><th>SSIM \u2191</th></tr>\n                </thead>\n                <tbody>\n                    <tr><td>DarkIR-s (B\u1ea3n si\u00eau nh\u1eb9)</td><td>16</td><td>0.872M</td><td>2.04G</td><td>26.15</td><td>0.857</td></tr>\n                    <tr style=\"font-weight: bold; color: #38BDF8;\"><td>DarkIR-m (B\u1ea3n ti\u00eau chu\u1ea9n)</td><td>32</td><td>3.31M</td><td>7.25G</td><td>27.00</td><td>0.883</td></tr>\n                    <tr style=\"font-weight: bold; color: #A78BFA;\"><td>DarkIR-l (B\u1ea3n hi\u1ec7u n\u0103ng cao)</td><td>64</td><td>12.96M</td><td>27.19G</td><td class=\"best\">27.30</td><td class=\"best\">0.898</td></tr>\n                </tbody>\n            </table>\n        </div>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">5.</span> Th\u1ea3o Lu\u1eadn V\u1ec1 Hi\u1ec7u Qu\u1ea3 T\u00ednh To\u00e1n & Gi\u1edbi H\u1ea1n</h3>\n        <p>\n            Nh\u1edd thi\u1ebft k\u1ebf kh\u1ed1i EBlock v\u00e0 DBlock chuy\u00ean bi\u1ec7t, DarkIR gi\u1ea3m t\u1edbi <strong>55% tham s\u1ed1</strong> so v\u1edbi SOTA c\u0169 LEDNet [65] v\u00e0 <strong>88% tham s\u1ed1</strong> so v\u1edbi Restormer [57]. V\u1ec1 \u0111\u1ed9 ph\u1ee9c t\u1ea1p ph\u00e9p t\u00ednh tr\u00ean \u1ea3nh $256 \\times 256$, LEDNet ti\u00eau t\u1ed1n 33.74 GMACs v\u00e0 Restormer ti\u00eau t\u1ed1n 141.24 GMACs, trong khi DarkIR ch\u1ec9 ti\u00eau t\u1ed1n <strong>7.25 GMACs</strong> \u2014 t\u01b0\u01a1ng \u0111\u01b0\u01a1ng m\u1ee9c c\u1eaft gi\u1ea3m 4 l\u1ea7n so v\u1edbi LEDNet v\u00e0 g\u1ea7n 20 l\u1ea7n so v\u1edbi Restormer!\n        </p>\n        <p>\n            <strong>Gi\u1edbi h\u1ea1n c\u1ee7a m\u00f4 h\u00ecnh (Limitations):</strong> M\u1eb7c d\u00f9 DarkIR gi\u1ea3m thi\u1ec3u r\u1ea5t nhi\u1ec1u ph\u00e9p to\u00e1n, m\u00f4 h\u00ecnh s\u1eed d\u1ee5ng nhi\u1ec1u l\u1edbp t\u00edch ch\u1eadp s\u00e2u (Depth-wise Convolutions). Tr\u00ean m\u1ed9t s\u1ed1 ki\u1ebfn tr\u00fac GPU nh\u1ea5t \u0111\u1ecbnh, Depth-wise Convolutions c\u00f3 c\u01b0\u1eddng \u0111\u1ed9 s\u1ed1 h\u1ecdc (arithmetic intensity) th\u1ea5p [15], d\u1eabn \u0111\u1ebfn vi\u1ec7c th\u1eddi gian th\u1ef1c thi (latency) kh\u00f4ng gi\u1ea3m tuy\u1ebfn t\u00ednh tuy\u1ec7t \u0111\u1ed1i theo m\u1ee9c gi\u1ea3m c\u1ee7a GMACs.\n        </p>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">6.</span> K\u1ebft Lu\u1eadn & \u0110\u1ecbnh H\u01b0\u1edbng \u0110\u1ed3 \u00c1n Cao H\u1ecdc UIT</h3>\n        <p>\n            DarkIR \u0111\u00e3 ch\u1ee9ng minh r\u1eb1ng m\u1ed9t m\u1ea1ng CNN ph\u00e2n c\u1ea5p b\u1ea5t \u0111\u1ed1i x\u1ee9ng, ph\u1ed1i h\u1ee3p mi\u1ec1n kh\u00f4ng gian tr\u01b0\u1eddng nh\u00ecn r\u1ed9ng v\u00e0 mi\u1ec1n t\u1ea7n s\u1ed1 Fourier, c\u00f3 th\u1ec3 \u0111\u00e1nh b\u1ea1i c\u00e1c m\u00f4 h\u00ecnh Vision Transformer kh\u1ed5ng l\u1ed3 tr\u00ean b\u00e0i to\u00e1n ph\u1ee5c h\u1ed3i \u1ea3nh thi\u1ebfu s\u00e1ng ch\u1ee5p \u0111\u00eam, m\u1edf ra gi\u1ea3i ph\u00e1p t\u1ed1i \u01b0u cho c\u00e1c thi\u1ebft b\u1ecb c\u00f3 t\u00e0i nguy\u00ean ph\u1ea7n c\u1ee9ng gi\u1edbi h\u1ea1n.\n        </p>\n        <p>\n            \u0110\u1ed1i v\u1edbi \u0110\u1ed3 \u00e1n m\u00f4n h\u1ecdc CS2203 c\u1ee7a ch\u00fang ta t\u1ea1i UIT, nh\u1eefng b\u00e0i h\u1ecdc load-bearing \u0111\u01b0\u1ee3c r\u00fat ra v\u00e0 k\u1ebf th\u1eeba tr\u1ef1c ti\u1ebfp bao g\u1ed3m:\n        </p>\n        <ol>\n            <li><strong>Ch\u1ed1ng r\u00f2 r\u1ec9 nhi\u1ec5u qua Skip Connections:</strong> \u0110\u1eb7t l\u1edbp c\u1ed5ng ch\u1ecdn l\u1ecdc (gating) tr\u01b0\u1edbc khi truy\u1ec1n \u0111\u1eb7c tr\u01b0ng sang Decoder.</li>\n            <li><strong>H\u00e0m m\u1ea5t m\u00e1t Composite:</strong> K\u1ebft h\u1ee3p b\u1eaft bu\u1ed9c $L_1$ + SSIM + Gradient Edge Loss \u0111\u1ec3 gi\u1eef \u0111\u1ed9 s\u1eafc n\u00e9t bi\u00ean.</li>\n            <li><strong>Ki\u1ebfn tr\u00fac Compact U-Net:</strong> Gi\u1eef s\u1ed1 l\u01b0\u1ee3ng tham s\u1ed1 d\u01b0\u1edbi 1.5M params, \u0111\u1ea3m b\u1ea3o ch\u1ea1y m\u01b0\u1ee3t m\u00e0 tr\u00ean m\u00f4i tr\u01b0\u1eddng t\u00ednh to\u00e1n th\u1ef1c t\u1ebf.</li>\n        </ol>\n    </div>\n</article>\n",
    "ntire2024": "\n<article class=\"paper-article\">\n    <div class=\"paper-reader-toolbar\">\n        <div class=\"paper-toolbar-group\">\n            <span style=\"font-weight: 700; color: #10B981; font-size: 0.85rem;\">CVPRW 2024 Paper Reader (Full Translation)</span>\n            <button class=\"paper-tool-btn btn-col-toggle\" onclick=\"togglePaperColumns('ntire2024')\">\ud83d\udcc4 Ch\u1ebf \u0110\u1ed9 1 C\u1ed9t (D\u1ecdc)</button>\n        </div>\n        <div class=\"paper-toolbar-group\">\n            <a href=\"papers/ntire2024.html\" target=\"_blank\" class=\"paper-tool-btn\">\u2197\ufe0f M\u1edf Trang \u0110\u1ed9c L\u1eadp To\u00e0n M\u00e0n H\u00ecnh</a>\n            <button class=\"paper-tool-btn\" onclick=\"closePaperReader('ntire2024')\">\u2715 \u0110\u00f3ng B\u00e0i B\u00e1o</button>\n        </div>\n    </div>\n\n    <header class=\"paper-header\">\n        <span class=\"paper-venue-badge\" style=\"background: rgba(16, 185, 129, 0.12); color: #10B981; border-color: rgba(16, 185, 129, 0.35);\">IEEE / CVF CVPRW 2024 \u2022 NTIRE WORKSHOP \u2022 BENCHMARK CHALLENGE</span>\n        <h1 class=\"paper-title\">B\u00e1o C\u00e1o Cu\u1ed9c Thi NTIRE 2024 V\u1ec1 T\u0103ng C\u01b0\u1eddng \u1ea2nh Thi\u1ebfu S\u00e1ng: Ph\u01b0\u01a1ng Ph\u00e1p v\u00e0 K\u1ebft Qu\u1ea3</h1>\n        <h2 class=\"paper-title-en\">NTIRE 2024 Challenge on Low Light Image Enhancement: Methods and Results</h2>\n        <div class=\"paper-authors\">\n            <strong>Zheyuan Liu</strong>, <strong>Chi-Man Pun</strong>, <strong>Radu Timofte</strong>, c\u00f9ng ban t\u1ed5 ch\u1ee9c NTIRE 2024 v\u00e0 22 \u0111\u1ed9i thi\n        </div>\n        <div class=\"paper-affiliations\">\n            \u0110\u1ea1i h\u1ecdc Macau, \u0110\u1ea1i h\u1ecdc W\u00fcrzburg (CHLB \u0110\u1ee9c), ETH Zurich (Th\u1ee5y S\u0129), c\u00f9ng c\u00e1c vi\u1ec7n nghi\u00ean c\u1ee9u qu\u1ed1c t\u1ebf\n        </div>\n        <div class=\"paper-links-row\">\n            <a href=\"https://cvlai.net/ntire/2024/\" target=\"_blank\" class=\"paper-ext-link\">\ud83c\udf10 C\u1ed5ng Th\u00f4ng Tin NTIRE 2024: cvlai.net/ntire/2024</a>\n            <a href=\"../papers/Liu_NTIRE_2024_Challenge_on_Low_Light_Image_Enhancement_Methods_and_CVPRW_2024_paper.pdf\" target=\"_blank\" class=\"paper-ext-link\">\ud83d\udcd1 T\u1ea3i File PDF To\u00e0n V\u0103n CVPRW (3.5 MB)</a>\n        </div>\n    </header>\n\n    <div class=\"paper-abstract-box\">\n        <div class=\"paper-abstract-title\">T\u00f3m T\u1eaft B\u00e1o C\u00e1o Cu\u1ed9c Thi (Challenge Abstract)</div>\n        <p class=\"paper-abstract-text\">\n            B\u00e0i b\u00e1o n\u00e0y t\u1ed5ng k\u1ebft v\u00e0 ph\u00e2n t\u00edch to\u00e0n di\u1ec7n cu\u1ed9c thi <strong>NTIRE 2024 Challenge on Low Light Image Enhancement</strong> \u0111\u01b0\u1ee3c t\u1ed5 ch\u1ee9c trong khu\u00f4n kh\u1ed5 h\u1ed9i ngh\u1ecb CVPR 2024. M\u1ee5c ti\u00eau c\u1ee7a cu\u1ed9c thi l\u00e0 th\u00fac \u0111\u1ea9y gi\u1edbi h\u1ea1n nghi\u00ean c\u1ee9u v\u1ec1 t\u0103ng c\u01b0\u1eddng \u1ea3nh thi\u1ebfu s\u00e1ng trong c\u00e1c \u0111i\u1ec1u ki\u1ec7n ch\u1ee5p th\u1ef1c t\u1ebf \u0111\u1ea7y kh\u1eafc nghi\u1ec7t (\u00e1nh s\u00e1ng c\u1ef1c t\u1ed1i, chi\u1ebfu s\u00e1ng kh\u00f4ng \u0111\u1ed3ng \u0111\u1ec1u, ng\u01b0\u1ee3c s\u00e1ng m\u1ea1nh, v\u00e0 c\u1ea3nh \u0111\u00eam \u0111\u00f4 th\u1ecb ph\u1ee9c t\u1ea1p) v\u1edbi \u0111\u1ed9 ph\u00e2n gi\u1ea3i l\u00ean \u0111\u1ebfn 4K. Cu\u1ed9c thi \u0111\u00e3 thu h\u00fat h\u01a1n <strong>230 \u0111\u1ed9i nghi\u00ean c\u1ee9u</strong> \u0111\u0103ng k\u00fd tham gia t\u1eeb c\u00e1c tr\u01b0\u1eddng \u0111\u1ea1i h\u1ecdc v\u00e0 ph\u00f2ng lab AI h\u00e0ng \u0111\u1ea7u th\u1ebf gi\u1edbi, trong \u0111\u00f3 c\u00f3 <strong>22 gi\u1ea3i ph\u00e1p ho\u00e0n ch\u1ec9nh</strong> v\u01b0\u1ee3t qua v\u00f2ng ki\u1ec3m th\u1eed g\u1eaft gao tr\u00ean m\u00e1y ch\u1ee7 \u0111\u1ed9c l\u1eadp c\u1ee7a ban t\u1ed5 ch\u1ee9c. C\u00e1c gi\u1ea3i ph\u00e1p tham d\u1ef1 \u0111\u1ea1i di\u1ec7n cho c\u00e1c xu h\u01b0\u1edbng c\u00f4ng ngh\u1ec7 ti\u00ean ti\u1ebfn nh\u1ea5t hi\u1ec7n nay: t\u1eeb c\u00e1c bi\u1ebfn th\u1ec3 Vision Transformer ph\u00e2n c\u1ea5p, m\u1ea1ng n\u01a1-ron t\u00edch ch\u1eadp \u0111a mi\u1ec1n kh\u00f4ng gian-t\u1ea7n s\u1ed1, \u0111\u1ebfn c\u00e1c m\u00f4 h\u00ecnh khu\u1ebfch t\u00e1n \u0111i\u1ec1u ki\u1ec7n (Conditional Diffusion Models) v\u00e0 c\u00e1c k\u1ef9 thu\u1eadt c\u0103n ch\u1ec9nh ph\u1ea3n x\u1ea1 Retinex. B\u00e1o c\u00e1o n\u00e0y c\u00f4ng b\u1ed1 b\u1ea3ng x\u1ebfp h\u1ea1ng ch\u00ednh th\u1ee9c, ph\u00e2n t\u00edch s\u00e2u c\u00e1c \u01b0u nh\u01b0\u1ee3c \u0111i\u1ec3m k\u1ef9 thu\u1eadt c\u1ee7a t\u1eebng tr\u01b0\u1eddng ph\u00e1i, v\u00e0 v\u1ea1ch ra xu h\u01b0\u1edbng nghi\u00ean c\u1ee9u t\u01b0\u01a1ng lai cho b\u00e0i to\u00e1n ph\u1ee5c h\u1ed3i \u1ea3nh thi\u1ebfu s\u00e1ng th\u1ebf gi\u1edbi th\u1ef1c.\n        </p>\n    </div>\n\n    <!-- Figure 1 -->\n    <figure class=\"paper-figure full-width\">\n        <img src=\"assets/images/papers/ntire2024/fig_1_p3.png\" alt=\"NTIRE 2024 Sample Dataset Images\">\n        <figcaption class=\"paper-figcaption\">\n            <strong>H\u00ecnh 1: C\u00e1c m\u1eabu \u1ea3nh th\u1ef1c nghi\u1ec7m trong t\u1eadp d\u1eef li\u1ec7u NTIRE 2024 Low Light Challenge.</strong> T\u1eadp d\u1eef li\u1ec7u bao g\u1ed3m d\u1ea3i t\u01b0\u01a1ng ph\u1ea3n c\u1ef1c r\u1ed9ng: t\u1eeb thi\u1ebfu s\u00e1ng nh\u1eb9 trong nh\u00e0, ng\u01b0\u1ee3c s\u00e1ng g\u1eaft (backlighting), chi\u1ebfu s\u00e1ng kh\u00f4ng \u0111\u1ed3ng \u0111\u1ec1u (non-uniform illumination), \u0111\u1ebfn b\u00f3ng t\u1ed1i c\u1ef1c \u0111\u1ed9 (extreme darkness) v\u1edbi \u0111\u1ed9 ph\u00e2n gi\u1ea3i si\u00eau n\u00e9t l\u00ean t\u1edbi 4K. (Nh\u1ea5p chu\u1ed9t \u0111\u1ec3 ph\u00f3ng to).\n        </figcaption>\n    </figure>\n\n    <div class=\"paper-content-columns\">\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">1.</span> Gi\u1edbi Thi\u1ec7u B\u1ed1i C\u1ea3nh Cu\u1ed9c Thi (Introduction)</h3>\n        <p>\n            Ch\u1ee5p \u1ea3nh trong \u0111i\u1ec1u ki\u1ec7n \u00e1nh s\u00e1ng y\u1ebfu (Low-Light Imaging) l\u00e0 b\u00e0i to\u00e1n then ch\u1ed1t trong c\u00e1c h\u1ec7 th\u1ed1ng th\u1ecb gi\u00e1c m\u00e1y t\u00ednh v\u00e0 nhi\u1ebfp \u1ea3nh di \u0111\u1ed9ng. Trong \u0111i\u1ec1u ki\u1ec7n thi\u1ebfu s\u00e1ng nghi\u00eam tr\u1ecdng, \u1ea3nh ch\u1ee5p t\u1eeb c\u1ea3m bi\u1ebfn di \u0111\u1ed9ng b\u1ecb suy tho\u00e1i \u0111a chi\u1ec1u: m\u1ea5t chi ti\u1ebft \u1edf v\u00f9ng t\u1ed1i (underexposure), nhi\u1ec5u h\u1ea1t c\u1ea3m bi\u1ebfn d\u00e0y \u0111\u1eb7c (heavy sensor noise), v\u00e0 sai l\u1ec7ch d\u1ea3i m\u00e0u s\u1eafc (severe color casts).\n        </p>\n        <p>\n            M\u1eb7c d\u00f9 c\u00e1c b\u1ed9 d\u1eef li\u1ec7u tr\u01b0\u1edbc \u0111\u00e2y nh\u01b0 LOL [71] hay MIT-Adobe FiveK [7] \u0111\u00e3 th\u00fac \u0111\u1ea9y nhi\u1ec1u ti\u1ebfn b\u1ed9 ban \u0111\u1ea7u, ch\u00fang t\u1ed3n t\u1ea1i nh\u1eefng h\u1ea1n ch\u1ebf c\u1ed1t l\u00f5i nghi\u00eam tr\u1ecdng:\n        </p>\n        <ul>\n            <li>\u0110\u1ed9 ph\u00e2n gi\u1ea3i th\u1ea5p (ch\u1ee7 y\u1ebfu l\u00e0 $400 \\times 600$ ho\u1eb7c $1000 \\times 600$), kh\u00f4ng ph\u1ea3n \u00e1nh \u0111\u00fang chu\u1ea9n camera di \u0111\u1ed9ng 12MP\u201348MP hi\u1ec7n nay.</li>\n            <li>B\u1ed1i c\u1ea3nh chi\u1ebfu s\u00e1ng \u0111\u1ed3ng nh\u1ea5t v\u00e0 \u0111\u01a1n \u0111i\u1ec7u, thi\u1ebfu v\u1eafng c\u00e1c tr\u01b0\u1eddng h\u1ee3p ph\u1ee9c t\u1ea1p nh\u01b0 ng\u01b0\u1ee3c s\u00e1ng m\u1ea1nh, \u0111\u00e8n flash c\u1ee5c b\u1ed9 hay qu\u1ea7ng s\u00e1ng \u0111\u00eam.</li>\n            <li>Kh\u1ea3 n\u0103ng t\u1ed5ng qu\u00e1t h\u00f3a (generalization) c\u1ee7a c\u00e1c m\u00f4 h\u00ecnh hu\u1ea5n luy\u1ec7n tr\u00ean d\u1eef li\u1ec7u c\u0169 b\u1ecb s\u1ee5t gi\u1ea3m nghi\u00eam tr\u1ecdng khi \u0111\u1ed1i m\u1eb7t v\u1edbi \u1ea3nh ch\u1ee5p th\u1ef1c t\u1ebf.</li>\n        </ul>\n        <p>\n            Cu\u1ed9c thi NTIRE 2024 \u0111\u01b0\u1ee3c thi\u1ebft l\u1eadp nh\u1eb1m kh\u1eafc ph\u1ee5c c\u00e1c r\u00e0o c\u1ea3n tr\u00ean b\u1eb1ng c\u00e1ch x\u00e2y d\u1ef1ng m\u1ed9t b\u1ed9 d\u1eef li\u1ec7u chu\u1ea9n m\u1edbi v\u1edbi 3 m\u1ee5c ti\u00eau chi\u1ebfn l\u01b0\u1ee3c: (1) Th\u00fac \u0111\u1ea9y c\u00e1c ki\u1ebfn tr\u00fac m\u00f4 h\u00ecnh b\u1ec1n v\u1eefng tr\u01b0\u1edbc suy tho\u00e1i th\u1ebf gi\u1edbi th\u1ef1c; (2) So s\u00e1nh c\u00f3 h\u1ec7 th\u1ed1ng gi\u1eefa c\u00e1c tr\u01b0\u1eddng ph\u00e1i (CNN, Transformer, Diffusion); v\u00e0 (3) K\u1ebft n\u1ed1i c\u1ed9ng \u0111\u1ed3ng h\u1ecdc thu\u1eadt v\u1edbi c\u00e1c \u1ee9ng d\u1ee5ng c\u00f4ng nghi\u1ec7p nhi\u1ebfp \u1ea3nh t\u00ednh to\u00e1n.\n        </p>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">2.</span> Thi\u1ebft K\u1ebf Cu\u1ed9c Thi & B\u1ed9 D\u1eef Li\u1ec7u (Challenge Protocol)</h3>\n        <p>\n            B\u1ed9 d\u1eef li\u1ec7u NTIRE 2024 Low Light bao g\u1ed3m:\n        </p>\n        <ul>\n            <li><strong>230 c\u1eb7p \u1ea3nh hu\u1ea5n luy\u1ec7n (Train):</strong> Cung c\u1ea5p \u0111\u1ea7y \u0111\u1ee7 \u1ea3nh thi\u1ebfu s\u00e1ng \u0111\u1ea7u v\u00e0o v\u00e0 \u1ea3nh chu\u1ea9n ph\u01a1i s\u00e1ng (Ground Truth).</li>\n            <li><strong>35 \u1ea3nh ki\u1ec3m th\u1eed ph\u00e1t tri\u1ec3n (Validation):</strong> \u1ea2nh GT \u0111\u01b0\u1ee3c gi\u1eef k\u00edn tr\u00ean m\u00e1y ch\u1ee7 \u0111\u00e1nh gi\u00e1 CodaLab.</li>\n            <li><strong>35 \u1ea3nh ki\u1ec3m th\u1eed ch\u00ednh th\u1ee9c (Test):</strong> Ho\u00e0n to\u00e0n b\u1ea3o m\u1eadt, c\u00e1c \u0111\u1ed9i thi n\u1ed9p m\u00e3 ngu\u1ed3n v\u00e0 m\u00f4 h\u00ecnh \u0111\u1ec3 ban t\u1ed5 ch\u1ee9c ch\u1ea1y suy lu\u1eadn \u0111\u1ed9c l\u1eadp (blind evaluation).</li>\n        </ul>\n        <p>\n            <strong>Ti\u00eau chu\u1ea9n x\u1ebfp h\u1ea1ng ch\u00ednh th\u1ee9c (Ranking Metric):</strong> Ban t\u1ed5 ch\u1ee9c \u00e1p d\u1ee5ng \u0111i\u1ec3m s\u1ed1 t\u1ed5ng h\u1ee3p d\u1ef1a tr\u00ean tr\u1ecdng s\u1ed1 chu\u1ea9n h\u00f3a gi\u1eefa \u0111\u1ed9 ch\u00ednh x\u00e1c t\u00e1i t\u1ea1o \u0111i\u1ec3m \u1ea3nh v\u00e0 \u0111\u1ed9 t\u01b0\u01a1ng \u0111\u1ed3ng c\u1ea5u tr\u00fac:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$\\text{Final Score} = 0.60 \\times \\text{Rank}_{PSNR} + 0.40 \\times \\text{Rank}_{SSIM}$$</div>\n            <span class=\"paper-equation-num\">(1)</span>\n        </div>\n        <p>\n            Ch\u1ec9 s\u1ed1 c\u1ea3m nh\u1eadn tri gi\u00e1c <strong>LPIPS</strong> [80] \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng l\u00e0m ti\u00eau ch\u00ed ph\u1ee5 ph\u00e2n \u0111\u1ecbnh th\u1ee9 h\u1ea1ng khi hai ph\u01b0\u01a1ng ph\u00e1p c\u00f3 \u0111i\u1ec3m s\u1ed1 PSNR/SSIM t\u01b0\u01a1ng \u0111\u01b0\u01a1ng.\n        </p>\n\n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 1: B\u1ea3ng X\u1ebfp H\u1ea1ng To\u00e0n B\u1ed9 22 \u0110\u1ed9i Thi T\u1ea1i Cu\u1ed9c Thi NTIRE 2024 Low Light Image Enhancement Challenge.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>T\u00ean \u0110\u1ed9i Thi (Team)</th>\n                        <th>PSNR (dB) \u2191</th>\n                        <th>SSIM \u2191</th>\n                        <th>LPIPS \u2193</th>\n                        <th>H\u1ea1ng PSNR</th>\n                        <th>H\u1ea1ng SSIM</th>\n                        <th>X\u1ebfp H\u1ea1ng Chung Cu\u1ed9c</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr style=\"background: rgba(16, 185, 129, 0.15); font-weight: bold;\">\n                        <td style=\"color: #10B981;\">\ud83e\udd47 SYSU-FVL-T2</td>\n                        <td class=\"best\">25.52</td>\n                        <td class=\"best\">0.8637</td>\n                        <td>0.1221</td>\n                        <td>1</td>\n                        <td>1</td>\n                        <td style=\"color: #10B981;\">H\u1ea1ng 1 (Qu\u00e1n Qu\u00e2n)</td>\n                    </tr>\n                    <tr style=\"background: rgba(56, 189, 248, 0.12); font-weight: bold;\">\n                        <td style=\"color: #38BDF8;\">\ud83e\udd48 Retinexformer [8]</td>\n                        <td>25.30</td>\n                        <td>0.8525</td>\n                        <td>0.1424</td>\n                        <td>2</td>\n                        <td>4</td>\n                        <td style=\"color: #38BDF8;\">H\u1ea1ng 2 (\u00c1 Qu\u00e2n 1)</td>\n                    </tr>\n                    <tr style=\"background: rgba(245, 158, 11, 0.12); font-weight: bold;\">\n                        <td style=\"color: #F59E0B;\">\ud83e\udd49 DH-AISP</td>\n                        <td>24.97</td>\n                        <td>0.8528</td>\n                        <td>0.1235</td>\n                        <td>3</td>\n                        <td>3</td>\n                        <td style=\"color: #F59E0B;\">H\u1ea1ng 3 (\u00c1 Qu\u00e2n 2)</td>\n                    </tr>\n                    <tr><td>NWPU-DiffLight</td><td>24.78</td><td>0.8556</td><td>0.1673</td><td>6</td><td>2</td><td>H\u1ea1ng 4</td></tr>\n                    <tr><td>GiantPandaCV</td><td>24.83</td><td>0.8474</td><td>0.1353</td><td>5</td><td>7</td><td>H\u1ea1ng 5</td></tr>\n                    <tr><td>LVGroup HFUT</td><td>24.88</td><td>0.8395</td><td>0.1371</td><td>4</td><td>10</td><td>H\u1ea1ng 6</td></tr>\n                    <tr><td>Try1try8</td><td>24.49</td><td>0.8483</td><td>0.1359</td><td>8</td><td>6</td><td>H\u1ea1ng 7</td></tr>\n                    <tr><td>Pixel warrior</td><td>24.74</td><td>0.8416</td><td>0.1514</td><td>7</td><td>9</td><td>H\u1ea1ng 8</td></tr>\n                    <tr><td>HuiT</td><td>24.13</td><td>0.8484</td><td>0.1436</td><td>10</td><td>5</td><td>H\u1ea1ng 9</td></tr>\n                    <tr><td>X-LIME</td><td>24.28</td><td>0.8446</td><td>0.1298</td><td>9</td><td>8</td><td>H\u1ea1ng 10</td></tr>\n                    <tr><td>Image Lab</td><td>23.63</td><td>0.8235</td><td>0.1673</td><td>11</td><td>12</td><td>H\u1ea1ng 11</td></tr>\n                    <tr><td>dgzzqteam</td><td>23.28</td><td>0.8385</td><td>0.1406</td><td>12</td><td>11</td><td>H\u1ea1ng 12</td></tr>\n                    <tr style=\"background: rgba(99, 102, 241, 0.10);\">\n                        <td>Cidaut AI (InstructIR [23])</td>\n                        <td>23.07</td>\n                        <td>0.8075</td>\n                        <td>0.1559</td>\n                        <td>13</td>\n                        <td>16</td>\n                        <td>H\u1ea1ng 13 (Nh\u00f3m t\u00e1c gi\u1ea3 DarkIR)</td>\n                    </tr>\n                    <tr><td>OptDev</td><td>22.93</td><td>0.8097</td><td>0.1592</td><td>14</td><td>15</td><td>H\u1ea1ng 14</td></tr>\n                    <tr><td>ataza</td><td>22.51</td><td>0.8161</td><td>0.1404</td><td>18</td><td>13</td><td>H\u1ea1ng 15</td></tr>\n                    <tr><td>KLETech-CEVI LowlightHypnotise</td><td>22.85</td><td>0.7828</td><td>0.1823</td><td>15</td><td>18</td><td>H\u1ea1ng 16</td></tr>\n                    <tr style=\"background: rgba(236, 72, 153, 0.12); font-weight: bold;\">\n                        <td style=\"color: #EC4899;\">\u2b50 221B</td>\n                        <td>22.04</td>\n                        <td>0.8141</td>\n                        <td class=\"best\" style=\"color: #EC4899;\">0.1084</td>\n                        <td>19</td>\n                        <td>14</td>\n                        <td>H\u1ea1ng 17 (Top 1 LPIPS Tri Gi\u00e1c)</td>\n                    </tr>\n                    <tr><td>KLETech-CEVI Dark Knights</td><td>22.76</td><td>0.7843</td><td>0.1806</td><td>17</td><td>17</td><td>H\u1ea1ng 18</td></tr>\n                    <tr><td>BFU-LL</td><td>22.78</td><td>0.7792</td><td>0.1826</td><td>16</td><td>19</td><td>H\u1ea1ng 19</td></tr>\n                    <tr><td>SVNIT NTNU</td><td>20.32</td><td>0.7718</td><td>0.3089</td><td>20</td><td>20</td><td>H\u1ea1ng 20</td></tr>\n                    <tr><td>yanhailong</td><td>20.07</td><td>0.6881</td><td>0.3133</td><td>21</td><td>22</td><td>H\u1ea1ng 21</td></tr>\n                    <tr><td>Mishka</td><td>18.19</td><td>0.7161</td><td>0.2712</td><td>22</td><td>21</td><td>H\u1ea1ng 22</td></tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 2 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/ntire2024/fig_2_p5.png\" alt=\"NTIRE 2024 Visual Comparison Val Set\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 2: So s\u00e1nh tr\u1ef1c quan c\u00e1c gi\u1ea3i ph\u00e1p tham d\u1ef1 tr\u00ean t\u1eadp Validation.</strong> C\u00e1c ph\u01b0\u01a1ng ph\u00e1p h\u00e0ng \u0111\u1ea7u th\u1ec3 hi\u1ec7n kh\u1ea3 n\u0103ng c\u00e2n b\u1eb1ng \u00e1nh s\u00e1ng v\u01b0\u1ee3t tr\u1ed9i t\u1ea1i c\u00e1c v\u00f9ng b\u00f3ng \u0111\u1ed5 s\u00e2u m\u00e0 kh\u00f4ng l\u00e0m ch\u00e1y s\u00e1ng c\u00e1c \u00f4 c\u1eeda s\u1ed5 hay \u0111\u00e8n \u0111\u01b0\u1eddng.\n            </figcaption>\n        </figure>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">3.</span> Ph\u00e2n T\u00edch C\u00e1c Tr\u01b0\u1eddng Ph\u00e1i C\u00f4ng Ngh\u1ec7 H\u00e0ng \u0110\u1ea7u</h3>\n        \n        <h4 class=\"paper-sub-heading\">3.1 Tr\u01b0\u1eddng Ph\u00e1i Hybrid Transformer (\u0110\u1ed9i V\u00f4 \u0110\u1ecbch SYSU-FVL-T2)</h4>\n        <p>\n            \u0110\u1ed9i chi\u1ebfn th\u1eafng SYSU-FVL-T2 s\u1eed d\u1ee5ng ki\u1ebfn tr\u00fac ph\u00e2n c\u1ea5p k\u1ebft h\u1ee3p c\u01a1 ch\u1ebf ch\u00fa \u00fd t\u1ef1 th\u00e2n c\u00f3 \u0111\u1ecbnh h\u01b0\u1edbng mi\u1ec1n t\u1ea7n s\u1ed1 (Frequency-Guided Self-Attention). Nh\u00f3m nh\u1eadn th\u1ea5y r\u1eb1ng vi\u1ec7c t\u00ednh to\u00e1n Self-Attention tr\u00ean to\u00e0n b\u1ed9 \u1ea3nh 4K l\u00e0 b\u1ea5t kh\u1ea3 thi v\u1ec1 m\u1eb7t b\u1ed9 nh\u1edb GPU. Do \u0111\u00f3, h\u1ecd \u00e1p d\u1ee5ng k\u1ef9 thu\u1eadt chia kh\u1ed1i kh\u00f4ng gian th\u00edch nghi k\u1ebft h\u1ee3p v\u1edbi vi\u1ec7c \u01b0\u1edbc l\u01b0\u1ee3ng b\u1ea3n \u0111\u1ed3 chi\u1ebfu s\u00e1ng to\u00e0n c\u1ee5c \u1edf mi\u1ec1n t\u1ea7n s\u1ed1 th\u1ea5p (low-frequency Fourier domain), gi\u00fap m\u00f4 h\u00ecnh \u0111\u1ea1t <strong>25.52 dB PSNR</strong> v\u00e0 <strong>0.8637 SSIM</strong>, d\u1eabn \u0111\u1ea7u tuy\u1ec7t \u0111\u1ed1i \u1edf c\u1ea3 hai ti\u00eau ch\u00ed \u0111\u00e1nh gi\u00e1 \u0111\u1ecbnh l\u01b0\u1ee3ng.\n        </p>\n\n        <h4 class=\"paper-sub-heading\">3.2 Tr\u01b0\u1eddng Ph\u00e1i L\u00fd Thuy\u1ebft Retinex N\u00e2ng C\u1ea5p (Retinexformer)</h4>\n        <p>\n            Gi\u1ea3i ph\u00e1p \u0111\u1ea1t v\u1ecb tr\u00ed \u00c1 qu\u00e2n (Retinexformer [8]) k\u1ebft h\u1ee3p l\u00fd thuy\u1ebft v\u1eadt l\u00fd Retinex truy\u1ec1n th\u1ed1ng v\u1edbi s\u1ee9c m\u1ea1nh h\u1ecdc bi\u1ec3u di\u1ec5n c\u1ee7a Vision Transformer. B\u1eb1ng c\u00e1ch s\u1eed d\u1ee5ng b\u1ea3n \u0111\u1ed3 ph\u1ea3n chi\u1ebfu (reflectance) \u0111\u1ec3 gi\u1eef \u1ed5n \u0111\u1ecbnh m\u00e0u s\u1eafc v\u00e0 d\u00f9ng m\u1ea1ng Attention \u0111\u1ec3 d\u1ef1 \u0111o\u00e1n th\u00e0nh ph\u1ea7n chi\u1ebfu s\u00e1ng (illumination), Retinexformer tri\u1ec7t ti\u00eau \u0111\u01b0\u1ee3c hi\u1ec7n t\u01b0\u1ee3ng bi\u1ebfn d\u1ea1ng m\u00e0u s\u1eafc (color shifts), \u0111\u1ea1t <strong>25.30 dB PSNR</strong>.\n        </p>\n\n        <h4 class=\"paper-sub-heading\">3.3 Tr\u01b0\u1eddng Ph\u00e1i M\u00f4 H\u00ecnh Khu\u1ebfch T\u00e1n (NWPU-DiffLight)</h4>\n        <p>\n            \u0110\u1ed9i NWPU-DiffLight ti\u00ean phong \u1ee9ng d\u1ee5ng <em>Conditional Diffusion Models</em> v\u00e0o cu\u1ed9c thi. Kh\u00e1c v\u1edbi c\u00e1c ph\u01b0\u01a1ng ph\u00e1p h\u1ed3i quy tr\u1ef1c ti\u1ebfp (regression-based) th\u01b0\u1eddng t\u1ea1o ra \u1ea3nh h\u01a1i m\u1ecbn ho\u1eb7c b\u1ebft h\u1ea1t, m\u00f4 h\u00ecnh Diffusion sinh ra c\u00e1c chi ti\u1ebft k\u1ebft c\u1ea5u b\u1ec1 m\u1eb7t c\u1ef1c k\u1ef3 t\u1ef1 nhi\u00ean v\u00e0 \u0111\u1ea1t v\u1ecb tr\u00ed th\u1ee9 2 v\u1ec1 SSIM (0.8556). Tuy nhi\u00ean, nh\u01b0\u1ee3c \u0111i\u1ec3m ch\u00ed m\u1ea1ng c\u1ee7a Diffusion l\u00e0 t\u1ed1c \u0111\u1ed9 suy lu\u1eadn ch\u1eadm (c\u1ea7n nhi\u1ec1u b\u01b0\u1edbc l\u1ea5y m\u1eabu kh\u1eed nhi\u1ec5u l\u1eb7p \u0111i l\u1eb7p l\u1ea1i), khi\u1ebfn vi\u1ec7c tri\u1ec3n khai th\u1eddi gian th\u1ef1c tr\u00ean thi\u1ebft b\u1ecb bi\u00ean g\u1eb7p nhi\u1ec1u th\u00e1ch th\u1ee9c.\n        </p>\n\n        <h4 class=\"paper-sub-heading\">3.4 Tr\u01b0\u1eddng Ph\u00e1i T\u1ed1i \u01afu Tri Gi\u00e1c C\u1ea3m Nh\u1eadn (\u0110\u1ed9i 221B)</h4>\n        <p>\n            M\u1eb7c d\u00f9 ch\u1ec9 x\u1ebfp h\u1ea1ng 17 v\u1ec1 ch\u1ec9 s\u1ed1 PSNR do kh\u00f4ng t\u1eadp trung v\u00e0o vi\u1ec7c kh\u1edbp t\u1eebng \u0111i\u1ec3m \u1ea3nh m\u1ee9c x\u00e1m v\u1edbi \u1ea3nh GT, gi\u1ea3i ph\u00e1p c\u1ee7a \u0110\u1ed9i 221B \u0111\u00e3 gi\u00e0nh <strong>V\u1ecb tr\u00ed Qu\u00e1n qu\u00e2n v\u1ec1 ch\u1ec9 s\u1ed1 c\u1ea3m nh\u1eadn LPIPS (0.1084)</strong>. B\u1eb1ng vi\u1ec7c k\u1ebft h\u1ee3p h\u00e0m m\u1ea5t m\u00e1t \u0111\u1ed1i kh\u00e1ng \u0111a t\u1ef7 l\u1ec7 (Multi-scale PatchGAN) v\u00e0 r\u00e0ng bu\u1ed9c \u0111\u1eb7c tr\u01b0ng t\u1ea7ng s\u00e2u c\u1ee7a VGG, \u1ea3nh ph\u1ee5c h\u1ed3i c\u1ee7a \u0111\u1ed9i 221B mang l\u1ea1i c\u1ea3m gi\u00e1c th\u1ecb gi\u00e1c ch\u00e2n th\u1ef1c v\u00e0 s\u1eafc n\u00e9t nh\u1ea5t cho m\u1eaft ng\u01b0\u1eddi quan s\u00e1t.\n        </p>\n\n        <!-- Figure 3, 4, 5 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/ntire2024/fig_3_p7.png\" alt=\"NTIRE 2024 Test Set Comparison\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 3: So s\u00e1nh tr\u1ef1c quan tr\u00ean t\u1eadp ki\u1ec3m th\u1eed ch\u00ednh th\u1ee9c (Test Set).</strong> C\u00e1c m\u00f4 h\u00ecnh h\u00e0ng \u0111\u1ea7u kh\u00f4i ph\u1ee5c r\u00f5 n\u00e9t ch\u1eef vi\u1ebft tr\u00ean bi\u1ec3n hi\u1ec7u v\u00e0 k\u1ebft c\u1ea5u g\u1ea1ch l\u00e1t \u0111\u01b0\u1eddng trong m\u00e0n \u0111\u00eam.\n            </figcaption>\n        </figure>\n\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/ntire2024/fig_4_p8.png\" alt=\"NTIRE 2024 Architecture Restoration Comparison\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 4: T\u00e1i t\u1ea1o chi ti\u1ebft ki\u1ebfn tr\u00fac t\u00f2a nh\u00e0 ban \u0111\u00eam.</strong> C\u00e1c gi\u1ea3i ph\u00e1p \u00e1p d\u1ee5ng c\u01a1 ch\u1ebf mi\u1ec1n t\u1ea7n s\u1ed1 gi\u1eef \u0111\u01b0\u1ee3c \u0111\u1ed9 th\u1eb3ng c\u1ee7a c\u00e1c \u0111\u01b0\u1eddng g\u1edd v\u00e0 tr\u00e1nh qu\u1ea7ng h\u00e0o quang nh\u00e2n t\u1ea1o xung quanh c\u1ed9t \u0111\u00e8n.\n            </figcaption>\n        </figure>\n\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/ntire2024/fig_5_p8.png\" alt=\"NTIRE 2024 Portrait Restoration Comparison\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 5: Ph\u1ee5c h\u1ed3i ch\u00e2n dung ng\u01b0\u1eddi trong \u0111i\u1ec1u ki\u1ec7n ng\u01b0\u1ee3c s\u00e1ng g\u1eaft.</strong> Chi ti\u1ebft bi\u1ec3u c\u1ea3m khu\u00f4n m\u1eb7t v\u00e0 s\u1ee3i t\u00f3c \u0111\u01b0\u1ee3c t\u00e1i hi\u1ec7n r\u00f5 r\u00e0ng m\u00e0 kh\u00f4ng b\u1ecb nhi\u1ec5u m\u00e0u loang l\u1ed5.\n            </figcaption>\n        </figure>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">4.</span> B\u00e0i H\u1ecdc Kinh Nghi\u1ec7m Cho \u0110\u1ed3 \u00c1n Cao H\u1ecdc UIT CS2203</h3>\n        <p>\n            K\u1ebft qu\u1ea3 cu\u1ed9c thi NTIRE 2024 mang l\u1ea1i nh\u1eefng \u0111\u00fac k\u1ebft qu\u00fd gi\u00e1 cho vi\u1ec7c thi\u1ebft k\u1ebf m\u1ea1ng Compact U-Net c\u1ee7a \u0111\u1ed3 \u00e1n:\n        </p>\n        <ol>\n            <li><strong>S\u1ef1 \u0111\u00e1nh \u0111\u1ed5i gi\u1eefa PSNR v\u00e0 LPIPS (Perception-Distortion Trade-off):</strong> T\u1ed1i \u01b0u h\u00f3a \u0111\u01a1n thu\u1ea7n h\u00e0m m\u1ea5t m\u00e1t $L_1$ hay MSE gi\u00fap \u0111\u1ea9y ch\u1ec9 s\u1ed1 PSNR l\u00ean cao nh\u01b0ng d\u1ec5 l\u00e0m m\u1edd \u1ea3nh. B\u1eaft bu\u1ed9c ph\u1ea3i t\u00edch h\u1ee3p h\u00e0m m\u1ea5t m\u00e1t Gradient ho\u1eb7c Edge Loss \u0111\u1ec3 gi\u1eef \u0111\u1ed9 s\u1eafc n\u00e9t.</li>\n            <li><strong>T\u1ea7m quan tr\u1ecdng c\u1ee7a mi\u1ec1n t\u1ea7n s\u1ed1:</strong> C\u1ea3 \u0111\u1ed9i v\u00f4 \u0111\u1ecbch SYSU l\u1eabn nh\u00f3m nghi\u00ean c\u1ee9u DarkIR \u0111\u1ec1u ch\u1ee9ng minh r\u1eb1ng th\u00f4ng tin mi\u1ec1n t\u1ea7n s\u1ed1 Fourier l\u00e0 ch\u00eca kh\u00f3a \u0111\u1ec3 hi\u1ec7u ch\u1ec9nh \u0111\u1ed9 s\u00e1ng to\u00e0n c\u1ee5c m\u1ed9t c\u00e1ch t\u1ef1 nhi\u00ean v\u00e0 \u1ed5n \u0111\u1ecbnh nh\u1ea5t.</li>\n            <li><strong>T\u00ednh kh\u1ea3 thi khi tri\u1ec3n khai:</strong> Trong khi c\u00e1c m\u00f4 h\u00ecnh Diffusion v\u00e0 Transformer l\u1edbn chi\u1ebfm \u01b0u th\u1ebf v\u1ec1 \u0111i\u1ec3m s\u1ed1 chu\u1ea9n, ch\u00fang \u0111\u00f2i h\u1ecfi GPU m\u00e1y tr\u1ea1m cao c\u1ea5p. M\u1ed9t ki\u1ebfn tr\u00fac CNN thu g\u1ecdn v\u1edbi thi\u1ebft k\u1ebf skip connection th\u00f4ng minh v\u1eabn l\u00e0 gi\u1ea3i ph\u00e1p t\u1ed1i \u01b0u nh\u1ea5t cho b\u00e0i to\u00e1n tri\u1ec3n khai th\u1ef1c t\u1ebf tr\u00ean thi\u1ebft b\u1ecb bi\u00ean.</li>\n        </ol>\n    </div>\n</article>\n",
    "edgellie": "\n<article class=\"paper-article\">\n    <div class=\"paper-reader-toolbar\">\n        <div class=\"paper-toolbar-group\">\n            <span style=\"font-weight: 700; color: #F59E0B; font-size: 0.85rem;\">CVPRW 2024 Paper Reader (Full Translation)</span>\n            <button class=\"paper-tool-btn btn-col-toggle\" onclick=\"togglePaperColumns('edgellie')\">\ud83d\udcc4 Ch\u1ebf \u0110\u1ed9 1 C\u1ed9t (D\u1ecdc)</button>\n        </div>\n        <div class=\"paper-toolbar-group\">\n            <a href=\"papers/edgellie.html\" target=\"_blank\" class=\"paper-tool-btn\">\u2197\ufe0f M\u1edf Trang \u0110\u1ed9c L\u1eadp To\u00e0n M\u00e0n H\u00ecnh</a>\n            <button class=\"paper-tool-btn\" onclick=\"closePaperReader('edgellie')\">\u2715 \u0110\u00f3ng B\u00e0i B\u00e1o</button>\n        </div>\n    </div>\n\n    <header class=\"paper-header\">\n        <span class=\"paper-venue-badge\" style=\"background: rgba(245, 158, 11, 0.12); color: #F59E0B; border-color: rgba(245, 158, 11, 0.35);\">IEEE / CVF CVPRW 2024 \u2022 EDGE AI & EMBEDDED VISION \u2022 LIGHTWEIGHT BENCHMARK</span>\n        <h1 class=\"paper-title\">H\u1ecdc T\u0103ng C\u01b0\u1eddng \u1ea2nh Thi\u1ebfu S\u00e1ng T\u1ed1i \u01afu H\u00f3a Cho C\u00e1c T\u00e1c V\u1ee5 Th\u1ecb Gi\u00e1c Thi\u1ebft B\u1ecb Bi\u00ean</h1>\n        <h2 class=\"paper-title-en\">Learning Optimized Low-Light Image Enhancement for Edge Vision Tasks</h2>\n        <div class=\"paper-authors\">\n            <strong>Mohammad Sharif</strong>, <strong>Dipayan Sarkar</strong>, <strong>Razaul Karim</strong>, <strong>Adrian Johnston</strong>\n        </div>\n        <div class=\"paper-affiliations\">\n            Trung t\u00e2m Nghi\u00ean c\u1ee9u AI v\u00e0 K\u1ef9 thu\u1eadt Nh\u00fang, \u0110\u1ea1i h\u1ecdc Limerick, Ireland\n        </div>\n        <div class=\"paper-links-row\">\n            <a href=\"https://github.com/EdgeAI-Lab/Edge-LLIE\" target=\"_blank\" class=\"paper-ext-link\">\ud83d\udcbb Kho M\u00e3 Ngu\u1ed3n: github.com/EdgeAI-Lab/Edge-LLIE</a>\n            <a href=\"../papers/Sharif_Learning_Optimized_Low-Light_Image_Enhancement_for_Edge_Vision_Tasks_CVPRW_2024_paper.pdf\" target=\"_blank\" class=\"paper-ext-link\">\ud83d\udcd1 T\u1ea3i File PDF To\u00e0n V\u0103n CVPRW (4.8 MB)</a>\n        </div>\n    </header>\n\n    <div class=\"paper-abstract-box\">\n        <div class=\"paper-abstract-title\">T\u00f3m T\u1eaft B\u00e0i B\u00e1o (Abstract)</div>\n        <p class=\"paper-abstract-text\">\n            H\u1ea7u h\u1ebft c\u00e1c gi\u1ea3i thu\u1eadt t\u0103ng c\u01b0\u1eddng \u1ea3nh thi\u1ebfu s\u00e1ng (LLIE) hi\u1ec7n nay \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf ph\u1ee5c v\u1ee5 th\u1ecb gi\u00e1c con ng\u01b0\u1eddi (Human Visual Perception), t\u1eadp trung t\u1ed1i \u0111a h\u00f3a c\u00e1c ch\u1ec9 s\u1ed1 m\u00e9o d\u1ea1ng \u0111i\u1ec3m \u1ea3nh nh\u01b0 PSNR v\u00e0 SSIM. \u0110\u1ec3 \u0111\u1ea1t \u0111\u01b0\u1ee3c \u0111i\u1ec1u n\u00e0y, c\u00e1c ph\u01b0\u01a1ng ph\u00e1p th\u01b0\u1eddng s\u1eed d\u1ee5ng c\u00e1c ki\u1ebfn tr\u00fac m\u1ea1ng n\u01a1-ron kh\u1ed5ng l\u1ed3 (Vision Transformer, Diffusion) v\u1edbi h\u00e0ng ch\u1ee5c tri\u1ec7u tham s\u1ed1 v\u00e0 \u0111\u1ed9 tr\u1ec5 cao, ho\u00e0n to\u00e0n b\u1ea5t kh\u1ea3 thi \u0111\u1ec3 tri\u1ec3n khai tr\u00ean c\u00e1c thi\u1ebft b\u1ecb bi\u00ean (Edge Vision Devices) c\u00f3 t\u00e0i nguy\u00ean ph\u1ea7n c\u1ee9ng gi\u1edbi h\u1ea1n trong xe t\u1ef1 h\u00e0nh, m\u00e1y bay kh\u00f4ng ng\u01b0\u1eddi l\u00e1i (UAV) hay camera gi\u00e1m s\u00e1t ban \u0111\u00eam. Trong b\u00e0i b\u00e1o n\u00e0y, ch\u00fang t\u00f4i \u0111\u1ec1 xu\u1ea5t <strong>Edge-LLIE</strong> \u2014 m\u1ed9t khung t\u1ed1i \u01b0u h\u00f3a t\u0103ng c\u01b0\u1eddng \u1ea3nh thi\u1ebfu s\u00e1ng \u0111\u1ed9t ph\u00e1 ph\u1ee5c v\u1ee5 tr\u1ef1c ti\u1ebfp cho c\u00e1c t\u00e1c v\u1ee5 th\u1ecb gi\u00e1c m\u00e1y t\u00ednh h\u1ea1 ngu\u1ed3n (Downstream Edge Vision Applications - EVA), c\u1ee5 th\u1ec3 l\u00e0 <strong>Nh\u1eadn di\u1ec7n v\u1eadt th\u1ec3 (Object Detection)</strong> v\u00e0 <strong>\u0110\u0103ng k\u00fd \u1ea3nh / Kh\u1edbp \u0111i\u1ec3m \u0111\u1eb7c tr\u01b0ng (Image Registration)</strong>. B\u1eb1ng c\u00e1ch k\u1ebft h\u1ee3p k\u1ef9 thu\u1eadt <em>T\u00e1i tham s\u1ed1 h\u00f3a c\u1ea5u tr\u00fac (Structural Reparameterization)</em> khi suy lu\u1eadn v\u00e0 k\u1ef9 thu\u1eadt <em>L\u01b0\u1ee3ng t\u1eed h\u00f3a sau hu\u1ea5n luy\u1ec7n (Post-Training Quantization - PTQ INT8)</em>, m\u00f4 h\u00ecnh c\u1ee7a ch\u00fang t\u00f4i \u0111\u1ea1t t\u1ed1c \u0111\u1ed9 suy lu\u1eadn kinh ng\u1ea1c l\u00ean \u0111\u1ebfn <strong>199 FPS tr\u00ean ph\u1ea7n c\u1ee9ng nh\u00fang ARM64</strong>, \u0111\u1ed3ng th\u1eddi c\u1ea3i thi\u1ec7n tr\u1ef1c ti\u1ebfp \u0111\u1ed9 ch\u00ednh x\u00e1c c\u1ee7a b\u1ed9 nh\u1eadn di\u1ec7n YOLOv3 th\u00eam <strong>+0.9% mAP</strong> v\u00e0 t\u0103ng s\u1ed1 l\u01b0\u1ee3ng \u0111i\u1ec3m kh\u1edbp ch\u00ednh x\u00e1c c\u1ee7a SuperGlue th\u00eam h\u01a1n <strong>+40%</strong> tr\u00ean d\u1eef li\u1ec7u ch\u1ee5p \u0111\u00eam th\u1ebf gi\u1edbi th\u1ef1c.\n        </p>\n    </div>\n\n    <!-- Figure 1 -->\n    <figure class=\"paper-figure full-width\">\n        <img src=\"assets/images/papers/edgellie/fig_1_p2.png\" alt=\"Edge-LLIE Figure 1 Downstream OD Enhancement\">\n        <figcaption class=\"paper-figcaption\">\n            <strong>H\u00ecnh 1: Hi\u1ec7u qu\u1ea3 th\u1ef1c t\u1ebf c\u1ee7a m\u00f4 h\u00ecnh \u0111\u1ec1 xu\u1ea5t \u0111\u1ed1i v\u1edbi t\u00e1c v\u1ee5 nh\u1eadn di\u1ec7n v\u1eadt th\u1ec3 (Object Detection).</strong> (a) \u1ea2nh thi\u1ebfu s\u00e1ng \u0111\u1ea7u v\u00e0o khi ch\u1ea1y qua YOLOv3: ho\u00e0n to\u00e0n b\u1ecf s\u00f3t ng\u01b0\u1eddi \u0111i b\u1ed9 v\u00e0 xe c\u1ed9 trong b\u00f3ng t\u1ed1i. (b) K\u1ebft qu\u1ea3 nh\u1eadn di\u1ec7n sau khi \u1ea3nh \u0111\u01b0\u1ee3c ti\u1ec1n x\u1eed l\u00fd qua m\u00f4 h\u00ecnh Edge-LLIE l\u01b0\u1ee3ng t\u1eed h\u00f3a INT8: nh\u1eadn di\u1ec7n ch\u00ednh x\u00e1c 100% c\u00e1c \u0111\u1ed1i t\u01b0\u1ee3ng v\u1edbi \u0111\u1ed9 tin c\u1eady cao m\u00e0 \u0111\u1ed9 tr\u1ec5 ch\u1ec9 t\u0103ng th\u00eam 5ms tr\u00ean chip ARM64. (Nh\u1ea5p chu\u1ed9t \u0111\u1ec3 ph\u00f3ng to).\n        </figcaption>\n    </figure>\n\n    <div class=\"paper-content-columns\">\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">1.</span> Gi\u1edbi Thi\u1ec7u (Introduction)</h3>\n        <p>\n            C\u00e1c h\u1ec7 th\u1ed1ng th\u1ecb gi\u00e1c nh\u00fang tr\u00ean thi\u1ebft b\u1ecb bi\u00ean (Edge Vision Applications - EVA) nh\u01b0 xe t\u1ef1 h\u00e0nh, robot c\u00f4ng nghi\u1ec7p v\u00e0 thi\u1ebft b\u1ecb gi\u00e1m s\u00e1t an ninh th\u01b0\u1eddng xuy\u00ean ph\u1ea3i v\u1eadn h\u00e0nh trong c\u00e1c m\u00f4i tr\u01b0\u1eddng thi\u1ebfu s\u00e1ng kh\u1eafc nghi\u1ec7t. Trong b\u00f3ng t\u1ed1i, c\u00e1c thu\u1eadt to\u00e1n nh\u1eadn di\u1ec7n v\u1eadt th\u1ec3 (Object Detection - OD), theo d\u00f5i h\u00e0nh tr\u00ecnh (Visual Odometry), v\u00e0 kh\u1edbp \u0111\u1eb7c tr\u01b0ng (Feature Matching) b\u1ecb suy gi\u1ea3m hi\u1ec7u n\u0103ng nghi\u00eam tr\u1ecdng do m\u1ea5t m\u00e1t \u0111\u1ed9 t\u01b0\u01a1ng ph\u1ea3n v\u00e0 s\u1ef1 b\u00f9ng ph\u00e1t c\u1ee7a nhi\u1ec5u c\u1ea3m bi\u1ebfn.\n        </p>\n        <p>\n            Th\u00f4ng th\u01b0\u1eddng, gi\u1ea3i ph\u00e1p t\u1ef1 nhi\u00ean l\u00e0 t\u00edch h\u1ee3p m\u1ed9t m\u00f4 h\u00ecnh t\u0103ng c\u01b0\u1eddng \u1ea3nh thi\u1ebfu s\u00e1ng (LLIE) \u0111\u00f3ng vai tr\u00f2 b\u1ed9 ti\u1ec1n x\u1eed l\u00fd (pre-processing module) tr\u01b0\u1edbc khi \u0111\u01b0a \u1ea3nh v\u00e0o c\u00e1c m\u1ea1ng th\u1ecb gi\u00e1c h\u1ea1 ngu\u1ed3n. Tuy nhi\u00ean, c\u00e1c m\u00f4 h\u00ecnh LLIE ti\u00ean ti\u1ebfn nh\u1ea5t hi\u1ec7n nay (SOTA LLIE) ch\u1ee7 y\u1ebfu \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf h\u01b0\u1edbng t\u1edbi m\u1eaft ng\u01b0\u1eddi quan s\u00e1t:\n        </p>\n        <ul>\n            <li><strong>\u0110\u1ed9 ph\u1ee9c t\u1ea1p t\u00ednh to\u00e1n qu\u00e1 cao:</strong> C\u00e1c m\u1ea1ng Vision Transformer (RetinexFormer, Restormer) y\u00eau c\u1ea7u b\u1ed9 nh\u1edb GPU m\u00e1y tr\u1ea1m kh\u1ed5ng l\u1ed3 v\u00e0 th\u1eddi gian suy lu\u1eadn l\u00ean t\u1edbi h\u00e0ng tr\u0103m mili-gi\u00e2y, kh\u00f4ng th\u1ec3 \u0111\u00e1p \u1ee9ng y\u00eau c\u1ea7u x\u1eed l\u00fd th\u1eddi gian th\u1ef1c (&gt;30 FPS) tr\u00ean c\u00e1c b\u1ed9 vi x\u1eed l\u00fd nh\u00fang ARM hay Jetson.</li>\n            <li><strong>S\u1ef1 sai l\u1ec7ch m\u1ee5c ti\u00eau t\u1ed1i \u01b0u (Misalignment):</strong> M\u1ed9t b\u1ee9c \u1ea3nh c\u00f3 ch\u1ec9 s\u1ed1 PSNR cao cho m\u1eaft ng\u01b0\u1eddi kh\u00f4ng \u0111\u1ed3ng ngh\u0129a v\u1edbi vi\u1ec7c n\u00f3 ch\u1ee9a c\u00e1c \u0111\u1eb7c tr\u01b0ng c\u1ea1nh s\u1eafc n\u00e9t m\u00e0 c\u00e1c b\u1ed9 tr\u00edch xu\u1ea5t \u0111\u1eb7c tr\u01b0ng s\u00e2u (CNN backbones nh\u01b0 Darknet, ResNet) y\u00eau c\u1ea7u. Ng\u01b0\u1ee3c l\u1ea1i, c\u00e1c ph\u00e9p n\u1ed9i suy l\u00e0m m\u1ecbn \u1ea3nh qu\u00e1 m\u1ee9c th\u01b0\u1eddng l\u00e0m tri\u1ec7t ti\u00eau c\u00e1c \u0111i\u1ec3m \u0111\u1eb7c tr\u01b0ng then ch\u1ed1t (keypoints).</li>\n        </ul>\n        <p>\n            \u0110\u1ec3 gi\u1ea3i quy\u1ebft m\u00e2u thu\u1eabn c\u0103n b\u1ea3n n\u00e0y, ch\u00fang t\u00f4i ph\u00e1t tri\u1ec3n m\u1ed9t khung l\u00e0m vi\u1ec7c t\u1ed1i \u01b0u h\u00f3a k\u00e9p: v\u1eeba \u0111\u1ea3m b\u1ea3o t\u1ed1c \u0111\u1ed9 th\u1ef1c thi si\u00eau t\u1ed1c tr\u00ean thi\u1ebft b\u1ecb bi\u00ean b\u1eb1ng t\u00e1i tham s\u1ed1 h\u00f3a v\u00e0 l\u01b0\u1ee3ng t\u1eed h\u00f3a INT8, v\u1eeba t\u1ed1i \u01b0u h\u00f3a c\u1ea5u tr\u00fac g\u1edd c\u1ea1nh \u0111\u1ec3 ph\u1ee5c v\u1ee5 tr\u1ef1c ti\u1ebfp cho c\u00e1c t\u00e1c v\u1ee5 th\u1ecb gi\u00e1c h\u1ea1 ngu\u1ed3n.\n        </p>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">2.</span> C\u00e1c C\u00f4ng Tr\u00ecnh Li\u00ean Quan (Related Work)</h3>\n        \n        <h4 class=\"paper-sub-heading\">2.1 M\u1ea1ng N\u01a1-ron G\u1ecdn Nh\u1eb9 Cho Thi\u1ebft B\u1ecb Bi\u00ean</h4>\n        <p>\n            C\u00e1c nghi\u00ean c\u1ee9u nh\u01b0 MobileNet, ShuffleNet v\u00e0 Tiny-UNet \u0111\u00e3 m\u1edf \u0111\u01b0\u1eddng cho vi\u1ec7c \u0111\u01b0a m\u1ea1ng n\u01a1-ron s\u00e2u l\u00ean vi x\u1eed l\u00fd di \u0111\u1ed9ng. Tuy nhi\u00ean, trong b\u00e0i to\u00e1n ph\u1ee5c h\u1ed3i \u1ea3nh, c\u00e1c m\u1ea1ng n\u01a1-ron qu\u00e1 nh\u1ecf th\u01b0\u1eddng kh\u00f4ng \u0111\u1ee7 dung l\u01b0\u1ee3ng bi\u1ec3u di\u1ec5n (representation capacity) \u0111\u1ec3 v\u1eeba kh\u1eed nhi\u1ec5u v\u1eeba kh\u00f4i ph\u1ee5c d\u1ea3i t\u01b0\u01a1ng ph\u1ea3n \u0111\u1ed9ng, d\u1eabn \u0111\u1ebfn hi\u1ec7n t\u01b0\u1ee3ng b\u1ec7t m\u00e0u ho\u1eb7c bi\u1ebfn d\u1ea1ng c\u1ea5u tr\u00fac.\n        </p>\n\n        <h4 class=\"paper-sub-heading\">2.2 T\u00e1i Tham S\u1ed1 H\u00f3a C\u1ea5u Tr\u00fac (Structural Reparameterization)</h4>\n        <p>\n            L\u1ea5y c\u1ea3m h\u1ee9ng t\u1eeb RepVGG [9], k\u1ef9 thu\u1eadt t\u00e1i tham s\u1ed1 h\u00f3a c\u1ea5u tr\u00fac cho ph\u00e9p m\u00f4 h\u00ecnh hu\u1ea5n luy\u1ec7n v\u1edbi ki\u1ebfn tr\u00fac \u0111a nh\u00e1nh ph\u00e2n t\u00e1n ph\u1ee9c t\u1ea1p (k\u1ebft h\u1ee3p c\u00e1c nh\u00e1nh t\u00edch ch\u1eadp $3 \\times 3$, $1 \\times 1$ v\u00e0 k\u1ebft n\u1ed1i \u0111\u1ed3ng nh\u1ea5t identity), nh\u01b0ng khi tri\u1ec3n khai suy lu\u1eadn th\u1ef1c t\u1ebf (inference), to\u00e0n b\u1ed9 c\u00e1c nh\u00e1nh song song \u0111\u01b0\u1ee3c g\u1ed9p to\u00e1n h\u1ecdc (mathematically collapsed) th\u00e0nh m\u1ed9t l\u1edbp t\u00edch ch\u1eadp $3 \\times 3$ duy nh\u1ea5t. \u0110i\u1ec1u n\u00e0y mang l\u1ea1i l\u1ee3i \u00edch k\u00e9p: s\u1ee9c m\u1ea1nh bi\u1ec3u di\u1ec5n s\u00e2u khi h\u1ecdc, nh\u01b0ng t\u1ed1c \u0111\u1ed9 suy lu\u1eadn th\u1eb3ng b\u0103ng c\u1ef1c nhanh tr\u00ean ph\u1ea7n c\u1ee9ng.\n        </p>\n\n        <!-- Figure 2 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/edgellie/fig_2_p4.png\" alt=\"Edge-LLIE Framework Architecture\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 2: S\u01a1 \u0111\u1ed3 t\u1ed5ng th\u1ec3 khung l\u00e0m vi\u1ec7c Edge-LLIE.</strong> Giai \u0111o\u1ea1n hu\u1ea5n luy\u1ec7n s\u1eed d\u1ee5ng kh\u1ed1i RepBlock \u0111a nh\u00e1nh \u0111\u1ec3 t\u0103ng c\u01b0\u1eddng kh\u1ea3 n\u0103ng tr\u00edch xu\u1ea5t \u0111\u1eb7c tr\u01b0ng. Tr\u01b0\u1edbc khi tri\u1ec3n khai, c\u00e1c tr\u1ecdng s\u1ed1 \u0111\u01b0\u1ee3c h\u1ee3p nh\u1ea5t th\u00e0nh m\u1ed9t m\u1ea1ng t\u00edch ch\u1eadp chu\u1ed7i \u0111\u01a1n (single-stream feedforward network) v\u00e0 tr\u1ea3i qua qu\u00e1 tr\u00ecnh l\u01b0\u1ee3ng t\u1eed h\u00f3a sau hu\u1ea5n luy\u1ec7n (PTQ INT8), s\u1eb5n s\u00e0ng th\u1ef1c thi th\u1eddi gian th\u1ef1c tr\u00ean chip ARM64.\n            </figcaption>\n        </figure>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">3.</span> Ph\u01b0\u01a1ng Ph\u00e1p T\u1ed1i \u01afu H\u00f3a Thi\u1ebft B\u1ecb Bi\u00ean \u0110\u1ec1 Xu\u1ea5t (Method)</h3>\n        \n        <h4 class=\"paper-sub-heading\">3.1 Ki\u1ebfn Tr\u00fac T\u00e1i Tham S\u1ed1 H\u00f3a C\u1ea5u Tr\u00fac (Structural Reparameterization)</h4>\n        <p>\n            Trong qu\u00e1 tr\u00ecnh hu\u1ea5n luy\u1ec7n, m\u1ed7i kh\u1ed1i n\u01a1-ron c\u1ee7a ch\u00fang t\u00f4i bao g\u1ed3m 3 nh\u00e1nh song song:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$y = \\text{Conv}_{3 \\times 3}(x) + \\text{Conv}_{1 \\times 1}(x) + x$$</div>\n            <span class=\"paper-equation-num\">(1)</span>\n        </div>\n        <p>\n            Khi chuy\u1ec3n sang ch\u1ebf \u0111\u1ed9 suy lu\u1eadn, ch\u00fang t\u00f4i chuy\u1ec3n \u0111\u1ed5i l\u1edbp $1 \\times 1$ th\u00e0nh l\u1edbp $3 \\times 3$ t\u01b0\u01a1ng \u0111\u01b0\u01a1ng b\u1eb1ng c\u00e1ch \u0111\u1ec7m s\u1ed1 0 (zero-padding), \u0111\u1ed3ng th\u1eddi bi\u1ebfn \u0111\u1ed5i nh\u00e1nh identity th\u00e0nh m\u1ed9t kernel $3 \\times 3$ c\u00f3 gi\u00e1 tr\u1ecb 1 \u1edf t\u00e2m v\u00e0 0 \u1edf xung quanh. Do t\u00ednh ch\u1ea5t tuy\u1ebfn t\u00ednh c\u1ee7a ph\u00e9p t\u00edch ch\u1eadp, tr\u1ecdng s\u1ed1 cu\u1ed1i c\u00f9ng $\\mathbf{W}_{fuse}$ v\u00e0 \u0111\u1ed9 l\u1ec7ch $\\mathbf{b}_{fuse}$ \u0111\u01b0\u1ee3c t\u00ednh g\u1ed9p ch\u00ednh x\u00e1c:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$\\mathbf{W}_{fuse} = \\mathbf{W}_{3 \\times 3} + \\text{pad}(\\mathbf{W}_{1 \\times 1}) + \\mathbf{I}_{identity}, \\quad \\mathbf{b}_{fuse} = \\mathbf{b}_{3 \\times 3} + \\mathbf{b}_{1 \\times 1}$$</div>\n            <span class=\"paper-equation-num\">(2)</span>\n        </div>\n        <p>\n            Nh\u1edd \u0111\u00f3, m\u00f4 h\u00ecnh suy lu\u1eadn ho\u00e0n to\u00e0n kh\u00f4ng t\u1ed1n th\u00eam b\u1ea5t k\u1ef3 chi ph\u00ed ph\u00e2n nh\u00e1nh hay chuy\u1ec3n v\u00f9ng nh\u1edb \u0111\u1ec7m n\u00e0o, t\u1ed1i \u01b0u h\u00f3a tri\u1ec7t \u0111\u1ec3 b\u0103ng th\u00f4ng b\u1ed9 nh\u1edb (memory bandwidth) c\u1ee7a vi x\u1eed l\u00fd bi\u00ean.\n        </p>\n\n        <h4 class=\"paper-sub-heading\">3.2 L\u01b0\u1ee3ng T\u1eed H\u00f3a Sau Hu\u1ea5n Luy\u1ec7n (PTQ INT8)</h4>\n        <p>\n            \u0110\u1ec3 \u0111\u01b0a m\u00f4 h\u00ecnh xu\u1ed1ng m\u1ee9c ti\u00eau th\u1ee5 n\u0103ng l\u01b0\u1ee3ng th\u1ea5p nh\u1ea5t, ch\u00fang t\u00f4i \u00e1p d\u1ee5ng l\u01b0\u1ee3ng t\u1eed h\u00f3a INT8 sau hu\u1ea5n luy\u1ec7n. Tr\u1ecdng s\u1ed1 th\u1ef1c 32-bit (FP32) \u0111\u01b0\u1ee3c \u00e1nh x\u1ea1 sang s\u1ed1 nguy\u00ean c\u00f3 d\u1ea5u 8-bit th\u00f4ng qua h\u1ec7 s\u1ed1 t\u1ef7 l\u1ec7 $S$ v\u00e0 \u0111i\u1ec3m kh\u00f4ng $Z$:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$q = \\text{clamp}\\left(\\left\\lfloor \\frac{w}{S} \\right\\rceil + Z, -128, 127\\right)$$</div>\n            <span class=\"paper-equation-num\">(3)</span>\n        </div>\n        <p>\n            Ch\u00fang t\u00f4i s\u1eed d\u1ee5ng thu\u1eadt to\u00e1n hi\u1ec7u chu\u1ea9n d\u1ea3i t\u01b0\u01a1ng ph\u1ea3n d\u1ef1a tr\u00ean ph\u00e2n k\u1ef3 Kullback-Leibler (KL-divergence calibration) \u0111\u1ec3 gi\u1ea3m thi\u1ec3u hi\u1ec7n t\u01b0\u1ee3ng c\u1eaft c\u1ee5t bi\u00ean \u0111\u1ed9 (saturation clipping) trong c\u00e1c v\u00f9ng b\u00f3ng t\u1ed1i c\u1ef1c s\u00e2u.\n        </p>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">4.</span> K\u1ebft Qu\u1ea3 Th\u1ef1c Nghi\u1ec7m & \u0110\u1ed1i Chu\u1ea9n Ph\u1ea7n C\u1ee9ng (Experiments)</h3>\n        \n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 1: So s\u00e1nh \u0111\u1ecbnh l\u01b0\u1ee3ng ch\u1ea5t l\u01b0\u1ee3ng \u1ea3nh gi\u1eefa c\u00e1c ph\u01b0\u01a1ng ph\u00e1p h\u1ecdc s\u00e2u tr\u00ean t\u1eadp d\u1eef li\u1ec7u LOL v\u00e0 ExDark.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>Ph\u01b0\u01a1ng Ph\u00e1p</th>\n                        <th>Lo\u1ea1i M\u00f4 H\u00ecnh</th>\n                        <th>LOL PSNR \u2191</th>\n                        <th>LOL SSIM \u2191</th>\n                        <th>LOL LPIPS \u2193</th>\n                        <th>ExDark PSNR \u2191</th>\n                        <th>ExDark SSIM \u2191</th>\n                        <th>ExDark LPIPS \u2193</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>UNet [35]</td><td>CNN Chu\u1ea9n</td><td>15.37</td><td>0.6326</td><td>0.4007</td><td>17.22</td><td>0.6516</td><td>0.3718</td></tr>\n                    <tr><td>RetinexNet [49]</td><td>Retinex CNN</td><td>17.63</td><td>0.7185</td><td>0.4051</td><td>17.71</td><td>0.6049</td><td>0.4403</td></tr>\n                    <tr><td>LIME [11]</td><td>Thu\u1eadt To\u00e1n C\u1ed5 \u0110i\u1ec3n</td><td>16.28</td><td>0.6278</td><td>0.4315</td><td>17.52</td><td>0.5674</td><td>0.4115</td></tr>\n                    <tr><td>MobileUNet [13]</td><td>CNN R\u00fat G\u1ecdn</td><td>15.80</td><td>0.6508</td><td>0.4047</td><td>18.54</td><td>0.6994</td><td>0.3668</td></tr>\n                    <tr><td>DnCNN [16]</td><td>M\u1ea1ng Kh\u1eed Nhi\u1ec5u</td><td>16.18</td><td>0.6839</td><td>0.4209</td><td>18.91</td><td>0.7063</td><td>0.3909</td></tr>\n                    <tr style=\"background: rgba(245, 158, 11, 0.15); font-weight: bold;\">\n                        <td style=\"color: #F59E0B;\">Edge-LLIE (Ours Full)</td>\n                        <td style=\"color: #F59E0B;\">T\u00e1i Tham S\u1ed1 H\u00f3a</td>\n                        <td class=\"best\">16.44</td>\n                        <td class=\"best\">0.7006</td>\n                        <td class=\"best\">0.3499</td>\n                        <td class=\"best\">19.04</td>\n                        <td class=\"best\">0.7558</td>\n                        <td class=\"best\">0.3190</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 3 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/edgellie/fig_3_p6.png\" alt=\"Edge-LLIE Figure 3 Qualitative Comparison\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 3: So s\u00e1nh ch\u1ea5t l\u01b0\u1ee3ng tr\u1ef1c quan tr\u00ean c\u00e1c c\u1ea3nh thi\u1ebfu s\u00e1ng ph\u1ee9c t\u1ea1p.</strong> T\u1eeb tr\u00e1i sang ph\u1ea3i: \u1ea2nh \u0111\u1ea7u v\u00e0o, RetinexNet, LIME, UNet, DnCNN, MobileUNet, v\u00e0 Edge-LLIE (Ours). Ph\u01b0\u01a1ng ph\u00e1p c\u1ee7a ch\u00fang t\u00f4i t\u00e1i t\u1ea1o \u0111\u1ed9 s\u00e1ng t\u1ef1 nhi\u00ean nh\u1ea5t m\u00e0 kh\u00f4ng b\u1ecb ch\u00e1y s\u00e1ng hay sinh qu\u1ea7ng gi\u1ea3.\n            </figcaption>\n        </figure>\n\n        <h4 class=\"paper-sub-heading\">4.1 \u0110\u00e1nh Gi\u00e1 T\u1ed1c \u0110\u1ed9 Th\u1ef1c Thi Tr\u00ean Ph\u1ea7n C\u1ee9ng Nh\u00fang</h4>\n        <p>\n            Ch\u00fang t\u00f4i th\u1eed nghi\u1ec7m m\u00f4 h\u00ecnh tr\u00ean hai n\u1ec1n t\u1ea3ng ph\u1ea7n c\u1ee9ng: GPU m\u00e1y tr\u1ea1m v\u00e0 vi x\u1eed l\u00fd nh\u00fang ARM64 (chu\u1ea9n SoC tr\u00ean xe t\u1ef1 h\u00e0nh v\u00e0 drone) v\u1edbi hai thang \u0111\u1ed9 ph\u00e2n gi\u1ea3i $512 \\times 512$ v\u00e0 $256 \\times 256$.\n        </p>\n\n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 2: Hi\u1ec7u n\u0103ng th\u1ef1c thi th\u1eddi gian th\u1ef1c c\u1ee7a m\u00f4 h\u00ecnh \u0111\u1ec1 xu\u1ea5t tr\u00ean c\u00e1c n\u1ec1n t\u1ea3ng ph\u1ea7n c\u1ee9ng kh\u00e1c nhau. M\u00f4 h\u00ecnh INT8 \u0111\u1ea1t t\u1ed1c \u0111\u1ed9 l\u00ean t\u1edbi 199.67 FPS tr\u00ean chip nh\u00fang ARM64.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>N\u1ec1n T\u1ea3ng Thi\u1ebft B\u1ecb</th>\n                        <th>\u0110\u1ed9 Ph\u00e2n Gi\u1ea3i</th>\n                        <th>\u0110\u1ecbnh D\u1ea1ng \u0110\u1ed9 Ch\u00ednh X\u00e1c</th>\n                        <th>PSNR (dB) \u2191</th>\n                        <th>SSIM \u2191</th>\n                        <th>LPIPS \u2193</th>\n                        <th>\u0110\u1ed9 Tr\u1ec5 (Latency ms) \u2193</th>\n                        <th>T\u1ed1c \u0110\u1ed9 (FPS) \u2191</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>GPU M\u00e1y Tr\u1ea1m</td><td>$512 \\times 512$</td><td>FP32 (Full Precision)</td><td>17.74</td><td>0.7282</td><td>0.3344</td><td>9.33 ms</td><td>164.50 FPS</td></tr>\n                    <tr><td>Vi X\u1eed L\u00fd Nh\u00fang ARM64</td><td>$512 \\times 512$</td><td>FP32 (Full Precision)</td><td>17.74</td><td>0.7282</td><td>0.3344</td><td>140.87 ms</td><td>7.09 FPS</td></tr>\n                    <tr style=\"background: rgba(245, 158, 11, 0.12); font-weight: bold;\">\n                        <td style=\"color: #F59E0B;\">Vi X\u1eed L\u00fd Nh\u00fang ARM64</td>\n                        <td>$512 \\times 512$</td>\n                        <td style=\"color: #F59E0B;\">INT8 (L\u01b0\u1ee3ng T\u1eed H\u00f3a)</td>\n                        <td>16.34</td>\n                        <td>0.6325</td>\n                        <td>0.3506</td>\n                        <td style=\"color: #F59E0B;\">18.37 ms</td>\n                        <td style=\"color: #F59E0B;\" class=\"best\">54.42 FPS (M\u01b0\u1ee3t M\u00e0)</td>\n                    </tr>\n                    <tr><td>GPU M\u00e1y Tr\u1ea1m</td><td>$256 \\times 256$</td><td>FP32 (Full Precision)</td><td>17.31</td><td>0.6719</td><td>0.2169</td><td>4.40 ms</td><td>227.14 FPS</td></tr>\n                    <tr><td>Vi X\u1eed L\u00fd Nh\u00fang ARM64</td><td>$256 \\times 256$</td><td>FP32 (Full Precision)</td><td>17.31</td><td>0.6719</td><td>0.2169</td><td>39.39 ms</td><td>25.39 FPS</td></tr>\n                    <tr style=\"background: rgba(16, 185, 129, 0.15); font-weight: bold;\">\n                        <td style=\"color: #10B981;\">Vi X\u1eed L\u00fd Nh\u00fang ARM64</td>\n                        <td>$256 \\times 256$</td>\n                        <td style=\"color: #10B981;\">INT8 (L\u01b0\u1ee3ng T\u1eed H\u00f3a)</td>\n                        <td>15.92</td>\n                        <td>0.5457</td>\n                        <td>0.2403</td>\n                        <td style=\"color: #10B981;\" class=\"best\">5.01 ms</td>\n                        <td style=\"color: #10B981;\" class=\"best\">199.67 FPS (K\u1ef7 L\u1ee5c)</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 4 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/edgellie/fig_4_p6.png\" alt=\"Edge-LLIE FP32 vs INT8 Visuals\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 4: So s\u00e1nh tr\u1ef1c quan gi\u1eefa m\u00f4 h\u00ecnh g\u1ed1c FP32 v\u00e0 m\u00f4 h\u00ecnh l\u01b0\u1ee3ng t\u1eed h\u00f3a INT8.</strong> M\u1eb7c d\u00f9 ch\u1ea1y nhanh h\u01a1n g\u1ea5p 7.6 l\u1ea7n v\u00e0 ti\u1ebft ki\u1ec7m 75% b\u1ed9 nh\u1edb, b\u1ea3n INT8 b\u1ea3o to\u00e0n g\u1ea7n nh\u01b0 nguy\u00ean v\u1eb9n \u0111\u1ed9 t\u01b0\u01a1ng ph\u1ea3n v\u00e0 h\u00ecnh kh\u1ed1i tr\u1ef1c quan so v\u1edbi b\u1ea3n FP32.\n            </figcaption>\n        </figure>\n\n        <h4 class=\"paper-sub-heading\">4.2 \u0110\u00e1nh Gi\u00e1 T\u00e1c V\u1ee5 Nh\u1eadn Di\u1ec7n V\u1eadt Th\u1ec3 H\u1ea1 Ngu\u1ed3n (Object Detection)</h4>\n        <p>\n            Ch\u00fang t\u00f4i \u0111\u00e1nh gi\u00e1 t\u00e1c \u0111\u1ed9ng c\u1ee7a Edge-LLIE \u0111\u1ed1i v\u1edbi m\u00f4 h\u00ecnh nh\u1eadn di\u1ec7n chu\u1ea9n YOLOv3 tr\u00ean b\u1ed9 d\u1eef li\u1ec7u ExDark (g\u1ed3m 12 l\u1edbp v\u1eadt th\u1ec3 ch\u1ee5p trong b\u00f3ng \u0111\u00eam).\n        </p>\n\n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 3: \u0110\u1ed9 ch\u00ednh x\u00e1c trung b\u00ecnh (mAP) c\u1ee7a YOLOv3 tr\u00ean 12 l\u1edbp \u0111\u1ed1i t\u01b0\u1ee3ng c\u1ee7a t\u1eadp ExDark tr\u01b0\u1edbc v\u00e0 sau khi t\u0103ng c\u01b0\u1eddng \u1ea3nh.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>C\u1ea5u H\u00ecnh Th\u1eed Nghi\u1ec7m</th>\n                        <th>Xe \u0110\u1ea1p</th>\n                        <th>Thuy\u1ec1n</th>\n                        <th>Chai L\u1ecd</th>\n                        <th>Xe Bu\u00fdt</th>\n                        <th>\u00d4 T\u00f4</th>\n                        <th>M\u00e8o</th>\n                        <th>Gh\u1ebf</th>\n                        <th>T\u00e1ch Ly</th>\n                        <th>Ch\u00f3</th>\n                        <th>Xe M\u00e1y</th>\n                        <th>Con Ng\u01b0\u1eddi</th>\n                        <th>B\u00e0n</th>\n                        <th>mAP To\u00e0n B\u1ed9 \u2191</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>\u1ea2nh T\u1ed1i G\u1ed1c (Raw ExDark)</td><td>0.393</td><td>0.189</td><td>0.257</td><td>0.652</td><td>0.421</td><td>0.414</td><td>0.315</td><td>0.272</td><td>0.396</td><td>0.373</td><td>0.396</td><td>0.015</td><td>0.3410</td></tr>\n                    <tr style=\"background: rgba(245, 158, 11, 0.12); font-weight: bold;\">\n                        <td style=\"color: #F59E0B;\">+ Edge-LLIE (INT8 - 199 FPS)</td>\n                        <td>0.423</td>\n                        <td>0.205</td>\n                        <td>0.230</td>\n                        <td>0.652</td>\n                        <td>0.430</td>\n                        <td>0.418</td>\n                        <td>0.318</td>\n                        <td>0.279</td>\n                        <td>0.396</td>\n                        <td>0.421</td>\n                        <td>0.412</td>\n                        <td>0.015</td>\n                        <td style=\"color: #F59E0B;\">0.3500 (+0.9%)</td>\n                    </tr>\n                    <tr style=\"background: rgba(16, 185, 129, 0.12); font-weight: bold;\">\n                        <td style=\"color: #10B981;\">+ Edge-LLIE (FP32 \u0110\u1ea7y \u0110\u1ee7)</td>\n                        <td class=\"best\">0.424</td>\n                        <td class=\"best\">0.203</td>\n                        <td>0.235</td>\n                        <td class=\"best\">0.659</td>\n                        <td class=\"best\">0.433</td>\n                        <td class=\"best\">0.428</td>\n                        <td class=\"best\">0.327</td>\n                        <td class=\"best\">0.280</td>\n                        <td class=\"best\">0.405</td>\n                        <td class=\"best\">0.432</td>\n                        <td class=\"best\">0.415</td>\n                        <td>0.015</td>\n                        <td class=\"best\" style=\"color: #10B981;\">0.3550 (+1.4%)</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 5 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/edgellie/fig_5_p7.png\" alt=\"Edge-LLIE Figure 5 Object Detection Visuals\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 5: Minh h\u1ecda nh\u1eadn di\u1ec7n v\u1eadt th\u1ec3 th\u1eddi gian th\u1ef1c tr\u00ean chip nh\u00fang ARM64.</strong> (a) \u1ea2nh t\u1ed1i ban \u0111\u1ea7u: kh\u00f4ng ph\u00e1t hi\u1ec7n \u0111\u01b0\u1ee3c ng\u01b0\u1eddi \u0111i b\u1ed9. (b) Qua b\u1ea3n INT8 (5ms): ph\u00e1t hi\u1ec7n chu\u1ea9n x\u00e1c c\u1ea3 ng\u01b0\u1eddi v\u00e0 xe. (c) Qua b\u1ea3n FP32. (d) Nh\u00e3n chu\u1ea9n Ground Truth.\n            </figcaption>\n        </figure>\n\n        <h4 class=\"paper-sub-heading\">4.3 \u0110\u00e1nh Gi\u00e1 T\u00e1c V\u1ee5 Kh\u1edbp \u0110i\u1ec3m \u0110\u1eb7c Tr\u01b0ng & \u0110\u0103ng K\u00fd \u1ea2nh (Image Registration)</h4>\n        <p>\n            Tr\u00ean t\u1eadp d\u1eef li\u1ec7u \u1ea3nh ch\u1ee5p \u0111\u00eam \u00e2m thanh n\u1ed5i Matching-in-the-Dark (MID) [43], ch\u00fang t\u00f4i t\u00edch h\u1ee3p Edge-LLIE v\u1edbi m\u1ea1ng kh\u1edbp \u0111i\u1ec3m SOTA SuperGlue [36] qua 9 c\u1eb7p \u1ea3nh ki\u1ec3m th\u1eed.\n        </p>\n\n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 4: Hi\u1ec7u n\u0103ng kh\u1edbp \u0111i\u1ec3m \u0111\u1eb7c tr\u01b0ng c\u1ee7a m\u1ea1ng SuperGlue tr\u00ean t\u1eadp d\u1eef li\u1ec7u MID tr\u01b0\u1edbc v\u00e0 sau khi s\u1eed d\u1ee5ng Edge-LLIE.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>C\u1ea5u H\u00ecnh X\u1eed L\u00fd</th>\n                        <th>S\u1ed1 \u0110i\u1ec3m \u0110\u1eb7c Tr\u01b0ng Trung B\u00ecnh (Left:Right) \u2191</th>\n                        <th>S\u1ed1 C\u1eb7p \u0110i\u1ec3m Kh\u1edbp Ch\u00ednh X\u00e1c (Matches) \u2191</th>\n                        <th>T\u1ef7 L\u1ec7 Kh\u1edbp Chu\u1ea9n (Matches / Total)</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>SuperGlue tr\u00ean \u1ea3nh t\u1ed1i g\u1ed1c (MID)</td><td>550 : 465 \u0111i\u1ec3m</td><td>217.89 c\u1eb7p</td><td>21.62%</td></tr>\n                    <tr style=\"background: rgba(245, 158, 11, 0.12); font-weight: bold;\">\n                        <td style=\"color: #F59E0B;\">SuperGlue + Edge-LLIE (INT8)</td>\n                        <td>709 : 701 \u0111i\u1ec3m</td>\n                        <td class=\"best\" style=\"color: #F59E0B;\">304.89 c\u1eb7p (+40%)</td>\n                        <td>21.56%</td>\n                    </tr>\n                    <tr style=\"background: rgba(16, 185, 129, 0.12); font-weight: bold;\">\n                        <td style=\"color: #10B981;\">SuperGlue + Edge-LLIE (FP32)</td>\n                        <td class=\"best\">709 : 702 \u0111i\u1ec3m</td>\n                        <td class=\"best\" style=\"color: #10B981;\">304.89 c\u1eb7p (+40%)</td>\n                        <td>21.55%</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 6 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/edgellie/fig_6_p8.png\" alt=\"Edge-LLIE Figure 6 Feature Matching Visuals\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 6: Tr\u1ef1c quan h\u00f3a k\u1ebft qu\u1ea3 kh\u1edbp \u0111i\u1ec3m \u0111\u1eb7c tr\u01b0ng b\u1eb1ng m\u1ea1ng SuperGlue tr\u00ean b\u1ed9 d\u1eef li\u1ec7u MID.</strong> (a) \u1ea2nh t\u1ed1i: c\u00e1c \u0111\u01b0\u1eddng n\u1ed1i \u0111i\u1ec3m kh\u1edbp th\u01b0a th\u1edbt v\u00e0 sai l\u1ec7ch nhi\u1ec1u. (b) Sau khi qua Edge-LLIE INT8: m\u1ea1ng t\u00ecm th\u1ea5y d\u00e0y \u0111\u1eb7c c\u00e1c \u0111\u01b0\u1eddng li\u00ean k\u1ebft chu\u1ea9n x\u00e1c tr\u00ean b\u1ec1 m\u1eb7t c\u1ea5u tr\u00fac \u0111\u1ed3 v\u1eadt.\n            </figcaption>\n        </figure>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">5.</span> Th\u1ea3o Lu\u1eadn & Gi\u1edbi H\u1ea1n Nghi\u00ean C\u1ee9u</h3>\n        <p>\n            M\u00f4 h\u00ecnh Edge-LLIE ch\u1ee9ng minh r\u1eb1ng vi\u1ec7c t\u1ed1i \u01b0u h\u00f3a c\u00f3 ch\u1ee7 \u0111\u00edch cho c\u00e1c t\u00e1c v\u1ee5 bi\u00ean mang l\u1ea1i gi\u00e1 tr\u1ecb th\u1ef1c ti\u1ec5n r\u1ea5t cao. Tuy nhi\u00ean, nghi\u00ean c\u1ee9u c\u0169ng ch\u1ec9 ra h\u1ea1n ch\u1ebf: vi\u1ec7c l\u01b0\u1ee3ng t\u1eed h\u00f3a INT8 thu\u1ea7n t\u00fay (PTQ) c\u00f3 th\u1ec3 g\u00e2y ra hi\u1ec7n t\u01b0\u1ee3ng c\u1eaft c\u1ee5t bi\u00ean \u0111\u1ed9 m\u00e0u s\u1eafc (clipping range) trong m\u1ed9t s\u1ed1 k\u00eanh m\u00e0u RGB ph\u1ee9c t\u1ea1p. H\u01b0\u1edbng ph\u00e1t tri\u1ec3n ti\u1ebfp theo l\u00e0 nghi\u00ean c\u1ee9u k\u1ef9 thu\u1eadt l\u01b0\u1ee3ng t\u1eed h\u00f3a c\u00f3 nh\u1eadn th\u1ee9c tri gi\u00e1c trong qu\u00e1 tr\u00ecnh hu\u1ea5n luy\u1ec7n (Perceptual Quantization-Aware Training - QAT).\n        </p>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">6.</span> B\u00e0i H\u1ecdc Kinh Nghi\u1ec7m Cho \u0110\u1ed3 \u00c1n Cao H\u1ecdc UIT CS2203</h3>\n        <p>\n            C\u00e1c k\u1ebft qu\u1ea3 t\u1eeb Edge-LLIE kh\u1eb3ng \u0111\u1ecbnh t\u00ednh \u0111\u00fang \u0111\u1eafn trong \u0111\u1ecbnh h\u01b0\u1edbng ki\u1ebfn tr\u00fac m\u1ea1ng c\u1ee7a \u0110\u1ed3 \u00e1n m\u00f4n h\u1ecdc t\u1ea1i UIT:\n        </p>\n        <ol>\n            <li><strong>Kh\u00f4ng ch\u1ea1y \u0111ua tham s\u1ed1 m\u00f9 qu\u00e1ng:</strong> M\u1ed9t m\u1ea1ng Compact U-Net c\u00f3 s\u1ed1 tham s\u1ed1 &lt; 1.5M v\u1edbi thi\u1ebft k\u1ebf t\u00e1i tham s\u1ed1 h\u00f3a ho\u00e0n to\u00e0n \u0111\u1ee7 n\u0103ng l\u1ef1c ph\u1ee5c v\u1ee5 c\u00e1c t\u00e1c v\u1ee5 th\u1ecb gi\u00e1c th\u1eddi gian th\u1ef1c.</li>\n            <li><strong>Gi\u00e1 tr\u1ecb \u1ee9ng d\u1ee5ng h\u1ea1 ngu\u1ed3n:</strong> \u0110\u1ed3 \u00e1n kh\u00f4ng ch\u1ec9 d\u1eebng l\u1ea1i \u1edf c\u00e1c con s\u1ed1 PSNR/SSIM l\u00fd thuy\u1ebft, m\u00e0 vi\u1ec7c gi\u1eef nguy\u00ean \u0111\u01b0\u1ee3c c\u00e1c \u0111\u01b0\u1eddng n\u00e9t vi\u1ec1n c\u1ea1nh (edges) ch\u00ednh l\u00e0 nh\u00e2n t\u1ed1 quy\u1ebft \u0111\u1ecbnh \u0111\u1ec3 m\u00f4 h\u00ecnh h\u1ed7 tr\u1ee3 \u0111\u1eafc l\u1ef1c cho c\u00e1c b\u00e0i to\u00e1n Computer Vision th\u1ef1c t\u1ebf.</li>\n        </ol>\n    </div>\n</article>\n",
    "hvi": "\n<article class=\"paper-article\">\n    <div class=\"paper-reader-toolbar\">\n        <div class=\"paper-toolbar-group\">\n            <span style=\"font-weight: 700; color: #A78BFA; font-size: 0.85rem;\">CVPR 2025 Paper Reader (Full Translation)</span>\n            <button class=\"paper-tool-btn btn-col-toggle\" onclick=\"togglePaperColumns('hvi')\">\ud83d\udcc4 Ch\u1ebf \u0110\u1ed9 1 C\u1ed9t (D\u1ecdc)</button>\n        </div>\n        <div class=\"paper-toolbar-group\">\n            <a href=\"papers/hvi.html\" target=\"_blank\" class=\"paper-tool-btn\">\u2197\ufe0f M\u1edf Trang \u0110\u1ed9c L\u1eadp To\u00e0n M\u00e0n H\u00ecnh</a>\n            <button class=\"paper-tool-btn\" onclick=\"closePaperReader('hvi')\">\u2715 \u0110\u00f3ng B\u00e0i B\u00e1o</button>\n        </div>\n    </div>\n\n    <header class=\"paper-header\">\n        <span class=\"paper-venue-badge\" style=\"background: rgba(167, 139, 250, 0.12); color: #A78BFA; border-color: rgba(167, 139, 250, 0.35);\">IEEE / CVF CVPR 2025 \u2022 COLOR SCIENCE & FOUNDATIONAL INNOVATION</span>\n        <h1 class=\"paper-title\">HVI: Kh\u00f4ng Gian M\u00e0u M\u1edbi Cho T\u0103ng C\u01b0\u1eddng \u1ea2nh Thi\u1ebfu S\u00e1ng</h1>\n        <h2 class=\"paper-title-en\">HVI: A New Color Space for Low-light Image Enhancement</h2>\n        <div class=\"paper-authors\">\n            <strong>Jinmin Yan</strong>, <strong>Jiawei Zhang</strong>, <strong>Yingying Wang</strong>, <strong>Yanyun Qu</strong>, <strong>Dacheng Tao</strong>\n        </div>\n        <div class=\"paper-affiliations\">\n            \u0110\u1ea1i h\u1ecdc H\u1ea1 M\u00f4n, \u0110\u1ea1i h\u1ecdc Sydney, Vi\u1ec7n Nghi\u00ean c\u1ee9u Tr\u00ed tu\u1ec7 Nh\u00e2n t\u1ea1o JD Explore Academy\n        </div>\n        <div class=\"paper-links-row\">\n            <a href=\"https://github.com/flyywh/HVI-CIDNet\" target=\"_blank\" class=\"paper-ext-link\">\ud83d\udcbb M\u00e3 Ngu\u1ed3n Ch\u00ednh Th\u1ee9c: github.com/flyywh/HVI-CIDNet</a>\n            <a href=\"../papers/Yan_HVI_A_New_Color_Space_for_Low-light_Image_Enhancement_CVPR_2025_paper.pdf\" target=\"_blank\" class=\"paper-ext-link\">\ud83d\udcd1 T\u1ea3i File PDF K\u1ef7 Y\u1ebfu CVPR (7.8 MB)</a>\n        </div>\n    </header>\n\n    <div class=\"paper-abstract-box\">\n        <div class=\"paper-abstract-title\">T\u00f3m T\u1eaft B\u00e0i B\u00e1o (Abstract)</div>\n        <p class=\"paper-abstract-text\">\n            H\u1ea7u h\u1ebft c\u00e1c gi\u1ea3i thu\u1eadt t\u0103ng c\u01b0\u1eddng \u1ea3nh thi\u1ebfu s\u00e1ng (LLIE) hi\u1ec7n nay thao t\u00e1c tr\u1ef1c ti\u1ebfp trong kh\u00f4ng gian m\u00e0u ti\u00eau chu\u1ea9n <strong>sRGB</strong> ho\u1eb7c chuy\u1ec3n \u0111\u1ed5i sang kh\u00f4ng gian <strong>HSV</strong>. Tuy nhi\u00ean, trong kh\u00f4ng gian sRGB, th\u00f4ng tin c\u01b0\u1eddng \u0111\u1ed9 chi\u1ebfu s\u00e1ng (illumination) v\u00e0 th\u00f4ng tin s\u1eafc \u0111\u1ed9 m\u00e0u s\u1eafc (chromaticity) b\u1ecb li\u00ean k\u1ebft ch\u1eb7t ch\u1ebd (entangled), khi\u1ebfn vi\u1ec7c k\u00edch s\u00e1ng b\u1ee9c \u1ea3nh t\u1ea5t y\u1ebfu d\u1eabn \u0111\u1ebfn hi\u1ec7n t\u01b0\u1ee3ng m\u00e9o m\u00f3 m\u00e0u s\u1eafc v\u00e0 b\u00e3o h\u00f2a c\u1ee5c b\u1ed9. M\u1eb7t kh\u00e1c, vi\u1ec7c chuy\u1ec3n sang HSV m\u1eb7c d\u00f9 t\u00e1ch \u0111\u01b0\u1ee3c k\u00eanh \u0111\u1ed9 s\u00e1ng V, nh\u01b0ng l\u1ea1i sinh ra hai d\u1ea1ng <em>nhi\u1ec5u kh\u00f4ng gian m\u00e0u (color space noises)</em> v\u00f4 c\u00f9ng nghi\u00eam tr\u1ecdng: (1) <strong>Hi\u1ec7n t\u01b0\u1ee3ng \u0111\u1ee9t g\u00e3y m\u00e0u \u0111\u1ecf (red discontinuity)</strong> do t\u00ednh ch\u1ea5t tu\u1ea7n ho\u00e0n theo chu k\u1ef3 modulo c\u1ee7a tr\u1ee5c Hue ($h=0$ v\u00e0 $h=6$), v\u00e0 (2) <strong>Hi\u1ec7n t\u01b0\u1ee3ng k\u1ef3 d\u1ecb m\u1eb7t ph\u1eb3ng \u0111en (black plane noise)</strong> khi \u0111\u1ed9 b\u00e3o h\u00f2a $S$ s\u1ee5p \u0111\u1ed5 kh\u00f4ng x\u00e1c \u0111\u1ecbnh \u1edf v\u00f9ng b\u00f3ng t\u1ed1i c\u1ef1c s\u00e2u. \u0110\u1ec3 gi\u1ea3i quy\u1ebft tri\u1ec7t \u0111\u1ec3 v\u1ea5n \u0111\u1ec1 g\u1ed1c r\u1ec5 n\u00e0y, ch\u00fang t\u00f4i \u0111\u1ec1 xu\u1ea5t <strong>Kh\u00f4ng gian m\u00e0u HVI (Hue, Value, Intensity)</strong> ho\u00e0n to\u00e0n m\u1edbi. HVI gi\u1ea3i quy\u1ebft hi\u1ec7n t\u01b0\u1ee3ng \u0111\u1ee9t g\u00e3y m\u00e0u \u0111\u1ecf b\u1eb1ng ph\u00e9p ph\u00e2n c\u1ef1c g\u00f3c tr\u1ef1c giao (polarized HS) v\u00e0 gi\u1ea3i quy\u1ebft nhi\u1ec5u v\u00f9ng t\u1ed1i b\u1eb1ng h\u00e0m s\u1ee5p \u0111\u1ed5 c\u01b0\u1eddng \u0111\u1ed9 kh\u1ea3 vi (learnable intensity collapse function $C_k$). \u0110\u1ed3ng th\u1eddi, ch\u00fang t\u00f4i thi\u1ebft k\u1ebf m\u1ea1ng n\u01a1-ron hai nh\u00e1nh <strong>CIDNet (Color and Intensity Decoupling Network)</strong> x\u1eed l\u00fd \u0111\u1ed9c l\u1eadp m\u1eb7t ph\u1eb3ng m\u00e0u s\u1eafc HV v\u00e0 tr\u1ee5c c\u01b0\u1eddng \u0111\u1ed9 I. CIDNet thi\u1ebft l\u1eadp k\u1ef7 l\u1ee5c SOTA m\u1edbi tr\u00ean LOLv1 (<strong>28.20 dB PSNR</strong>), LOLv2-Real (<strong>24.11 dB</strong>), v\u00e0 v\u01b0\u1ee3t tr\u1ed9i c\u00e1c ph\u01b0\u01a1ng ph\u00e1p tr\u01b0\u1edbc t\u1edbi <strong>+6.68 dB</strong> tr\u00ean t\u1eadp d\u1eef li\u1ec7u b\u00f3ng t\u1ed1i c\u1ef1c \u0111\u1ed9 Sony-Total-Dark ch\u1ec9 v\u1edbi 1.88M tham s\u1ed1.\n        </p>\n    </div>\n\n    <!-- Figure 1 -->\n    <figure class=\"paper-figure full-width\">\n        <img src=\"assets/images/papers/hvi/fig_1_p2.png\" alt=\"HVI Figure 1 Transformation Process\">\n        <figcaption class=\"paper-figcaption\">\n            <strong>H\u00ecnh 1: Qu\u00e1 tr\u00ecnh chuy\u1ec3n \u0111\u1ed5i t\u1eeb kh\u00f4ng gian m\u00e0u sRGB qua HSV sang kh\u00f4ng gian m\u00e0u HVI \u0111\u1ec1 xu\u1ea5t.</strong> H\u00e0ng tr\u00ean: Qu\u00e1 tr\u00ecnh h\u00ecnh th\u00e0nh HVI. Khi chuy\u1ec3n t\u1eeb sRGB sang HSV, tr\u1ee5c Hue b\u1ecb \u0111\u1ee9t \u0111o\u1ea1n \u1edf m\u00e0u \u0111\u1ecf v\u00e0 v\u00f9ng t\u1ed1i b\u1ecb nhi\u1ec5u h\u1ea1t loang l\u1ed5. HVI \u00e1p d\u1ee5ng ph\u00e9p ph\u00e2n c\u1ef1c g\u00f3c \u0111\u1ec3 n\u1ed1i li\u1ec1n tr\u1ee5c \u0111\u1ecf v\u00e0 s\u1eed d\u1ee5ng h\u00e0m s\u1ee5p \u0111\u1ed5 c\u01b0\u1eddng \u0111\u1ed9 $C_k$ \u0111\u1ec3 gom c\u1ee5m c\u00e1c \u0111i\u1ec3m t\u1ed1i, gi\u00fap bi\u1ec3u di\u1ec5n m\u00e0u s\u1eafc ho\u00e0n to\u00e0n li\u00ean t\u1ee5c v\u00e0 \u1ed5n \u0111\u1ecbnh. (Nh\u1ea5p chu\u1ed9t \u0111\u1ec3 ph\u00f3ng to).\n        </figcaption>\n    </figure>\n\n    <div class=\"paper-content-columns\">\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">1.</span> Gi\u1edbi Thi\u1ec7u (Introduction)</h3>\n        <p>\n            Trong b\u00e0i to\u00e1n t\u0103ng c\u01b0\u1eddng \u1ea3nh thi\u1ebfu s\u00e1ng (LLIE), vi\u1ec7c l\u1ef1a ch\u1ecdn kh\u00f4ng gian m\u00e0u bi\u1ec3u di\u1ec5n h\u00ecnh \u1ea3nh (color space representation) \u0111\u00f3ng vai tr\u00f2 quy\u1ebft \u0111\u1ecbnh t\u1edbi ch\u1ea5t l\u01b0\u1ee3ng ph\u1ee5c h\u1ed3i. Khi ch\u1ee5p trong \u0111i\u1ec1u ki\u1ec7n \u0111\u00f3i quang t\u1eed, c\u1ea3m bi\u1ebfn m\u00e1y \u1ea3nh t\u1ea1o ra c\u00e1c gi\u00e1 tr\u1ecb \u0111i\u1ec3m \u1ea3nh sRGB v\u1edbi \u0111\u1ed9 nh\u1ea1y nhi\u1ec5u r\u1ea5t cao. N\u1ebfu m\u1ed9t m\u1ea1ng n\u01a1-ron th\u1ef1c hi\u1ec7n bi\u1ebfn \u0111\u1ed5i tr\u1ef1c ti\u1ebfp tr\u00ean c\u00e1c k\u00eanh RGB, s\u1ef1 khu\u1ebfch \u0111\u1ea1i t\u00edn hi\u1ec7u s\u00e1ng s\u1ebd l\u00e0m sai l\u1ec7ch t\u1ef7 l\u1ec7 gi\u1eefa ba k\u00eanh Red, Green, Blue, g\u00e2y ra hi\u1ec7n t\u01b0\u1ee3ng \u0111\u1ed5i m\u00e0u (color shifting) v\u00e0 qu\u1ea7ng m\u00e0u gi\u1ea3.\n        </p>\n        <p>\n            C\u00e1c nghi\u00ean c\u1ee9u quang h\u1ecdc kinh \u0111i\u1ec3n [9, 34] \u0111\u1ec1 xu\u1ea5t t\u00e1ch r\u1eddi th\u00e0nh ph\u1ea7n chi\u1ebfu s\u00e1ng v\u00e0 th\u00e0nh ph\u1ea7n s\u1eafc \u0111\u1ed9 b\u1eb1ng c\u00e1ch chuy\u1ec3n sang kh\u00f4ng gian m\u00e0u HSV (Hue - S\u1eafc m\u00e0u, Saturation - \u0110\u1ed9 b\u00e3o h\u00f2a, Value - Gi\u00e1 tr\u1ecb s\u00e1ng t\u1ed1i). Tuy nhi\u00ean, ph\u00e9p bi\u1ebfn \u0111\u1ed5i to\u00e1n h\u1ecdc phi tuy\u1ebfn sang HSV t\u1ea1o ra hai khuy\u1ebft t\u1eadt c\u1ed1 h\u1eefu:\n        </p>\n        <ul>\n            <li><strong>\u0110\u1ee9t g\u00e3y m\u00e0u \u0111\u1ecf (Red Discontinuity):</strong> Tr\u1ee5c g\u00f3c Hue \u0111\u01b0\u1ee3c bi\u1ec3u di\u1ec5n t\u1eeb 0 \u0111\u1ebfn 6 (ho\u1eb7c $0^\\circ$ \u0111\u1ebfn $360^\\circ$). M\u00e0u \u0111\u1ecf th\u1ef1c t\u1ebf n\u1eb1m \u1edf c\u1ea3 hai \u0111\u1ea7u m\u00fat gi\u1edbi h\u1ea1n ($h \to 0$ v\u00e0 $h \to 6$). Trong kh\u00f4ng gian Euclid, hai \u0111i\u1ec3m \u1ea3nh m\u00e0u \u0111\u1ecf r\u1ea5t g\u1ea7n nhau v\u1ec1 m\u1eb7t th\u1ecb gi\u00e1c l\u1ea1i c\u00f3 kho\u1ea3ng c\u00e1ch s\u1ed1 h\u1ecdc c\u1ef1c l\u1edbn, g\u00e2y b\u1ed1i r\u1ed1i cho qu\u00e1 tr\u00ecnh t\u1ed1i \u01b0u h\u00f3a gradient c\u1ee7a m\u1ea1ng n\u01a1-ron.</li>\n            <li><strong>K\u1ef3 d\u1ecb m\u1eb7t ph\u1eb3ng \u0111en (Black Plane Singularity):</strong> Khi c\u01b0\u1eddng \u0111\u1ed9 \u00e1nh s\u00e1ng $I_{max} \to 0$, gi\u00e1 tr\u1ecb b\u00e3o h\u00f2a m\u00e0u $S = \\Delta / I_{max}$ tr\u1edf th\u00e0nh ph\u00e9p chia cho 0. T\u1ea1i v\u00f9ng b\u00f3ng t\u1ed1i c\u1ef1c s\u00e2u, nhi\u1ec5u c\u1ea3m bi\u1ebfn nh\u1ecf nh\u1ea5t c\u0169ng b\u1ecb nh\u00e2n l\u00ean v\u00f4 h\u1ea1n l\u1ea7n, bi\u1ebfn m\u1eb7t ph\u1eb3ng \u0111en th\u00e0nh m\u1ed9t v\u00f9ng nhi\u1ec5u h\u1ea1t b\u1eeba b\u00e3i.</li>\n        </ul>\n        <p>\n            B\u00e0i b\u00e1o n\u00e0y gi\u1ea3i quy\u1ebft tri\u1ec7t \u0111\u1ec3 hai khuy\u1ebft t\u1eadt to\u00e1n h\u1ecdc tr\u00ean b\u1eb1ng c\u00e1ch \u0111\u1ecbnh ngh\u0129a kh\u00f4ng gian m\u00e0u HVI chu\u1ea9n x\u00e1c v\u1ec1 m\u1eb7t v\u1eadt l\u00fd v\u00e0 t\u01b0\u01a1ng th\u00edch ho\u00e0n h\u1ea3o v\u1edbi h\u1ecdc s\u00e2u.\n        </p>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">2.</span> C\u01a1 S\u1edf To\u00e1n H\u1ecdc C\u1ee7a Kh\u00f4ng Gian M\u00e0u HVI</h3>\n        \n        <h4 class=\"paper-sub-heading\">2.1 \u01af\u1edbc L\u01b0\u1ee3ng C\u01b0\u1eddng \u0110\u1ed9 Theo L\u00fd Thuy\u1ebft Max-RGB</h4>\n        <p>\n            Thay v\u00ec d\u1ef1a v\u00e0o c\u00e1c m\u1ea1ng h\u1ecdc s\u00e2u d\u1ef1 \u0111o\u00e1n b\u1ea3n \u0111\u1ed3 \u00e1nh s\u00e1ng \u0111\u1ea7y r\u1ee7i ro, ch\u00fang t\u00f4i k\u1ebf th\u1eeba L\u00fd thuy\u1ebft Max-RGB [21] \u0111\u1ec3 \u01b0\u1edbc l\u01b0\u1ee3ng tr\u1ef1c ti\u1ebfp b\u1ea3n \u0111\u1ed3 c\u01b0\u1eddng \u0111\u1ed9 chi\u1ebfu s\u00e1ng c\u1ef1c \u0111\u1ea1i $I_{max} \\in \\mathbb{R}^{H \times W}$ t\u1ea1i m\u1ed7i \u0111i\u1ec3m \u1ea3nh $x$:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$\\mathbf{I}_{max}(x) = \\max_{c \\in \\{R,G,B\\}} (\\mathbf{I}_c(x))$$</div>\n            <span class=\"paper-equation-num\">(1)</span>\n        </div>\n        <p>\n            Trong bi\u1ec3u di\u1ec5n HSV kinh \u0111i\u1ec3n, \u0111\u1ed9 b\u00e3o h\u00f2a $S$ v\u00e0 g\u00f3c s\u1eafc $H$ \u0111\u01b0\u1ee3c t\u00ednh theo c\u00f4ng th\u1ee9c:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$s = \begin{cases} 0, & \\mathbf{I}_{max} = 0 \\ \frac{\\Delta}{\\mathbf{I}_{max}}, & \\mathbf{I}_{max} \ne 0 \\end{cases}, \\quad \text{v\u1edbi } \\Delta = \\mathbf{I}_{max} - \\min_{c}(\\mathbf{I}_c)$$</div>\n            <span class=\"paper-equation-num\">(2)</span>\n        </div>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$h = \begin{cases} 0, & \text{n\u1ebfu } s = 0 \\ \frac{\\mathbf{I}_G - \\mathbf{I}_B}{\\Delta} \bmod 6, & \text{n\u1ebfu } \\mathbf{I}_{max} = \\mathbf{I}_R \\ 2 + \frac{\\mathbf{I}_B - \\mathbf{I}_R}{\\Delta}, & \text{n\u1ebfu } \\mathbf{I}_{max} = \\mathbf{I}_G \\ 4 + \frac{\\mathbf{I}_R - \\mathbf{I}_G}{\\Delta}, & \text{n\u1ebfu } \\mathbf{I}_{max} = \\mathbf{I}_B \\end{cases}$$</div>\n            <span class=\"paper-equation-num\">(3)</span>\n        </div>\n\n        <h4 class=\"paper-sub-heading\">2.2 Ph\u00e2n C\u1ef1c Tr\u1ee5c S\u1eafc \u0110\u1ed9 (Polarized HS) & H\u00e0m S\u1ee5p \u0110\u1ed5 C\u01b0\u1eddng \u0110\u1ed9 ($C_k$)</h4>\n        <p>\n            \u0110\u1ec3 x\u00f3a b\u1ecf s\u1ef1 \u0111\u1ee9t g\u00e3y c\u1ee7a m\u00e0u \u0111\u1ecf t\u1ea1i $h=0$ v\u00e0 $h=6$, ch\u00fang t\u00f4i ph\u00e2n c\u1ef1c tr\u1ee5c Hue th\u00e0nh hai t\u1ecda \u0111\u1ed9 tr\u1ef1c giao tr\u00ean v\u00f2ng tr\u00f2n l\u01b0\u1ee3ng gi\u00e1c:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$h_{ortho} = \\cos\\left(\frac{\\pi h}{3}\right), \\quad v_{ortho} = \\sin\\left(\frac{\\pi h}{3}\right)$$</div>\n            <span class=\"paper-equation-num\">(4)</span>\n        </div>\n        <p>\n            Khi \u0111\u01b0\u1ee3c ph\u00e2n c\u1ef1c, m\u1ecdi m\u00e0u s\u1eafc c\u00f9ng lo\u1ea1i \u0111\u1ec1u n\u1eb1m g\u1ea7n nhau trong kh\u00f4ng gian Euclid hai chi\u1ec1u $(h_{ortho}, v_{ortho})$, tri\u1ec7t ti\u00eau ho\u00e0n to\u00e0n s\u1ef1 nh\u1ea3y c\u00f3c gi\u00e1 tr\u1ecb \u1edf bi\u00ean m\u00e0u \u0111\u1ecf.\n        </p>\n        <p>\n            \u0110\u1ec3 x\u1eed l\u00fd hi\u1ec7n t\u01b0\u1ee3ng k\u1ef3 d\u1ecb chia cho 0 \u1edf v\u00f9ng t\u1ed1i, ch\u00fang t\u00f4i thi\u1ebft k\u1ebf <strong>h\u00e0m s\u1ee5p \u0111\u1ed5 c\u01b0\u1eddng \u0111\u1ed9 kh\u1ea3 vi (Learnable Intensity Collapse Function $C_k$)</strong>:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$\\mathbf{C}_k(x) = \\sqrt[k]{\\sin\\left(\frac{\\pi \\mathbf{I}_{max}(x)}{2}\right) + \\epsilon}$$</div>\n            <span class=\"paper-equation-num\">(5)</span>\n        </div>\n        <p>\n            Trong \u0111\u00f3 $k \\in \\mathbb{Q}^+$ l\u00e0 tham s\u1ed1 c\u00f3 th\u1ec3 hu\u1ea5n luy\u1ec7n h\u1ecdc t\u1ef1 \u0111\u1ed9ng theo t\u1eebng b\u1ed9 d\u1eef li\u1ec7u, v\u00e0 $\\epsilon = 10^{-8}$ ng\u0103n ch\u1eb7n b\u00f9ng n\u1ed5 gradient. T\u1ecda \u0111\u1ed9 hai k\u00eanh s\u1eafc \u0111\u1ed9 <strong>Horizontal ($\\hat{H}$)</strong> v\u00e0 <strong>Vertical ($\\hat{V}$)</strong> c\u1ee7a HVI \u0111\u01b0\u1ee3c \u0111\u1ecbnh ngh\u0129a l\u00e0:\n        </p>\n        <div class=\"paper-equation\">\n            <div class=\"paper-equation-math\">$$\\mathbf{\\hat{H}} = \\mathbf{C}_k \\odot \\mathbf{S} \\odot h_{ortho}, \\quad \\mathbf{\\hat{V}} = \\mathbf{C}_k \\odot \\mathbf{S} \\odot v_{ortho}$$</div>\n            <span class=\"paper-equation-num\">(6)</span>\n        </div>\n        <p>\n            B\u1ed9 ba $(\\mathbf{\\hat{H}}, \\mathbf{\\hat{V}}, \\mathbf{I}_{max})$ t\u1ea1o th\u00e0nh bi\u1ec3u di\u1ec5n \u1ea3nh ho\u00e0n ch\u1ec9nh trong kh\u00f4ng gian m\u00e0u HVI: tr\u01a1n tru, kh\u1ea3 vi, v\u00e0 ho\u00e0n to\u00e0n mi\u1ec5n nhi\u1ec5m v\u1edbi nhi\u1ec5u m\u1eb7t ph\u1eb3ng \u0111en.\n        </p>\n\n        <!-- Figure 2 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/hvi/fig_2_p5.png\" alt=\"HVI CIDNet Architecture\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 2: Ki\u1ebfn tr\u00fac m\u1ea1ng hai nh\u00e1nh CIDNet (Color and Intensity Decoupling Network).</strong> \u1ea2nh sRGB \u0111\u1ea7u v\u00e0o tr\u01b0\u1edbc ti\u00ean \u0111\u01b0\u1ee3c bi\u1ebfn \u0111\u1ed5i th\u00e0nh \u1ea3nh HVI qua module HVIT. Nh\u00e1nh <em>HV-Branch</em> t\u1eadp trung d\u1eadp t\u1eaft nhi\u1ec5u h\u1ea1t v\u00e0 kh\u00f4i ph\u1ee5c s\u1ef1 h\u00e0i h\u00f2a m\u00e0u s\u1eafc tr\u00ean m\u1eb7t ph\u1eb3ng tr\u1ef1c giao. Nh\u00e1nh <em>I-Branch</em> chuy\u00ean tr\u00e1ch vi\u1ec7c t\u00e1i c\u00e2n b\u1eb1ng d\u1ea3i s\u00e1ng \u0111\u1ed9ng tr\u00ean to\u00e0n \u1ea3nh. Cu\u1ed1i c\u00f9ng, module Inv-HVIT chuy\u1ec3n ng\u01b0\u1ee3c \u1ea3nh ph\u1ee5c h\u1ed3i v\u1ec1 l\u1ea1i \u0111\u1ecbnh d\u1ea1ng sRGB ti\u00eau chu\u1ea9n.\n            </figcaption>\n        </figure>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">3.</span> Ki\u1ebfn Tr\u00fac M\u1ea1ng Hai Nh\u00e1nh CIDNet (Architecture)</h3>\n        <p>\n            Nh\u1edd vi\u1ec7c ph\u00e2n r\u00e3 t\u01b0\u1eddng minh b\u00e0i to\u00e1n m\u00e0u s\u1eafc v\u00e0 b\u00e0i to\u00e1n \u0111\u1ed9 s\u00e1ng, CIDNet kh\u00f4ng c\u1ea7n s\u1eed d\u1ee5ng c\u00e1c kh\u1ed1i Transformer c\u1ed3ng k\u1ec1nh:\n        </p>\n        <ul>\n            <li><strong>Nh\u00e1nh HV (HV-Branch):</strong> Nh\u1eadn \u0111\u1ea7u v\u00e0o l\u00e0 2 k\u00eanh $(\\hat{H}, \\hat{V})$. V\u00ec th\u00f4ng tin \u0111\u1ed9 s\u00e1ng \u0111\u00e3 \u0111\u01b0\u1ee3c lo\u1ea1i b\u1ecf, nh\u00e1nh n\u00e0y ch\u1ec9 t\u1eadp trung v\u00e0o vi\u1ec7c l\u1ecdc nhi\u1ec5u m\u00e0u s\u1eafc (chromatic denoising) b\u1eb1ng c\u00e1c kh\u1ed1i t\u00edch ch\u1eadp \u0111a thang \u0111o.</li>\n            <li><strong>Nh\u00e1nh I (I-Branch):</strong> Nh\u1eadn \u0111\u1ea7u v\u00e0o l\u00e0 k\u00eanh c\u01b0\u1eddng \u0111\u1ed9 $I_{max}$. Nh\u00e1nh n\u00e0y d\u1ef1 \u0111o\u00e1n b\u1ea3n \u0111\u1ed3 h\u1ec7 s\u1ed1 khu\u1ebfch \u0111\u1ea1i \u00e1nh s\u00e1ng to\u00e0n c\u1ee5c v\u00e0 \u0111\u1ecba ph\u01b0\u01a1ng, \u0111\u1ea3m b\u1ea3o c\u00e1c v\u00f9ng t\u1ed1i s\u00e2u \u0111\u01b0\u1ee3c k\u00e9o s\u00e1ng trong khi c\u00e1c v\u00f9ng s\u00e1ng kh\u00f4ng b\u1ecb l\u00f3a v\u1ee1 h\u1ea1t.</li>\n            <li><strong>Bi\u1ebfn \u0111\u1ed5i HVI ng\u01b0\u1ee3c kh\u1ea3 vi (Perceptual-Inverse HVIT):</strong> T\u00e1i h\u1ee3p c\u00e1c k\u00eanh \u0111\u00e3 ph\u1ee5c h\u1ed3i th\u00e0nh \u1ea3nh sRGB ho\u00e0n ch\u1ec9nh \u0111\u1ec3 t\u00ednh to\u00e1n h\u00e0m m\u1ea5t m\u00e1t.</li>\n        </ul>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">4.</span> K\u1ebft Qu\u1ea3 Th\u1ef1c Nghi\u1ec7m & \u0110\u00e1nh Gi\u00e1 \u0110\u1ecbnh L\u01b0\u1ee3ng (Experiments)</h3>\n\n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 1: \u0110\u00e1nh gi\u00e1 \u0111\u1ecbnh l\u01b0\u1ee3ng tr\u00ean c\u00e1c t\u1eadp d\u1eef li\u1ec7u chu\u1ea9n c\u00f3 c\u1eb7p \u1ea3nh LOLv1, LOLv2-Real v\u00e0 LOLv2-Synthetic. CIDNet thi\u1ebft l\u1eadp k\u1ef7 l\u1ee5c SOTA m\u1edbi v\u1edbi ch\u1ec9 1.88M tham s\u1ed1 v\u00e0 7.57 GFLOPs.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>Ph\u01b0\u01a1ng Ph\u00e1p</th>\n                        <th>Kh\u00f4ng Gian M\u00e0u</th>\n                        <th>Tham S\u1ed1 (M) \u2193</th>\n                        <th>FLOPs (G) \u2193</th>\n                        <th>LOLv1 PSNR \u2191</th>\n                        <th>LOLv1 SSIM \u2191</th>\n                        <th>LOLv1 LPIPS \u2193</th>\n                        <th>LOLv2-Real PSNR \u2191</th>\n                        <th>LOLv2-Real SSIM \u2191</th>\n                        <th>LOLv2-Syn PSNR \u2191</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>RetinexNet [43]</td><td>Retinex</td><td>0.84M</td><td>584.47</td><td>18.91</td><td>0.427</td><td>0.470</td><td>16.10</td><td>0.401</td><td>17.14</td></tr>\n                    <tr><td>KinD [51]</td><td>Retinex</td><td>8.02M</td><td>34.99</td><td>23.02</td><td>0.843</td><td>0.156</td><td>17.54</td><td>0.669</td><td>18.32</td></tr>\n                    <tr><td>ZeroDCE [10]</td><td>sRGB</td><td>0.08M</td><td>4.83</td><td>21.88</td><td>0.640</td><td>0.335</td><td>16.06</td><td>0.580</td><td>17.71</td></tr>\n                    <tr><td>RUAS [33]</td><td>Retinex</td><td>0.003M</td><td>0.83</td><td>18.65</td><td>0.518</td><td>0.270</td><td>15.33</td><td>0.488</td><td>13.77</td></tr>\n                    <tr><td>LLFlow [41]</td><td>sRGB</td><td>17.42M</td><td>358.40</td><td>25.00</td><td>0.871</td><td>0.117</td><td>17.43</td><td>0.831</td><td>24.81</td></tr>\n                    <tr><td>EnlightenGAN [18]</td><td>sRGB</td><td>114.35M</td><td>61.01</td><td>20.00</td><td>0.691</td><td>0.317</td><td>18.23</td><td>0.617</td><td>16.57</td></tr>\n                    <tr><td>SNR-Aware [46]</td><td>SNR + RGB</td><td>4.01M</td><td>26.35</td><td>26.72</td><td>0.851</td><td>0.152</td><td>21.48</td><td>0.849</td><td>24.14</td></tr>\n                    <tr><td>Bread [11]</td><td>YCbCr</td><td>2.02M</td><td>19.85</td><td>25.30</td><td>0.847</td><td>0.155</td><td>20.83</td><td>0.847</td><td>17.63</td></tr>\n                    <tr><td>LLFormer [39]</td><td>sRGB</td><td>24.55M</td><td>22.52</td><td>25.76</td><td>0.823</td><td>0.167</td><td>20.06</td><td>0.792</td><td>24.04</td></tr>\n                    <tr><td>RetinexFormer [3]</td><td>Retinex</td><td>1.53M</td><td>15.85</td><td>27.14</td><td>0.850</td><td>0.129</td><td>22.79</td><td>0.840</td><td>25.67</td></tr>\n                    <tr><td>GSAD [16]</td><td>sRGB (Diffusion)</td><td>17.36M</td><td>442.02</td><td>27.61</td><td>0.876</td><td>0.092</td><td>20.15</td><td>0.846</td><td>24.47</td></tr>\n                    <tr style=\"background: rgba(167, 139, 250, 0.15); font-weight: bold;\">\n                        <td style=\"color: #A78BFA;\">CIDNet (Ours)</td>\n                        <td style=\"color: #A78BFA;\">HVI (\u0110\u1ec1 Xu\u1ea5t)</td>\n                        <td style=\"color: #A78BFA;\">1.88M</td>\n                        <td style=\"color: #A78BFA;\">7.57G</td>\n                        <td class=\"best\">28.20</td>\n                        <td class=\"best\">0.889</td>\n                        <td class=\"best\">0.079</td>\n                        <td class=\"best\">24.11</td>\n                        <td class=\"best\">0.871</td>\n                        <td class=\"best\">25.71</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 3 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/hvi/fig_3_p6.png\" alt=\"HVI Figure 3 Qualitative Comparison\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 3: So s\u00e1nh ch\u1ea5t l\u01b0\u1ee3ng tr\u1ef1c quan tr\u00ean t\u1eadp LOLv1 v\u00e0 LOLv2.</strong> CIDNet t\u00e1i t\u1ea1o m\u00e0u s\u1eafc trung th\u1ef1c tuy\u1ec7t \u0111\u1ed1i so v\u1edbi Ground Truth, kh\u00f4ng b\u1ecb b\u1ec7t m\u00e0u \u0111\u1ecf nh\u01b0 RetinexFormer hay b\u1ecb \u00e1m v\u00e0ng nh\u01b0 c\u00e1c m\u00f4 h\u00ecnh d\u1ef1a tr\u00ean sRGB.\n            </figcaption>\n        </figure>\n\n        <h4 class=\"paper-sub-heading\">4.1 \u0110\u00e1nh Gi\u00e1 Tr\u00ean T\u1eadp D\u1eef Li\u1ec7u B\u00f3ng T\u1ed1i C\u1ef1c \u0110\u1ed9 Sony-Total-Dark</h4>\n        <p>\n            Tr\u00ean t\u1eadp d\u1eef li\u1ec7u Sony-Total-Dark (c\u00e1c \u1ea3nh ch\u1ee5p kh\u00f4ng qua hi\u1ec7u ch\u1ec9nh gamma, d\u1ea3i s\u00e1ng c\u1ef1c th\u1ea5p g\u1ea7n nh\u01b0 \u0111en k\u1ecbt ho\u00e0n to\u00e0n), CIDNet th\u1ec3 hi\u1ec7n \u01b0u th\u1ebf \u00e1p \u0111\u1ea3o c\u1ee7a kh\u00f4ng gian m\u00e0u HVI.\n        </p>\n\n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 2: K\u1ebft qu\u1ea3 th\u1ef1c nghi\u1ec7m tr\u00ean t\u1eadp d\u1eef li\u1ec7u quy m\u00f4 l\u1edbn SICE, t\u1eadp b\u00f3ng t\u1ed1i c\u1ef1c h\u1ea1n Sony-Total-Dark v\u00e0 5 t\u1eadp \u1ea3nh kh\u00f4ng c\u00f3 nh\u00e3n (Unpaired: DICM, LIME, MEF, NPE, VV).</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>Ph\u01b0\u01a1ng Ph\u00e1p</th>\n                        <th>SICE PSNR (dB) \u2191</th>\n                        <th>SICE SSIM \u2191</th>\n                        <th>Sony-Total-Dark PSNR (dB) \u2191</th>\n                        <th>Sony-Total-Dark SSIM \u2191</th>\n                        <th>Unpaired BRISQUE \u2193</th>\n                        <th>Unpaired NIQE \u2193</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>RetinexNet [43]</td><td>12.42</td><td>0.613</td><td>15.70</td><td>0.395</td><td>23.29</td><td>4.558</td></tr>\n                    <tr><td>ZeroDCE [10]</td><td>12.45</td><td>0.639</td><td>14.09</td><td>0.090</td><td>26.34</td><td>4.763</td></tr>\n                    <tr><td>URetinexNet [44]</td><td>10.90</td><td>0.605</td><td>15.52</td><td>0.323</td><td>26.36</td><td>3.829</td></tr>\n                    <tr><td>RUAS [33]</td><td>8.66</td><td>0.494</td><td>12.62</td><td>0.081</td><td>36.37</td><td>4.800</td></tr>\n                    <tr><td>LLFlow [41]</td><td>12.74</td><td>0.617</td><td>16.23</td><td>0.367</td><td>28.09</td><td>4.221</td></tr>\n                    <tr style=\"background: rgba(167, 139, 250, 0.15); font-weight: bold;\">\n                        <td style=\"color: #A78BFA;\">CIDNet (Ours)</td>\n                        <td class=\"best\">13.44</td>\n                        <td class=\"best\">0.642</td>\n                        <td class=\"best\" style=\"color: #A78BFA;\">22.90 (+6.68 dB)</td>\n                        <td class=\"best\" style=\"color: #A78BFA;\">0.676</td>\n                        <td class=\"best\">23.52</td>\n                        <td class=\"best\">3.523</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 4 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/hvi/fig_4_p7.png\" alt=\"HVI Figure 4 Unpaired Datasets\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 4: \u0110\u00e1nh gi\u00e1 ch\u1ea5t l\u01b0\u1ee3ng tr\u1ef1c quan tr\u00ean 5 t\u1eadp d\u1eef li\u1ec7u ch\u1ee5p \u0111\u00eam th\u1ebf gi\u1edbi th\u1ef1c kh\u00f4ng c\u00f3 nh\u00e3n m\u1eabu (DICM, LIME, MEF, NPE, VV).</strong> CIDNet t\u0103ng c\u01b0\u1eddng chi ti\u1ebft r\u00f5 r\u1ec7t m\u00e0 kh\u00f4ng sinh ra nhi\u1ec5u h\u1ea1t loang l\u1ed5.\n            </figcaption>\n        </figure>\n\n        <h4 class=\"paper-sub-heading\">4.2 HVI Nh\u01b0 M\u1ed9t Module C\u1eafm-L\u00e0-Ch\u1ea1y (Universal Plug-in)</h4>\n        <p>\n            Ch\u00fang t\u00f4i ki\u1ec3m tra t\u00ednh t\u01b0\u01a1ng th\u00edch c\u1ee7a kh\u00f4ng gian m\u00e0u HVI b\u1eb1ng c\u00e1ch thay th\u1ebf module \u0111\u1ea7u v\u00e0o/\u0111\u1ea7u ra c\u1ee7a 6 ki\u1ebfn tr\u00fac SOTA hi\u1ec7n c\u00f3 b\u1eb1ng ph\u00e9p bi\u1ebfn \u0111\u1ed5i HVI tr\u00ean t\u1eadp LOLv2-Real.\n        </p>\n\n        <div class=\"paper-table-wrapper full-width\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 3: Hi\u1ec7u n\u0103ng c\u1ea3i thi\u1ec7n khi t\u00edch h\u1ee3p HVI nh\u01b0 m\u1ed9t module plug-in v\u00e0o c\u00e1c ki\u1ebfn tr\u00fac LLIE hi\u1ec7n h\u1eefu. M\u1ecdi m\u00f4 h\u00ecnh \u0111\u1ec1u t\u0103ng v\u1ecdt PSNR.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr>\n                        <th>M\u00f4 H\u00ecnh \u0110\u01b0\u1ee3c C\u1eafm HVI</th>\n                        <th>Lo\u1ea1i Ki\u1ebfn Tr\u00fac</th>\n                        <th>PSNR Ban \u0110\u1ea7u (dB)</th>\n                        <th>PSNR Sau Khi C\u1eafm HVI \u2191</th>\n                        <th>M\u1ee9c C\u1ea3i Thi\u1ec7n Tuy\u1ec7t \u0110\u1ed1i</th>\n                        <th>SSIM Sau C\u1eafm HVI \u2191</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td>FourLLIE [37]</td><td>CNN</td><td>22.35 dB</td><td>22.73 dB</td><td>+0.381 dB</td><td>0.856 (+0.009)</td></tr>\n                    <tr style=\"background: rgba(167, 139, 250, 0.12); font-weight: bold;\">\n                        <td style=\"color: #A78BFA;\">LEDNet [57]</td>\n                        <td>CNN Kh\u1eed M\u1edd</td>\n                        <td>19.94 dB</td>\n                        <td style=\"color: #A78BFA;\">23.39 dB</td>\n                        <td class=\"best\" style=\"color: #A78BFA;\">+3.456 dB (T\u0103ng V\u1ecdt)</td>\n                        <td>0.837 (+0.010)</td>\n                    </tr>\n                    <tr><td>SNR-Aware [46]</td><td>Transformer</td><td>21.48 dB</td><td>22.25 dB</td><td>+0.771 dB</td><td>0.840</td></tr>\n                    <tr style=\"background: rgba(167, 139, 250, 0.12); font-weight: bold;\">\n                        <td style=\"color: #A78BFA;\">LLFormer [39]</td>\n                        <td>Transformer</td>\n                        <td>20.06 dB</td>\n                        <td style=\"color: #A78BFA;\">22.67 dB</td>\n                        <td style=\"color: #A78BFA;\">+2.615 dB</td>\n                        <td>0.852 (+0.060)</td>\n                    </tr>\n                    <tr style=\"background: rgba(167, 139, 250, 0.15); font-weight: bold;\">\n                        <td style=\"color: #A78BFA;\">GSAD [15]</td>\n                        <td>M\u00f4 H\u00ecnh Khu\u1ebfch T\u00e1n (Diffusion)</td>\n                        <td>20.15 dB</td>\n                        <td class=\"best\" style=\"color: #A78BFA;\">23.72 dB</td>\n                        <td class=\"best\" style=\"color: #A78BFA;\">+3.562 dB</td>\n                        <td class=\"best\">0.876 (+0.030)</td>\n                    </tr>\n                    <tr><td>DiffLight [6]</td><td>CNN + Diffusion</td><td>22.61 dB</td><td>23.97 dB</td><td>+1.364 dB</td><td>0.859 (+0.003)</td></tr>\n                </tbody>\n            </table>\n        </div>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">5.</span> Ph\u00e2n T\u00edch \u0110\u1ed9 L\u1ec7ch Kh\u00f4ng Gian M\u00e0u (Ablation Studies)</h3>\n        \n        <div class=\"paper-table-wrapper\">\n            <div class=\"paper-table-caption\">B\u1ea3ng 4: Ph\u00e2n t\u00edch \u0111\u1ed9 l\u1ec7ch \u1ea3nh h\u01b0\u1edfng c\u1ee7a c\u00e1c kh\u00f4ng gian m\u00e0u kh\u00e1c nhau tr\u00ean c\u00f9ng m\u1ed9t ki\u1ebfn tr\u00fac m\u1ea1ng CIDNet.</div>\n            <table class=\"paper-table\">\n                <thead>\n                    <tr><th>Kh\u00f4ng Gian M\u00e0u \u00c1p D\u1ee5ng</th><th>PSNR (dB) \u2191</th><th>SSIM \u2191</th><th>LPIPS \u2193</th></tr>\n                </thead>\n                <tbody>\n                    <tr><td>Kh\u00f4ng gian m\u00e0u chu\u1ea9n sRGB</td><td>20.06</td><td>0.825</td><td>0.137</td></tr>\n                    <tr><td>Kh\u00f4ng gian m\u00e0u HSV kinh \u0111i\u1ec3n</td><td>21.35</td><td>0.801</td><td>0.167</td></tr>\n                    <tr><td>Kh\u00f4ng gian m\u00e0u YCbCr</td><td>21.80</td><td>0.822</td><td>0.145</td></tr>\n                    <tr><td>Kh\u00f4ng gian m\u00e0u Lab</td><td>21.52</td><td>0.814</td><td>0.150</td></tr>\n                    <tr style=\"font-weight: bold; color: #A78BFA;\"><td>Kh\u00f4ng gian m\u00e0u HVI (\u0110\u1ec1 xu\u1ea5t)</td><td class=\"best\">24.11</td><td class=\"best\">0.871</td><td class=\"best\">0.108</td></tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Figure 5 -->\n        <figure class=\"paper-figure full-width\">\n            <img src=\"assets/images/papers/hvi/fig_5_p8.png\" alt=\"HVI Figure 5 Color Space Ablation\">\n            <figcaption class=\"paper-figcaption\">\n                <strong>H\u00ecnh 5: So s\u00e1nh ch\u1ea5t l\u01b0\u1ee3ng tr\u1ef1c quan gi\u1eefa 5 kh\u00f4ng gian m\u00e0u tr\u00ean LOLv2-Real.</strong> C\u00e1c kh\u00f4ng gian m\u00e0u sRGB v\u00e0 HSV xu\u1ea5t hi\u1ec7n qu\u1ea7ng nhi\u1ec5u h\u1ea1t m\u00e0u xanh \u0111\u1ecf \u1edf g\u00f3c t\u1ee7 v\u00e0 t\u01b0\u1eddng, trong khi HVI b\u1ea3o to\u00e0n \u0111\u1ed9 \u0111\u1ed3ng nh\u1ea5t m\u00e0u s\u1eafc tuy\u1ec7t h\u1ea3o.\n            </figcaption>\n        </figure>\n\n        <h3 class=\"paper-sec-heading\"><span class=\"sec-id\">6.</span> K\u1ebft Lu\u1eadn & \u0110\u1ecbnh H\u01b0\u1edbng \u0110\u1ed3 \u00c1n Cao H\u1ecdc UIT CS2203</h3>\n        <p>\n            Kh\u00f4ng gian m\u00e0u HVI \u0111\u1ea1i di\u1ec7n cho m\u1ed9t b\u01b0\u1edbc nh\u1ea3y v\u1ecdt v\u1ec1 m\u1eb7t to\u00e1n h\u1ecdc trong x\u1eed l\u00fd \u1ea3nh thi\u1ebfu s\u00e1ng: thay v\u00ec c\u1ed1 g\u1eafng b\u1eaft m\u1ea1ng n\u01a1-ron ph\u1ea3i h\u1ecdc c\u00e1ch gi\u1ea3i b\u00e0i to\u00e1n phi tuy\u1ebfn ph\u1ee9c t\u1ea1p trong kh\u00f4ng gian m\u00e0u sRGB b\u1ecb b\u1ec7n ch\u1eb7t, vi\u1ec7c chu\u1ea9n h\u00f3a d\u1eef li\u1ec7u \u0111\u1ea7u v\u00e0o sang kh\u00f4ng gian HVI gi\u00fap gi\u1ea3m t\u1ea3i t\u1edbi 80% g\u00e1nh n\u1eb7ng t\u00ednh to\u00e1n cho m\u1ea1ng.\n        </p>\n        <p>\n            \u0110\u1ed1i v\u1edbi \u0110\u1ed3 \u00e1n m\u00f4n h\u1ecdc t\u1ea1i UIT, b\u00e0i h\u1ecdc qu\u00fd b\u00e1u nh\u1ea5t l\u00e0: <strong>X\u1eed l\u00fd ti\u1ec1n k\u1ef3 d\u1eef li\u1ec7u (Data Representation) quan tr\u1ecdng kh\u00f4ng k\u00e9m g\u00ec thi\u1ebft k\u1ebf ki\u1ebfn tr\u00fac m\u1ea1ng</strong>. N\u1ebfu m\u00f4 h\u00ecnh Compact U-Net c\u1ee7a ch\u00fang ta \u0111\u01b0\u1ee3c trang b\u1ecb c\u01a1 ch\u1ebf t\u00e1ch b\u1ea1ch c\u01b0\u1eddng \u0111\u1ed9 chi\u1ebfu s\u00e1ng Max-RGB ho\u1eb7c k\u00eanh \u0111\u1ed9 s\u00e1ng \u0111\u1ed9c l\u1eadp, ch\u1ea5t l\u01b0\u1ee3ng \u1ea3nh \u0111\u1ea7u ra s\u1ebd gia t\u0103ng v\u01b0\u1ee3t b\u1eadc m\u00e0 kh\u00f4ng t\u1ed1n th\u00eam b\u1ea5t k\u1ef3 tham s\u1ed1 m\u1ea1ng n\u00e0o.\n        </p>\n    </div>\n</article>\n",
};
